/**
 * @fileoverview Real-Time Activity Stream - flowing feed of system activity
 * with severity filtering, auto-scroll, and animated item entry. Shows
 * timestamps, severity color bands, and activity messages. Caps at 100 items.
 *
 * @example
 * <loki-activity-stream api-url="http://localhost:57374" theme="dark"></loki-activity-stream>
 */

import { LokiElement } from '../core/loki-theme.js';
import { getApiClient } from '../core/loki-api-client.js';
import { registerPoll } from '../core/loki-poll-registry.js';

/** @type {Object<string, {color: string, label: string, icon: string}>} */
const SEVERITY_CONFIG = {
  info:    { color: 'var(--loki-blue, #2F71E3)',   label: 'INFO',    icon: 'i' },
  success: { color: 'var(--loki-green, #1FC5A8)',  label: 'OK',      icon: '+' },
  warning: { color: 'var(--loki-yellow, #D4A03C)', label: 'WARN',    icon: '!' },
  error:   { color: 'var(--loki-red, #C45B5B)',    label: 'ERR',     icon: 'x' },
};

const MAX_ITEMS = 100;

/**
 * @class LokiActivityStream
 * @extends LokiElement
 * @property {string} api-url - API base URL (default: window.location.origin)
 * @property {string} theme - Theme name (default: auto-detect)
 */
export class LokiActivityStream extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'theme'];
  }

  constructor() {
    super();
    this._items = [];
    this._filter = 'all';
    this._api = null;
    this._pollInterval = null;
    this._paused = false;
    this._lastTimestamp = null;
  }

  connectedCallback() {
    super.connectedCallback();
    this._setupApi();
    this._loadData();
    this._startPolling();
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this._stopPolling();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    if (name === 'api-url' && this._api) {
      this._api = getApiClient({ baseUrl: newValue });
      this._loadData();
    }
    if (name === 'theme') {
      this._applyTheme();
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });
  }

  _startPolling() {
    // Central registry (core/loki-poll-registry.js) gates this poll to the
    // active + visible section in ONE place, replacing the per-component
    // visibilitychange handler. connectedCallback already did the first load,
    // so immediate is disabled to avoid a duplicate fetch.
    this._poll = registerPoll({
      loadFn: () => this._loadData(),
      intervalMs: 3000,
      element: this,
      immediate: false,
    });
  }

  _stopPolling() {
    if (this._poll) {
      this._poll.stop();
      this._poll = null;
    }
  }

  async _loadData() {
    const api = this._api;
    try {
      const data = await api._get('/api/v2/activity');
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      const events = data.events || data.activities || [];
      if (events.length > 0) {
        const newItems = events
          .filter(e => !this._lastTimestamp || new Date(e.timestamp) > new Date(this._lastTimestamp))
          .map(e => ({
            id: e.id || crypto.randomUUID(),
            timestamp: e.timestamp || new Date().toISOString(),
            message: e.message || e.description || '',
            severity: e.severity || e.level || 'info',
            source: e.source || e.component || '',
            isNew: true,
          }));

        if (newItems.length > 0) {
          this._items = [...newItems, ...this._items].slice(0, MAX_ITEMS);
          this._lastTimestamp = newItems[0].timestamp;
          // Clear "new" flag after animation
          setTimeout(() => {
            this._items.forEach(i => i.isNew = false);
          }, 600);
        }
      }
    } catch {
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      // Generate demo data on first load if API unavailable
      if (this._items.length === 0) {
        this._items = this._getDemoItems();
      }
    }
    this.render();
  }

  _getDemoItems() {
    const now = Date.now();
    return [
      { id: '1', timestamp: new Date(now - 2000).toISOString(), message: 'Build iteration #12 started', severity: 'info', source: 'runner' },
      { id: '2', timestamp: new Date(now - 5000).toISOString(), message: 'Code review passed (3/3 reviewers)', severity: 'success', source: 'review' },
      { id: '3', timestamp: new Date(now - 8000).toISOString(), message: 'Context window at 78% capacity', severity: 'warning', source: 'context' },
      { id: '4', timestamp: new Date(now - 12000).toISOString(), message: 'Test suite completed: 42/42 passed', severity: 'success', source: 'testing' },
      { id: '5', timestamp: new Date(now - 15000).toISOString(), message: 'Verify step complete: changes checked', severity: 'info', source: 'rarv' },
    ];
  }

  _formatTime(timestamp) {
    if (!timestamp) return '';
    try {
      const date = new Date(timestamp);
      return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    } catch {
      return '';
    }
  }

  _escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  _getFilteredItems() {
    if (this._filter === 'all') return this._items;
    return this._items.filter(i => i.severity === this._filter);
  }

  _setFilter(filter) {
    this._filter = filter;
    this.render();
  }

  _bindEvents() {
    const root = this.shadowRoot;

    // Filter buttons
    root.querySelectorAll('.filter-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        this._setFilter(btn.dataset.filter);
      });
    });

    // Pause on hover
    const feed = root.querySelector('.activity-feed');
    if (feed) {
      feed.addEventListener('mouseenter', () => { this._paused = true; });
      feed.addEventListener('mouseleave', () => { this._paused = false; });
    }
  }

  _getStyles() {
    return `
      :host {
        display: block;
      }

      .stream-container {
        font-family: var(--loki-font-family, 'Inter', -apple-system, sans-serif);
        color: var(--loki-text-primary, #201515);
      }

      .header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        margin-bottom: 12px;
      }

      .title {
        font-size: 16px;
        font-weight: 600;
        margin: 0;
      }

      .filter-bar {
        display: flex;
        gap: 4px;
        background: var(--loki-bg-tertiary, #ECEAE3);
        border-radius: 5px;
        padding: 2px;
      }

      .filter-btn {
        padding: 4px 10px;
        border: none;
        background: none;
        color: var(--loki-text-muted, #939084);
        cursor: pointer;
        border-radius: 4px;
        font-size: 11px;
        font-weight: 500;
        transition: all 0.2s;
        font-family: inherit;
        text-transform: uppercase;
        letter-spacing: 0.03em;
      }

      .filter-btn:hover {
        color: var(--loki-text-secondary, #36342E);
      }

      .filter-btn.active {
        background: var(--loki-accent, #553DE9);
        color: white;
      }

      .activity-feed {
        background: var(--loki-bg-card, #ffffff);
        border: 1px solid var(--loki-border, #ECEAE3);
        border-radius: 5px;
        max-height: 400px;
        overflow-y: auto;
        overflow-x: hidden;
      }

      .activity-item {
        display: flex;
        align-items: stretch;
        gap: 0;
        border-bottom: 1px solid var(--loki-border, #ECEAE3);
        transition: background 0.2s, opacity 0.3s;
        animation: slideIn 0.3s ease-out;
      }

      .activity-item:last-child {
        border-bottom: none;
      }

      .activity-item:hover {
        background: var(--loki-bg-hover, #F3EFE9);
      }

      .activity-item.new-item {
        animation: slideInFromRight 0.4s ease-out;
      }

      @keyframes slideInFromRight {
        from {
          transform: translateX(30px);
          opacity: 0;
        }
        to {
          transform: translateX(0);
          opacity: 1;
        }
      }

      @keyframes slideIn {
        from { opacity: 0; }
        to { opacity: 1; }
      }

      .severity-band {
        width: 4px;
        flex-shrink: 0;
      }

      .item-content {
        display: flex;
        align-items: center;
        gap: 10px;
        padding: 10px 14px;
        flex: 1;
        min-width: 0;
      }

      .severity-icon {
        width: 22px;
        height: 22px;
        border-radius: 4px;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 11px;
        font-weight: 700;
        color: white;
        flex-shrink: 0;
        font-family: 'JetBrains Mono', monospace;
      }

      .item-time {
        font-size: 11px;
        font-family: 'JetBrains Mono', monospace;
        color: var(--loki-text-muted, #939084);
        white-space: nowrap;
        min-width: 70px;
      }

      .item-message {
        flex: 1;
        font-size: 13px;
        color: var(--loki-text-primary, #201515);
        line-height: 1.4;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
      }

      .item-source {
        font-size: 10px;
        font-family: 'JetBrains Mono', monospace;
        color: var(--loki-text-muted, #939084);
        background: var(--loki-bg-tertiary, #ECEAE3);
        padding: 2px 8px;
        border-radius: 5px;
        white-space: nowrap;
        flex-shrink: 0;
      }

      .empty-state {
        text-align: center;
        padding: 32px 16px;
        color: var(--loki-text-muted, #939084);
        font-size: 13px;
      }

      .count-badge {
        font-size: 11px;
        font-family: 'JetBrains Mono', monospace;
        color: var(--loki-text-muted, #939084);
        margin-left: 4px;
      }

      .pause-indicator {
        font-size: 10px;
        color: var(--loki-text-muted, #939084);
        text-transform: uppercase;
        letter-spacing: 0.05em;
        padding: 2px 8px;
        background: var(--loki-bg-tertiary, #ECEAE3);
        border-radius: 4px;
      }

      ::-webkit-scrollbar { width: 6px; }
      ::-webkit-scrollbar-track { background: var(--loki-bg-primary, #FFFEFB); }
      ::-webkit-scrollbar-thumb { background: var(--loki-border, #ECEAE3); border-radius: 3px; }
      ::-webkit-scrollbar-thumb:hover { background: var(--loki-border-light, #C5C0B1); }
    `;
  }

  render() {
    const s = this.shadowRoot;
    if (!s) return;

    const filtered = this._getFilteredItems();
    const severities = ['all', 'info', 'success', 'warning', 'error'];

    const filterButtons = severities.map(sev => {
      const isActive = this._filter === sev;
      const label = sev === 'all' ? 'All' : (SEVERITY_CONFIG[sev]?.label || sev);
      return `<button class="filter-btn ${isActive ? 'active' : ''}" data-filter="${sev}">${label}</button>`;
    }).join('');

    let feedContent;
    if (filtered.length === 0) {
      feedContent = '<div class="empty-state">No activity yet. Updates will stream here as your build runs.</div>';
    } else {
      feedContent = filtered.map(item => {
        const cfg = SEVERITY_CONFIG[item.severity] || SEVERITY_CONFIG.info;
        return `
          <div class="activity-item ${item.isNew ? 'new-item' : ''}">
            <div class="severity-band" style="background: ${cfg.color};"></div>
            <div class="item-content">
              <div class="severity-icon" style="background: ${cfg.color};">${cfg.icon}</div>
              <span class="item-time">${this._formatTime(item.timestamp)}</span>
              <span class="item-message">${this._escapeHtml(item.message)}</span>
              ${item.source ? `<span class="item-source">${this._escapeHtml(item.source)}</span>` : ''}
            </div>
          </div>
        `;
      }).join('');
    }

    s.innerHTML = `
      <style>${this.getBaseStyles()}${this._getStyles()}</style>
      <div class="stream-container">
        <div class="header">
          <h3 class="title">Activity Stream <span class="count-badge">${this._items.length}</span></h3>
          <div class="filter-bar">${filterButtons}</div>
        </div>
        <div class="activity-feed">
          ${feedContent}
        </div>
      </div>
    `;

    this._bindEvents();

    // Auto-scroll to top (newest items) unless paused
    if (!this._paused) {
      const feed = s.querySelector('.activity-feed');
      if (feed) feed.scrollTop = 0;
    }
  }
}

if (!customElements.get('loki-activity-stream')) {
  customElements.define('loki-activity-stream', LokiActivityStream);
}

export default LokiActivityStream;

/**
 * @fileoverview Agent Performance Leaderboard - ranked list of agents by
 * performance metrics including tasks completed, average quality score,
 * and speed. Highlights top 3 with gold/silver/bronze indicators and
 * shows rank change arrows.
 *
 * @example
 * <loki-agent-leaderboard api-url="http://localhost:57374" theme="dark"></loki-agent-leaderboard>
 */

import { LokiElement } from '../core/loki-theme.js';
import { getApiClient } from '../core/loki-api-client.js';
import { registerPoll } from '../core/loki-poll-registry.js';

const RANK_COLORS = {
  1: { bg: 'rgba(212, 160, 60, 0.15)', border: '#D4A03C', label: '1st' },
  2: { bg: 'rgba(147, 144, 132, 0.15)', border: '#939084', label: '2nd' },
  3: { bg: 'rgba(196, 130, 91, 0.15)', border: '#C4825B', label: '3rd' },
};

/**
 * @class LokiAgentLeaderboard
 * @extends LokiElement
 * @property {string} api-url - API base URL (default: window.location.origin)
 * @property {string} theme - Theme name (default: auto-detect)
 */
export class LokiAgentLeaderboard extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'theme'];
  }

  constructor() {
    super();
    this._agents = [];
    this._expandedAgent = null;
    this._api = null;
    this._pollInterval = null;
    this._previousRanks = {};
  }

  connectedCallback() {
    super.connectedCallback();
    this._setupApi();
    this._loadData();
    this._startPolling();
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this._stopPolling();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    if (name === 'api-url' && this._api) {
      this._api = getApiClient({ baseUrl: newValue });
      this._loadData();
    }
    if (name === 'theme') {
      this._applyTheme();
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });
  }

  _startPolling() {
    // Central registry (core/loki-poll-registry.js) gates this poll to the
    // active + visible section in ONE place, so a hidden tab or background
    // section does not fetch. connectedCallback already did the first load,
    // so immediate is disabled to avoid a duplicate fetch.
    this._poll = registerPoll({
      loadFn: () => this._loadData(),
      intervalMs: 10000,
      element: this,
      immediate: false,
    });
  }

  _stopPolling() {
    if (this._poll) {
      this._poll.stop();
      this._poll = null;
    }
  }

  async _loadData() {
    const api = this._api;
    try {
      const data = await api._get('/api/v2/agents/leaderboard');
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      const agents = data.agents || [];
      // Track rank changes
      const newRanks = {};
      agents.forEach((a, i) => {
        newRanks[a.type || a.name] = i + 1;
      });
      this._previousRanks = { ...this._currentRanks || {} };
      this._currentRanks = newRanks;
      this._agents = agents;
    } catch {
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      if (this._agents.length === 0) {
        this._agents = this._getDemoData();
        this._currentRanks = {};
        this._agents.forEach((a, i) => {
          this._currentRanks[a.type] = i + 1;
        });
        this._previousRanks = {};
      }
    }
    this.render();
  }

  _getDemoData() {
    return [
      { type: 'code-generator',    name: 'Code Generator',     tasks: 24, quality: 9.2, speed: 'fast',   cost_usd: 2.40 },
      { type: 'test-writer',       name: 'Test Writer',        tasks: 18, quality: 9.0, speed: 'fast',   cost_usd: 1.20 },
      { type: 'code-reviewer',     name: 'Code Reviewer',      tasks: 15, quality: 8.8, speed: 'medium', cost_usd: 1.80 },
      { type: 'architect',         name: 'Architect',          tasks: 8,  quality: 9.5, speed: 'slow',   cost_usd: 3.10 },
      { type: 'debugger',          name: 'Debugger',           tasks: 12, quality: 8.5, speed: 'fast',   cost_usd: 0.95 },
      { type: 'doc-writer',        name: 'Documentation',      tasks: 10, quality: 8.3, speed: 'fast',   cost_usd: 0.60 },
    ];
  }

  _getRankChange(agentType) {
    const current = this._currentRanks?.[agentType];
    const prev = this._previousRanks?.[agentType];
    if (current == null || prev == null) return 0;
    return prev - current; // positive = moved up
  }

  _escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  _toggleAgent(agentType) {
    this._expandedAgent = this._expandedAgent === agentType ? null : agentType;
    this.render();
  }

  _bindEvents() {
    const root = this.shadowRoot;
    root.querySelectorAll('.agent-row').forEach(row => {
      row.addEventListener('click', () => {
        this._toggleAgent(row.dataset.agent);
      });
    });
  }

  _getQualityColor(score) {
    if (score >= 9) return 'var(--loki-green, #1FC5A8)';
    if (score >= 8) return 'var(--loki-blue, #2F71E3)';
    if (score >= 7) return 'var(--loki-yellow, #D4A03C)';
    return 'var(--loki-red, #C45B5B)';
  }

  _getSpeedLabel(speed) {
    if (speed === 'fast') return { label: 'Fast', color: 'var(--loki-green, #1FC5A8)' };
    if (speed === 'medium') return { label: 'Medium', color: 'var(--loki-yellow, #D4A03C)' };
    return { label: 'Slow', color: 'var(--loki-red, #C45B5B)' };
  }

  _getStyles() {
    return `
      :host {
        display: block;
      }

      .leaderboard-container {
        font-family: var(--loki-font-family, 'Inter', -apple-system, sans-serif);
        color: var(--loki-text-primary, #201515);
      }

      .header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        margin-bottom: 16px;
      }

      .title {
        font-size: 16px;
        font-weight: 600;
        margin: 0;
      }

      .agent-count {
        font-size: 12px;
        color: var(--loki-text-muted, #939084);
      }

      .leaderboard-table {
        background: var(--loki-bg-card, #ffffff);
        border: 1px solid var(--loki-border, #ECEAE3);
        border-radius: 5px;
        overflow: hidden;
      }

      .table-header {
        display: grid;
        grid-template-columns: 48px 1fr 80px 80px 80px;
        padding: 10px 14px;
        border-bottom: 1px solid var(--loki-border, #ECEAE3);
        background: var(--loki-bg-secondary, #F8F4F0);
      }

      .table-header span {
        font-size: 10px;
        font-weight: 600;
        text-transform: uppercase;
        letter-spacing: 0.05em;
        color: var(--loki-text-muted, #939084);
      }

      .agent-row {
        display: grid;
        grid-template-columns: 48px 1fr 80px 80px 80px;
        padding: 12px 14px;
        border-bottom: 1px solid var(--loki-border, #ECEAE3);
        cursor: pointer;
        transition: all 0.2s;
        align-items: center;
      }

      .agent-row:last-child {
        border-bottom: none;
      }

      .agent-row:hover {
        background: var(--loki-bg-hover, #F3EFE9);
      }

      .agent-row.top-3 {
        border-left: 3px solid transparent;
      }

      .rank-cell {
        display: flex;
        align-items: center;
        gap: 4px;
      }

      .rank-number {
        font-size: 15px;
        font-weight: 700;
        font-family: 'JetBrains Mono', monospace;
        min-width: 20px;
      }

      .rank-badge {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 28px;
        height: 28px;
        border-radius: 50%;
        font-size: 12px;
        font-weight: 700;
        font-family: 'JetBrains Mono', monospace;
      }

      .rank-change {
        font-size: 10px;
        font-weight: 600;
      }

      .rank-up {
        color: var(--loki-green, #1FC5A8);
      }

      .rank-down {
        color: var(--loki-red, #C45B5B);
      }

      .agent-name-cell {
        display: flex;
        flex-direction: column;
        gap: 2px;
      }

      .agent-name {
        font-size: 13px;
        font-weight: 600;
        color: var(--loki-text-primary, #201515);
      }

      .agent-type {
        font-size: 10px;
        font-family: 'JetBrains Mono', monospace;
        color: var(--loki-text-muted, #939084);
      }

      .metric-cell {
        font-size: 13px;
        font-family: 'JetBrains Mono', monospace;
        font-weight: 600;
      }

      .quality-score {
        display: inline-flex;
        align-items: center;
        gap: 4px;
      }

      .quality-bar {
        width: 40px;
        height: 4px;
        background: var(--loki-bg-tertiary, #ECEAE3);
        border-radius: 2px;
        overflow: hidden;
      }

      .quality-fill {
        height: 100%;
        border-radius: 2px;
      }

      .speed-badge {
        font-size: 10px;
        font-weight: 600;
        padding: 2px 8px;
        border-radius: 4px;
        text-transform: uppercase;
        letter-spacing: 0.03em;
      }

      .agent-detail {
        grid-column: 1 / -1;
        padding: 12px 14px;
        background: var(--loki-bg-secondary, #F8F4F0);
        border-top: 1px solid var(--loki-border, #ECEAE3);
        display: grid;
        grid-template-columns: 1fr 1fr 1fr;
        gap: 12px;
        animation: expandDetail 0.2s ease-out;
      }

      @keyframes expandDetail {
        from { opacity: 0; max-height: 0; }
        to { opacity: 1; max-height: 100px; }
      }

      .detail-metric {
        display: flex;
        flex-direction: column;
        gap: 2px;
      }

      .detail-label {
        font-size: 10px;
        font-weight: 600;
        text-transform: uppercase;
        letter-spacing: 0.05em;
        color: var(--loki-text-muted, #939084);
      }

      .detail-value {
        font-size: 13px;
        font-family: 'JetBrains Mono', monospace;
        color: var(--loki-text-primary, #201515);
      }

      .empty-state {
        text-align: center;
        padding: 32px 16px;
        color: var(--loki-text-muted, #939084);
        font-size: 13px;
      }
    `;
  }

  render() {
    const s = this.shadowRoot;
    if (!s) return;

    if (this._agents.length === 0) {
      s.innerHTML = `
        <style>${this.getBaseStyles()}${this._getStyles()}</style>
        <div class="leaderboard-container">
          <div class="header">
            <h3 class="title">Agent Leaderboard</h3>
          </div>
          <div class="empty-state">No agent performance data available</div>
        </div>
      `;
      return;
    }

    const rows = this._agents.map((agent, idx) => {
      const rank = idx + 1;
      const rankCfg = RANK_COLORS[rank];
      const agentKey = agent.type || agent.name;
      const rankChange = this._getRankChange(agentKey);
      const isExpanded = this._expandedAgent === agentKey;
      const qualityColor = this._getQualityColor(agent.quality);
      const speedCfg = this._getSpeedLabel(agent.speed);
      const qualityPct = ((agent.quality || 0) / 10) * 100;

      let rankHtml;
      if (rankCfg) {
        rankHtml = `<div class="rank-badge" style="background: ${rankCfg.bg}; color: ${rankCfg.border};">${rank}</div>`;
      } else {
        rankHtml = `<span class="rank-number" style="color: var(--loki-text-muted);">${rank}</span>`;
      }

      let rankChangeHtml = '';
      if (rankChange > 0) {
        rankChangeHtml = `<span class="rank-change rank-up">+${rankChange}</span>`;
      } else if (rankChange < 0) {
        rankChangeHtml = `<span class="rank-change rank-down">${rankChange}</span>`;
      }

      const detailHtml = isExpanded ? `
        <div class="agent-detail">
          <div class="detail-metric">
            <span class="detail-label">Total Cost</span>
            <span class="detail-value">$${(agent.cost_usd || 0).toFixed(2)}</span>
          </div>
          <div class="detail-metric">
            <span class="detail-label">Avg Time/Task</span>
            <span class="detail-value">${agent.avg_time || '--'}</span>
          </div>
          <div class="detail-metric">
            <span class="detail-label">Success Rate</span>
            <span class="detail-value">${agent.success_rate != null ? agent.success_rate + '%' : '--'}</span>
          </div>
        </div>
      ` : '';

      return `
        <div class="agent-row ${rank <= 3 ? 'top-3' : ''}" data-agent="${this._escapeHtml(agentKey)}"
             style="${rankCfg ? 'border-left-color: ' + rankCfg.border + ';' : ''}">
          <div class="rank-cell">${rankHtml}${rankChangeHtml}</div>
          <div class="agent-name-cell">
            <span class="agent-name">${this._escapeHtml(agent.name || agent.type)}</span>
            <span class="agent-type">${this._escapeHtml(agent.type || '')}</span>
          </div>
          <div class="metric-cell">${agent.tasks || 0}</div>
          <div class="metric-cell">
            <div class="quality-score">
              <span style="color: ${qualityColor};">${(agent.quality || 0).toFixed(1)}</span>
              <div class="quality-bar"><div class="quality-fill" style="width: ${qualityPct}%; background: ${qualityColor};"></div></div>
            </div>
          </div>
          <div class="metric-cell">
            <span class="speed-badge" style="background: ${speedCfg.color}15; color: ${speedCfg.color};">${speedCfg.label}</span>
          </div>
        </div>
        ${detailHtml}
      `;
    }).join('');

    s.innerHTML = `
      <style>${this.getBaseStyles()}${this._getStyles()}</style>
      <div class="leaderboard-container">
        <div class="header">
          <h3 class="title">Agent Leaderboard</h3>
          <span class="agent-count">${this._agents.length} agents</span>
        </div>
        <div class="leaderboard-table">
          <div class="table-header">
            <span>Rank</span>
            <span>Agent</span>
            <span>Tasks</span>
            <span>Quality</span>
            <span>Speed</span>
          </div>
          ${rows}
        </div>
      </div>
    `;

    this._bindEvents();
  }
}

if (!customElements.get('loki-agent-leaderboard')) {
  customElements.define('loki-agent-leaderboard', LokiAgentLeaderboard);
}

export default LokiAgentLeaderboard;

/**
 * @fileoverview Loki Analytics Dashboard - cross-provider analytics with
 * activity heatmap, tool usage breakdown, velocity metrics, and provider
 * comparison. Uses existing API endpoints with client-side aggregation.
 * No chart libraries - pure CSS visualizations.
 *
 * @example
 * <loki-analytics api-url="http://localhost:57374"></loki-analytics>
 */

import { LokiElement } from '../core/loki-theme.js';
import { getApiClient } from '../core/loki-api-client.js';
import { registerPoll } from '../core/loki-poll-registry.js';

/** Map model name fragments to provider -- ordered longest-first to avoid false prefix matches */
const MODEL_TO_PROVIDER = [
  ['claude-opus', 'claude'], ['claude-sonnet', 'claude'], ['claude-haiku', 'claude'],
  ['opus', 'claude'], ['sonnet', 'claude'], ['haiku', 'claude'], ['claude', 'claude'],
  ['gpt-4', 'codex'], ['gpt-5', 'codex'], ['gpt', 'codex'], ['codex', 'codex'], ['o1', 'codex'], ['o3', 'codex'],
  ['cline', 'cline'],
  ['aider', 'aider'],
];

/**
 * Map RARV iteration to tier (matches autonomy/run.sh get_rarv_tier).
 * Returns { tier: 'planning'|'development'|'fast', model: 'opus'|'sonnet'|'haiku' }
 */
function getRARVTier(iteration) {
  if (iteration == null) return null;
  const step = iteration % 4;
  switch (step) {
    case 0: return { tier: 'planning', model: 'opus', provider: 'claude' };
    case 1: return { tier: 'development', model: 'sonnet', provider: 'claude' };
    case 2: return { tier: 'development', model: 'sonnet', provider: 'claude' };
    case 3: return { tier: 'fast', model: 'haiku', provider: 'claude' };
    default: return { tier: 'development', model: 'sonnet', provider: 'claude' };
  }
}

function classifyProvider(modelName, iteration) {
  // Use RARV tier mapping when iteration data is available
  if (iteration != null) {
    const rarv = getRARVTier(iteration);
    if (rarv) return rarv.provider;
  }
  const lower = (modelName || '').toLowerCase();
  for (const [key, provider] of MODEL_TO_PROVIDER) {
    if (lower.includes(key)) return provider;
  }
  return 'unknown';
}

/**
 * @class LokiAnalytics
 * @extends LokiElement
 */
export class LokiAnalytics extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'theme'];
  }

  constructor() {
    super();
    this._api = null;
    this._pollInterval = null;
    this._activeTab = 'heatmap';
    this._activity = [];
    this._tools = [];
    this._cost = {};
    this._context = {};
    this._trends = [];
    this._toolTimeRange = '7d';
    this._connected = false;
    this._loading = false;
    this._loadedOnce = false;
  }

  connectedCallback() {
    super.connectedCallback();
    this._setupApi();
    this._loadData();
    this._startPolling();
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this._stopPolling();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    if (name === 'api-url' && this._api) {
      this._api = getApiClient({ baseUrl: newValue });
      this._loadData();
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });
  }

  async _fetchActivity(api = this._api) {
    const baseUrl = api.baseUrl || window.location.origin;
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 10000);
    try {
      const resp = await fetch(`${baseUrl}/api/activity?limit=1000`, { signal: controller.signal });
      clearTimeout(timeout);
      if (!resp.ok) throw new Error(`Activity API ${resp.status}`);
      return resp.json();
    } catch (e) {
      clearTimeout(timeout);
      throw e;
    }
  }

  async _loadData() {
    if (!this.isConnected || this._loading) return;
    // Capture the api instance so a mid-flight api-url switch can be detected.
    const api = this._api;
    this._loading = true;

    try {
      const results = await Promise.allSettled([
        this._fetchActivity(api),
        api.getToolEfficiency(50),
        api.getCost(),
        api.getContext(),
        api.getLearningTrends({ timeRange: this._toolTimeRange }),
      ]);

      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;

      if (results[0].status === 'fulfilled') this._activity = results[0].value || [];
      if (results[1].status === 'fulfilled') this._tools = results[1].value || [];
      if (results[2].status === 'fulfilled') this._cost = results[2].value || {};
      if (results[3].status === 'fulfilled') this._context = results[3].value || {};
      if (results[4].status === 'fulfilled') {
        const trendsRaw = results[4].value || {};
        this._trends = Array.isArray(trendsRaw) ? trendsRaw : (trendsRaw.dataPoints || []);
      }

      this._connected = results.some(r => r.status === 'fulfilled');
      this._loadedOnce = true;
      this.render();
    } finally {
      this._loading = false;
    }
  }

  /**
   * True when at least one analytics source has real data. Used to decide
   * between the branded empty state and the data views. Honest: never shows
   * fabricated charts for a fresh repo.
   */
  _hasAnyData() {
    const activity = Array.isArray(this._activity) ? this._activity.length : 0;
    const tools = Array.isArray(this._tools) ? this._tools.length : 0;
    const byModel = (this._cost && this._cost.by_model) ? Object.keys(this._cost.by_model).length : 0;
    const ctx = this._context || {};
    const totals = ctx.totals || {};
    const iter = totals.iterations_tracked || ctx.total_iterations || ctx.iteration || 0;
    return activity > 0 || tools > 0 || byModel > 0 || iter > 0;
  }

  _startPolling() {
    // Central registry (core/loki-poll-registry.js) gates this poll to the
    // active + visible section in ONE place, replacing the per-component
    // visibilitychange handler. connectedCallback already did the first load,
    // so immediate is disabled to avoid a duplicate fetch.
    this._poll = registerPoll({
      loadFn: () => this._loadData(),
      intervalMs: 30000,
      element: this,
      immediate: false,
    });
  }

  _stopPolling() {
    if (this._poll) {
      this._poll.stop();
      this._poll = null;
    }
  }

  // --- Heatmap computation ---

  _computeHeatmap() {
    const counts = {};
    const items = Array.isArray(this._activity) ? this._activity : [];

    for (const entry of items) {
      const ts = entry.timestamp || entry.ts || entry.created_at;
      if (!ts) continue;
      const d = new Date(ts);
      if (isNaN(d.getTime())) continue;
      const key = this._localDateKey(d);
      counts[key] = (counts[key] || 0) + 1;
    }

    // Build 52-week grid ending today
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const dayOfWeek = today.getDay(); // 0=Sun
    const endDate = new Date(today);
    const startDate = new Date(today);
    startDate.setDate(startDate.getDate() - (52 * 7 + dayOfWeek));

    const cells = [];
    const current = new Date(startDate);
    let maxCount = 0;
    while (current <= endDate) {
      const key = this._localDateKey(current);
      const count = counts[key] || 0;
      if (count > maxCount) maxCount = count;
      cells.push({ date: key, count, day: current.getDay() });
      current.setDate(current.getDate() + 1);
    }

    return { cells, maxCount };
  }

  _getHeatmapLevel(count, maxCount) {
    if (count === 0 || maxCount === 0) return 0;
    const ratio = count / maxCount;
    if (ratio <= 0.25) return 1;
    if (ratio <= 0.50) return 2;
    if (ratio <= 0.75) return 3;
    return 4;
  }

  _renderHeatmap() {
    const { cells, maxCount } = this._computeHeatmap();
    const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    const dayLabels = ['', 'Mon', '', 'Wed', '', 'Fri', ''];

    // Compute month label positions (place at the week containing month's first day)
    const monthPositions = [];
    let lastMonth = -1;
    let weekCol = -1;
    for (let i = 0; i < cells.length; i++) {
      if (cells[i].day === 0) weekCol++;
      const month = new Date(cells[i].date).getMonth();
      if (month !== lastMonth) {
        monthPositions.push({ month: months[month], col: Math.max(weekCol, 1) });
        lastMonth = month;
      }
    }

    const monthLabelsHTML = monthPositions.map(m =>
      `<span class="heatmap-month" style="grid-column: ${m.col}">${m.month}</span>`
    ).join('');

    const cellsHTML = cells.map(c => {
      const level = this._getHeatmapLevel(c.count, maxCount);
      return `<div class="heatmap-cell level-${level}" title="${c.date}: ${c.count} activities"></div>`;
    }).join('');

    const dayLabelsHTML = dayLabels.map(d =>
      `<span class="heatmap-day-label">${d}</span>`
    ).join('');

    return `
      <div class="heatmap-container">
        <div class="heatmap-months">${monthLabelsHTML}</div>
        <div class="heatmap-body">
          <div class="heatmap-day-labels">${dayLabelsHTML}</div>
          <div class="heatmap-grid">${cellsHTML}</div>
        </div>
        <div class="heatmap-legend">
          <span class="heatmap-legend-label">Less</span>
          <div class="heatmap-cell level-0"></div>
          <div class="heatmap-cell level-1"></div>
          <div class="heatmap-cell level-2"></div>
          <div class="heatmap-cell level-3"></div>
          <div class="heatmap-cell level-4"></div>
          <span class="heatmap-legend-label">More</span>
        </div>
      </div>
    `;
  }

  // --- Tool usage computation ---

  _computeToolUsage() {
    const tools = Array.isArray(this._tools) ? this._tools : [];
    // Aggregate by tool name
    const byName = {};
    for (const t of tools) {
      const name = t.tool || t.name || t.tool_name || (t.data && t.data.tool_name) || 'unknown';
      const count = t.count ?? t.calls ?? t.frequency ?? (t.data && t.data.count) ?? 1;
      byName[name] = (byName[name] || 0) + count;
    }

    return Object.entries(byName)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 15);
  }

  _renderToolUsage() {
    const tools = this._computeToolUsage();
    const maxCount = tools.length > 0 ? tools[0][1] : 0;

    if (tools.length === 0) {
      return '<div class="empty-state">No tool usage data available</div>';
    }

    const barsHTML = tools.map(([name, count]) => {
      const pct = maxCount > 0 ? (count / maxCount) * 100 : 0;
      return `
        <div class="tool-row">
          <span class="tool-name" title="${this._esc(name)}">${this._esc(name)}</span>
          <div class="tool-bar-track">
            <div class="tool-bar-fill" style="width: ${pct.toFixed(1)}%"></div>
          </div>
          <span class="tool-count">${count}</span>
        </div>
      `;
    }).join('');

    return '<div class="tool-bars">' + barsHTML + '</div>';
  }

  // --- Velocity computation ---

  _computeVelocity() {
    const ctx = this._context || {};
    const iterations = ctx.per_iteration || ctx.iterations || [];
    const totalIterations = Array.isArray(iterations) && iterations.length > 0
      ? iterations.length
      : ((ctx.totals && ctx.totals.iterations_tracked) || ctx.total_iterations || 0);

    // Calculate iterations/hour from timestamps
    let iterPerHour = 0;
    if (Array.isArray(iterations) && iterations.length >= 2) {
      const timestamps = iterations
        .map(it => new Date(it.timestamp || it.started_at || it.ts).getTime())
        .filter(t => !isNaN(t))
        .sort((a, b) => a - b);

      if (timestamps.length >= 2) {
        const spanHours = (timestamps[timestamps.length - 1] - timestamps[0]) / 3600000;
        if (spanHours > 0) {
          iterPerHour = Math.max(timestamps.length - 1, 1) / spanHours;
        }
      }
    }

    // Build hourly sparkline from trends or iterations
    const hourlyBuckets = [];
    const trendData = Array.isArray(this._trends) ? this._trends : [];

    if (trendData.length > 0) {
      for (const bucket of trendData.slice(-24)) {
        hourlyBuckets.push(bucket.count ?? bucket.value ?? 0);
      }
    } else if (Array.isArray(iterations) && iterations.length > 0) {
      // Bucket by hour
      const bucketMap = {};
      for (const it of iterations) {
        const ts = it.timestamp || it.started_at || it.ts;
        if (!ts) continue;
        const d = new Date(ts);
        const hourKey = d.toISOString().slice(0, 13);
        bucketMap[hourKey] = (bucketMap[hourKey] || 0) + 1;
      }
      const keys = Object.keys(bucketMap).sort().slice(-24);
      for (const k of keys) hourlyBuckets.push(bucketMap[k]);
    }

    return { iterPerHour, totalIterations, hourlyBuckets };
  }

  _renderVelocity() {
    const { iterPerHour, totalIterations, hourlyBuckets } = this._computeVelocity();

    const maxBucket = Math.max(1, ...hourlyBuckets);
    const sparkBars = hourlyBuckets.length > 0
      ? hourlyBuckets.map(v => {
          const pct = (v / maxBucket) * 100;
          return `<div class="spark-bar" style="height: ${Math.max(2, pct)}%" title="${v}"></div>`;
        }).join('')
      : '<div class="empty-state" style="padding: 12px">No trend data</div>';

    const trendFilterHTML = `
      <div class="tool-filter">
        <select class="tool-time-select" id="tool-time-range">
          <option value="1h" ${this._toolTimeRange === '1h' ? 'selected' : ''}>Trend: Last hour</option>
          <option value="24h" ${this._toolTimeRange === '24h' ? 'selected' : ''}>Trend: Last 24h</option>
          <option value="7d" ${this._toolTimeRange === '7d' ? 'selected' : ''}>Trend: Last 7 days</option>
          <option value="30d" ${this._toolTimeRange === '30d' ? 'selected' : ''}>Trend: Last 30 days</option>
        </select>
      </div>
    `;

    return `
      ${trendFilterHTML}
      <div class="velocity-cards">
        <div class="velocity-card">
          <div class="velocity-label">Iterations / Hour</div>
          <div class="velocity-value">${iterPerHour.toFixed(1)}</div>
        </div>
        <div class="velocity-card">
          <div class="velocity-label">Total Iterations</div>
          <div class="velocity-value">${totalIterations}</div>
        </div>
      </div>
      <div class="sparkline-container">
        <div class="sparkline-label">Activity Trend (hourly)</div>
        <div class="sparkline">${sparkBars}</div>
      </div>
    `;
  }

  // --- Provider comparison ---

  _computeProviders() {
    const byModel = this._cost.by_model || {};
    const providers = {};

    for (const [model, data] of Object.entries(byModel)) {
      const prov = classifyProvider(model);
      if (!providers[prov]) {
        providers[prov] = { cost: 0, tokens: 0, iterations: 0, models: [] };
      }
      const cost = data.cost_usd || 0;
      const tokens = (data.input_tokens || 0) + (data.output_tokens || 0);
      providers[prov].cost += cost;
      providers[prov].tokens += tokens;
      providers[prov].models.push(model);
    }

    // Estimate iterations from context
    const totals = this._context.totals || {};
    const totalIter = totals.iterations_tracked || this._context.total_iterations || this._context.iteration || 0;
    const totalCost = this._cost.estimated_cost_usd || 0;

    for (const prov of Object.values(providers)) {
      if (totalCost > 0 && totalIter > 0) {
        const costShare = prov.cost / totalCost;
        prov.iterations = Math.round(costShare * totalIter);
      }
    }

    return providers;
  }

  _renderProviders() {
    const providers = this._computeProviders();
    const providerConfig = {
      claude: { label: 'Claude', color: 'var(--loki-accent)' },
      codex: { label: 'Codex', color: 'var(--loki-success)' },
      cline: { label: 'Cline', color: 'var(--loki-info)' },
      aider: { label: 'Aider', color: 'var(--loki-blue)' },
      unknown: { label: 'Other', color: 'var(--loki-text-muted)' },
    };

    const entries = Object.entries(providers);
    if (entries.length === 0) {
      return '<div class="empty-state">No provider activity yet. Start a build to compare providers side by side.</div>';
    }

    return `
      <div class="provider-grid">
        ${entries.map(([key, data]) => {
          const cfg = providerConfig[key] || providerConfig.unknown;
          const costPerIter = data.iterations > 0 ? (data.cost / data.iterations).toFixed(4) : '--';
          const tokensPerIter = data.iterations > 0 ? Math.round(data.tokens / data.iterations).toLocaleString() : '--';

          return `
            <div class="provider-card">
              <div class="provider-accent" style="background: ${cfg.color}"></div>
              <div class="provider-body">
                <div class="provider-name">${cfg.label}</div>
                <div class="provider-stat">
                  <span class="provider-stat-label">Total Cost</span>
                  <span class="provider-stat-value">${data.cost > 0 ? '$' + data.cost.toFixed(2) : '$0.00'}</span>
                </div>
                <div class="provider-stat">
                  <span class="provider-stat-label">Cost / Iteration</span>
                  <span class="provider-stat-value">${costPerIter !== '--' ? '$' + costPerIter : costPerIter}</span>
                </div>
                <div class="provider-stat">
                  <span class="provider-stat-label">Tokens / Iteration</span>
                  <span class="provider-stat-value">${tokensPerIter}</span>
                </div>
                <div class="provider-stat">
                  <span class="provider-stat-label">Total Tokens</span>
                  <span class="provider-stat-value">${(data.tokens ?? 0).toLocaleString()}</span>
                </div>
                <div class="provider-models">${data.models.map(m => this._esc(m)).join(', ')}</div>
              </div>
            </div>
          `;
        }).join('')}
      </div>
    `;
  }

  _esc(str) {
    if (!str) return '';
    return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#x27;');
  }

  _localDateKey(d) {
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  }

  _handleTabClick(e) {
    const tab = e.target.closest('[data-tab]');
    if (!tab) return;
    this._activeTab = tab.dataset.tab;
    this.render();
  }

  _handleTimeRangeChange(e) {
    this._toolTimeRange = e.target.value;
    this._loadData();
  }

  render() {
    const tabs = [
      { id: 'heatmap', label: 'Activity', icon: '<svg viewBox="0 0 24 24"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg>' },
      { id: 'tools', label: 'Tools', icon: '<svg viewBox="0 0 24 24"><path d="M14.7 6.3a1 1 0 000 1.4l1.6 1.6a1 1 0 001.4 0l3.77-3.77a6 6 0 01-7.94 7.94l-6.91 6.91a2.12 2.12 0 01-3-3l6.91-6.91a6 6 0 017.94-7.94l-3.76 3.76z"/></svg>' },
      { id: 'velocity', label: 'Velocity', icon: '<svg viewBox="0 0 24 24"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg>' },
      { id: 'providers', label: 'Providers', icon: '<svg viewBox="0 0 24 24"><line x1="18" y1="20" x2="18" y2="10"/><line x1="12" y1="20" x2="12" y2="4"/><line x1="6" y1="20" x2="6" y2="14"/></svg>' },
    ];

