        `}
      </div>
    `;

    // Bind event listeners
    this.shadowRoot.querySelectorAll('[data-tab]').forEach(btn => {
      btn.addEventListener('click', (e) => this._handleTabClick(e));
    });

    const timeSelect = this.shadowRoot.getElementById('tool-time-range');
