          flex-direction: column;
          gap: 16px;
        }

        .gauge-container {
          display: flex;
          justify-content: center;
          padding: 16px 0;
        }

        .gauge-svg {
          width: 180px;
          height: 180px;
        }

        .gauge-ring {
          transition: stroke-dashoffset 0.6s ease;
        }

        .cache-info {
          background: var(--loki-bg-card);
          border: 1px solid var(--loki-border);
          border-radius: 5px;
          padding: 16px;
        }

        .cache-grid {
          display: grid;
          grid-template-columns: 1fr 1fr;
          gap: 12px;
