          color: var(--loki-text-primary);
        }

        /* Timeline Tab */
        .timeline-tab {
          display: flex;
          flex-direction: column;
          gap: 4px;
        }

        .timeline-header-row {
          display: grid;
          grid-template-columns: 48px 1fr 72px 72px;
          gap: 8px;
