/**
 * @fileoverview Cost Breakdown Waterfall Chart - visualizes cost composition
 * by phase with running total line and budget comparison. Each phase has a
 * colored bar showing its contribution, with hover tooltips for exact amounts.
 *
 * @example
 * <loki-cost-waterfall api-url="http://localhost:57374" theme="dark"></loki-cost-waterfall>
 */

import { LokiElement } from '../core/loki-theme.js';
import { getApiClient } from '../core/loki-api-client.js';
import { registerPoll } from '../core/loki-poll-registry.js';

/** @type {Object<string, {color: string, label: string}>} Phase color mapping */
const PHASE_COLORS = {
  planning:       { color: 'var(--loki-blue, #2F71E3)',   label: 'Planning' },
  building:       { color: 'var(--loki-green, #1FC5A8)',   label: 'Building' },
  implementation: { color: 'var(--loki-green, #1FC5A8)',   label: 'Building' },
  testing:        { color: 'var(--loki-purple, #553DE9)',  label: 'Testing' },
  review:         { color: 'var(--loki-yellow, #D4A03C)',  label: 'Review' },
  overhead:       { color: 'var(--loki-text-muted, #939084)', label: 'Overhead' },
};

/**
 * @class LokiCostWaterfall
 * @extends LokiElement
 * @property {string} api-url - API base URL (default: window.location.origin)
 * @property {string} theme - Theme name (default: auto-detect)
 */
export class LokiCostWaterfall extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'theme'];
  }

  constructor() {
    super();
    this._phases = [];
    this._budget = null;
    this._totalCost = 0;
    this._hoveredPhase = null;
    this._api = null;
    this._pollInterval = null;
  }

  connectedCallback() {
    super.connectedCallback();
    this._setupApi();
    this._loadData();
    this._startPolling();
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this._stopPolling();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    if (name === 'api-url' && this._api) {
      this._api = getApiClient({ baseUrl: newValue });
      this._loadData();
    }
    if (name === 'theme') {
      this._applyTheme();
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });
  }

  _startPolling() {
    // Central registry gates this poll to the active + visible section so a
    // hidden tab or a background section does not fetch. connectedCallback
    // already does the initial load, so immediate is disabled here to avoid a
    // duplicate first fetch.
    this._poll = registerPoll({
      loadFn: () => this._loadData(),
      intervalMs: 10000,
      element: this,
      immediate: false,
    });
  }

  _stopPolling() {
    if (this._poll) {
      this._poll.stop();
      this._poll = null;
    }
  }

  async _loadData() {
    // Capture the api instance so a mid-flight api-url switch can be detected.
    const api = this._api;
    try {
      const data = await api._get('/api/v2/cost/breakdown');
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      this._phases = data.phases || [];
      this._budget = data.budget_usd || null;
      this._totalCost = data.total_usd || this._phases.reduce((sum, p) => sum + (p.cost_usd || 0), 0);
    } catch {
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      if (this._phases.length === 0) {
        this._phases = this._getDemoData();
        this._budget = 10.00;
        this._totalCost = this._phases.reduce((sum, p) => sum + p.cost_usd, 0);
      }
    }
    this.render();
  }

  _getDemoData() {
    return [
      { phase: 'planning',  cost_usd: 0.85, tokens: 12400 },
      { phase: 'building',  cost_usd: 3.20, tokens: 68500 },
      { phase: 'testing',   cost_usd: 1.45, tokens: 31200 },
      { phase: 'review',    cost_usd: 0.90, tokens: 18800 },
      { phase: 'overhead',  cost_usd: 0.35, tokens: 5600 },
    ];
  }

  _formatCost(usd) {
    if (usd == null) return '--';
    return '$' + usd.toFixed(2);
  }

  _escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  _bindEvents() {
    const root = this.shadowRoot;
    root.querySelectorAll('.waterfall-bar').forEach(bar => {
      bar.addEventListener('mouseenter', () => {
        this._hoveredPhase = bar.dataset.phase;
        this._updateTooltip(bar);
      });
      bar.addEventListener('mouseleave', () => {
        this._hoveredPhase = null;
        this._hideTooltip();
      });
    });
  }

  _updateTooltip(barEl) {
    const tooltip = this.shadowRoot.querySelector('.tooltip');
    if (!tooltip) return;
    const phase = this._phases.find(p => p.phase === this._hoveredPhase);
    if (!phase) return;
    const cfg = PHASE_COLORS[phase.phase] || { label: phase.phase };
    tooltip.innerHTML = `<strong>${this._escapeHtml(cfg.label)}</strong>: ${this._formatCost(phase.cost_usd)}`;
    tooltip.style.display = 'block';
    const rect = barEl.getBoundingClientRect();
    const containerRect = this.shadowRoot.querySelector('.chart-area').getBoundingClientRect();
    tooltip.style.left = (rect.left - containerRect.left + rect.width / 2) + 'px';
    tooltip.style.top = (rect.top - containerRect.top - 30) + 'px';
  }

  _hideTooltip() {
    const tooltip = this.shadowRoot.querySelector('.tooltip');
    if (tooltip) tooltip.style.display = 'none';
  }

  _getStyles() {
    return `
      :host {
        display: block;
      }

      .waterfall-container {
        font-family: var(--loki-font-family, 'Inter', -apple-system, sans-serif);
        color: var(--loki-text-primary, #201515);
      }

      .header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        margin-bottom: 16px;
      }

      .title {
        font-size: 16px;
        font-weight: 600;
        margin: 0;
      }

      .total-cost {
        font-size: 14px;
        font-family: 'JetBrains Mono', monospace;
        font-weight: 600;
        color: var(--loki-accent, #553DE9);
      }

      .chart-card {
        background: var(--loki-bg-card, #ffffff);
        border: 1px solid var(--loki-border, #ECEAE3);
        border-radius: 5px;
        padding: 20px;
      }

      .chart-area {
        position: relative;
        display: flex;
        align-items: flex-end;
        gap: 8px;
        height: 200px;
        padding-bottom: 40px;
        border-bottom: 1px solid var(--loki-border, #ECEAE3);
      }

      .bar-group {
        flex: 1;
        display: flex;
        flex-direction: column;
        align-items: center;
        height: 100%;
        justify-content: flex-end;
        position: relative;
      }

      .waterfall-bar {
        width: 100%;
        max-width: 60px;
        border-radius: 4px 4px 0 0;
        transition: all 0.3s ease;
        cursor: pointer;
        min-height: 4px;
        position: relative;
      }

      .waterfall-bar:hover {
        opacity: 0.85;
        transform: scaleY(1.03);
        transform-origin: bottom;
      }

      .bar-label {
        position: absolute;
        bottom: -32px;
        left: 50%;
        transform: translateX(-50%);
        font-size: 10px;
        font-weight: 600;
        color: var(--loki-text-muted, #939084);
        text-transform: uppercase;
        letter-spacing: 0.03em;
        white-space: nowrap;
      }

      .bar-value {
        position: absolute;
        top: -20px;
        left: 50%;
        transform: translateX(-50%);
        font-size: 11px;
        font-family: 'JetBrains Mono', monospace;
        color: var(--loki-text-secondary, #36342E);
        white-space: nowrap;
      }

      .budget-line {
        position: absolute;
        left: 0;
        right: 0;
        border-top: 2px dashed var(--loki-red, #C45B5B);
        z-index: 1;
      }

      .budget-label {
        position: absolute;
        right: 0;
        top: -16px;
        font-size: 10px;
        font-family: 'JetBrains Mono', monospace;
        color: var(--loki-red, #C45B5B);
        font-weight: 600;
      }

      .running-total-line {
        position: absolute;
        left: 0;
        right: 0;
        bottom: 40px;
        height: calc(100% - 40px);
        pointer-events: none;
      }

      .running-total-line svg {
        width: 100%;
        height: 100%;
      }

      .tooltip {
        display: none;
        position: absolute;
        background: var(--loki-bg-primary, #FFFEFB);
        border: 1px solid var(--loki-border, #ECEAE3);
        border-radius: 4px;
        padding: 6px 10px;
        font-size: 12px;
        box-shadow: var(--loki-shadow-md, 0 4px 6px rgba(32, 21, 21, 0.06));
        white-space: nowrap;
        z-index: 10;
        transform: translateX(-50%);
        pointer-events: none;
      }

      .summary-row {
        display: flex;
        gap: 16px;
        margin-top: 16px;
        flex-wrap: wrap;
      }

      .summary-item {
        display: flex;
        align-items: center;
        gap: 6px;
        font-size: 12px;
      }

      .summary-dot {
        width: 10px;
        height: 10px;
        border-radius: 3px;
        flex-shrink: 0;
      }

      .summary-label {
        color: var(--loki-text-secondary, #36342E);
        font-weight: 500;
      }

      .summary-value {
        font-family: 'JetBrains Mono', monospace;
        color: var(--loki-text-muted, #939084);
        font-size: 11px;
      }

      .empty-state {
        text-align: center;
        padding: 32px 16px;
        color: var(--loki-text-muted, #939084);
        font-size: 13px;
      }
    `;
  }

  render() {
    const s = this.shadowRoot;
    if (!s) return;

    if (this._phases.length === 0) {
      s.innerHTML = `
        <style>${this.getBaseStyles()}${this._getStyles()}</style>
        <div class="waterfall-container">
          <div class="header">
            <h3 class="title">Cost Breakdown</h3>
          </div>
          <div class="empty-state">Cost details will appear once a build starts running.</div>
        </div>
      `;
      return;
    }

    const maxCost = Math.max(...this._phases.map(p => p.cost_usd || 0), 0.01);
    const chartHeight = 160; // usable height in pixels
    const maxBarHeight = this._budget ? Math.max(maxCost, this._budget) : maxCost;

    // Budget line position
    const budgetLineBottom = this._budget ? (this._budget / maxBarHeight) * chartHeight : null;

    // Build bars
    const bars = this._phases.map(p => {
      const cfg = PHASE_COLORS[p.phase] || { color: 'var(--loki-text-muted)', label: p.phase };
      const height = ((p.cost_usd || 0) / maxBarHeight) * chartHeight;
      const isHovered = this._hoveredPhase === p.phase;

      return `
        <div class="bar-group">
          <span class="bar-value">${this._formatCost(p.cost_usd)}</span>
          <div class="waterfall-bar" data-phase="${this._escapeHtml(p.phase)}"
               style="height: ${Math.max(height, 4)}px; background: ${cfg.color}; ${isHovered ? 'opacity: 0.85;' : ''}">
          </div>
          <span class="bar-label">${this._escapeHtml(cfg.label)}</span>
        </div>
      `;
    }).join('');

    // Budget line
    const budgetHtml = budgetLineBottom != null ? `
      <div class="budget-line" style="bottom: ${budgetLineBottom + 40}px;">
        <span class="budget-label">Budget: ${this._formatCost(this._budget)}</span>
      </div>
    ` : '';

    // Summary
    const summaryItems = this._phases.map(p => {
      const cfg = PHASE_COLORS[p.phase] || { color: 'var(--loki-text-muted)', label: p.phase };
      const pct = this._totalCost > 0 ? ((p.cost_usd / this._totalCost) * 100).toFixed(0) : 0;
      return `<div class="summary-item">
        <div class="summary-dot" style="background: ${cfg.color};"></div>
        <span class="summary-label">${this._escapeHtml(cfg.label)}</span>
        <span class="summary-value">${this._formatCost(p.cost_usd)} (${pct}%)</span>
      </div>`;
    }).join('');

    s.innerHTML = `
      <style>${this.getBaseStyles()}${this._getStyles()}</style>
      <div class="waterfall-container">
        <div class="header">
          <h3 class="title">Cost Breakdown</h3>
          <span class="total-cost">Total: ${this._formatCost(this._totalCost)}</span>
        </div>
        <div class="chart-card">
          <div class="chart-area">
            ${bars}
            ${budgetHtml}
            <div class="tooltip"></div>
          </div>
          <div class="summary-row">
            ${summaryItems}
          </div>
        </div>
      </div>
    `;

    this._bindEvents();
  }
}

if (!customElements.get('loki-cost-waterfall')) {
  customElements.define('loki-cost-waterfall', LokiCostWaterfall);
}

export default LokiCostWaterfall;

/**
 * @fileoverview Loki Completion Council Dashboard Component - displays
 * council state, vote history, convergence tracking, and agent management
 * across four tabs: Overview, Decision Log, Convergence, and Agents.
 * Polls council and agent APIs every 3 seconds with visibility-aware
 * pause/resume to avoid unnecessary requests when hidden.
 *
 * @example
 * <loki-council-dashboard api-url="http://localhost:57374" theme="dark"></loki-council-dashboard>
 */

import { LokiElement } from '../core/loki-theme.js';
import { getApiClient } from '../core/loki-api-client.js';
import { registerPoll } from '../core/loki-poll-registry.js';

/** @type {Array<{id: string, label: string}>} Council dashboard tab definitions */
const COUNCIL_TABS = [
  { id: 'overview', label: 'Overview' },
  { id: 'decisions', label: 'Decision Log' },
  { id: 'convergence', label: 'Convergence' },
  { id: 'agents', label: 'Agents' },
];

/**
 * @class LokiCouncilDashboard
 * @extends LokiElement
 * @fires council-action - When a council action is taken (force-review, kill/pause/resume agent)
 * @property {string} api-url - API base URL (default: window.location.origin)
 * @property {string} theme - 'light' or 'dark' (default: auto-detect)
 */
export class LokiCouncilDashboard extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'theme'];
  }

  constructor() {
    super();
    this._loading = false;
    this._error = null;
    this._api = null;
    this._activeTab = 'overview';
    this._pollInterval = null;

    // Data
    this._councilState = null;
    this._verdicts = [];
    this._convergence = [];
    this._agents = [];
    this._selectedAgent = null;
    this._lastDataHash = null;
  }

  connectedCallback() {
    super.connectedCallback();
    this._setupApi();
    this._loadData();
    this._startPolling();
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this._stopPolling();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    if (name === 'api-url' && this._api) {
      this._api = getApiClient({ baseUrl: newValue });
      this._loadData();
    }
    if (name === 'theme') {
      this._applyTheme();
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });
  }

  _startPolling() {
    // Central registry (core/loki-poll-registry.js) gates this poll to the
    // active + visible section in ONE place, replacing the per-component
    // visibilitychange handler. connectedCallback already did the first load,
    // so immediate is disabled to avoid a duplicate fetch.
    this._poll = registerPoll({
      loadFn: () => this._loadData(),
      intervalMs: 3000,
      element: this,
      immediate: false,
    });
  }

  _stopPolling() {
    if (this._poll) {
      this._poll.stop();
      this._poll = null;
    }
    if (this._pendingRaf) {
      cancelAnimationFrame(this._pendingRaf);
      this._pendingRaf = null;
    }
  }

  async _loadData() {
    // Drop a stale response if the api-url switched mid-flight.
    const api = this._api;
    try {
      const [councilState, verdicts, convergence, agents] = await Promise.allSettled([
        api._get('/api/council/state'),
        api._get('/api/council/verdicts'),
        api._get('/api/council/convergence'),
        api._get('/api/agents'),
      ]);
      if (api !== this._api) return;

      if (councilState.status === 'fulfilled') this._councilState = councilState.value;
      if (verdicts.status === 'fulfilled') {
        this._verdicts = verdicts.value.verdicts || [];
      }
      if (convergence.status === 'fulfilled') {
        this._convergence = convergence.value.dataPoints || [];
      }
      if (agents.status === 'fulfilled') {
        this._agents = Array.isArray(agents.value) ? agents.value : [];
      }

      this._error = null;
    } catch (err) {
      if (api !== this._api) return;
      this._error = err.message;
    }

    // Skip full re-render if data hasn't changed (avoids disrupting user interaction)
    const dataHash = JSON.stringify({
      s: this._councilState,
      v: this._verdicts,
      c: this._convergence,
      a: this._agents,
      e: this._error,
    });
    if (dataHash === this._lastDataHash) return;
    this._lastDataHash = dataHash;

    this.render();
  }

  async _forceReview() {
    try {
      await this._api._post('/api/council/force-review');
      this.dispatchEvent(new CustomEvent('council-action', {
        detail: { action: 'force-review' },
        bubbles: true,
      }));
    } catch (err) {
      this._error = `Failed to force review: ${err.message}`;
      this.render();
    }
  }

  async _killAgent(agentId) {
    if (!confirm(`Kill agent ${agentId}?`)) return;
    try {
      await this._api._post(`/api/agents/${agentId}/kill`);
      this.dispatchEvent(new CustomEvent('council-action', {
        detail: { action: 'kill-agent', agentId },
        bubbles: true,
      }));
      await this._loadData();
    } catch (err) {
      this._error = `Failed to kill agent: ${err.message}`;
      this.render();
    }
  }

  async _pauseAgent(agentId) {
    try {
      await this._api._post(`/api/agents/${agentId}/pause`);
      await this._loadData();
    } catch (err) {
      this._error = `Failed to pause agent: ${err.message}`;
      this.render();
    }
  }

  async _resumeAgent(agentId) {
    try {
      await this._api._post(`/api/agents/${agentId}/resume`);
      await this._loadData();
    } catch (err) {
      this._error = `Failed to resume agent: ${err.message}`;
      this.render();
    }
  }

  _setTab(tabId) {
    this._activeTab = tabId;
    this.render();
  }

  _selectAgent(agent) {
    this._selectedAgent = this._selectedAgent?.id === agent.id ? null : agent;
    this.render();
  }

  render() {
    const s = this.shadowRoot;
    if (!s) return;

    // Cancel any pending deferred event binding from _renderAgents
    if (this._pendingRaf) {
      cancelAnimationFrame(this._pendingRaf);
      this._pendingRaf = null;
    }

    s.innerHTML = `
      <style>${this.getBaseStyles()}${this._getStyles()}</style>
      <div class="council-dashboard">
        <div class="council-header">
          <div class="header-left">
            <h2 class="title">Completion Council</h2>
            ${this._councilState?.enabled !== false
              ? `<span class="badge badge-active">Active</span>`
              : `<span class="badge badge-inactive">Disabled</span>`
            }
          </div>
          <button class="btn btn-primary" id="force-review-btn">
            Force Review
          </button>
        </div>

        <div class="tabs">
          ${COUNCIL_TABS.map(tab => `
            <button
              class="tab ${this._activeTab === tab.id ? 'active' : ''}"
              data-tab="${tab.id}"
            >${tab.label}</button>
          `).join('')}
        </div>

        <div class="tab-content">
          ${this._renderTabContent()}
        </div>

        ${this._error ? `<div class="error-banner">${this._escapeHtml(this._error)}</div>` : ''}
      </div>
    `;

    this._attachEventListeners();
  }

  _attachEventListeners() {
    const s = this.shadowRoot;
    if (!s) return;

    // Force Review button
    const forceBtn = s.getElementById('force-review-btn');
    if (forceBtn) {
      forceBtn.addEventListener('click', () => this._forceReview());
    }

    // Tab buttons
    s.querySelectorAll('.tab[data-tab]').forEach(tab => {
      tab.addEventListener('click', () => this._setTab(tab.dataset.tab));
    });

    // Agent cards (bound in _renderAgents via deferred rAF)
  }

  _renderTabContent() {
    switch (this._activeTab) {
      case 'overview': return this._renderOverview();
      case 'decisions': return this._renderDecisions();
      case 'convergence': return this._renderConvergence();
      case 'agents': return this._renderAgents();
      default: return '';
    }
  }

  _renderOverview() {
    const state = this._councilState || {};
    const noChange = state.consecutive_no_change || 0;
    const doneSignals = state.done_signals || 0;
    const totalVotes = state.total_votes || 0;
    const approveVotes = state.approve_votes || 0;
    const lastVerdict = this._verdicts.length > 0 ? this._verdicts[this._verdicts.length - 1] : null;
    const agentCount = this._agents.filter(a => a.alive).length;

    return `
      <div class="overview-grid">
        <div class="stat-card">
          <div class="stat-label">Council Status</div>
          <div class="stat-value ${state.enabled !== false ? 'text-green' : 'text-muted'}">
            ${state.enabled !== false ? 'Monitoring' : 'Disabled'}
          </div>
        </div>
        <div class="stat-card">
          <div class="stat-label">Total Votes Cast</div>
          <div class="stat-value">${totalVotes}</div>
          <div class="stat-sub">${approveVotes} approved</div>
        </div>
        <div class="stat-card">
          <div class="stat-label">Stagnation Streak</div>
          <div class="stat-value ${noChange >= 3 ? 'text-warn' : ''}">${noChange}</div>
          <div class="stat-sub">consecutive no-change</div>
        </div>
        <div class="stat-card">
          <div class="stat-label">Done Signals</div>
          <div class="stat-value ${doneSignals >= 2 ? 'text-green' : ''}">${doneSignals}</div>
          <div class="stat-sub">from agent output</div>
        </div>
        <div class="stat-card">
          <div class="stat-label">Active Agents</div>
          <div class="stat-value">${agentCount}</div>
          <div class="stat-sub">of ${this._agents.length} total</div>
        </div>
        <div class="stat-card">
          <div class="stat-label">Last Verdict</div>
          <div class="stat-value ${lastVerdict?.result === 'APPROVED' ? 'text-green' : 'text-muted'}">
            ${lastVerdict ? lastVerdict.result : 'None'}
          </div>
          ${lastVerdict ? `<div class="stat-sub">iteration ${lastVerdict.iteration}</div>` : ''}
        </div>
      </div>

      ${this._convergence.length > 0 ? `
        <div class="section">
          <h3 class="section-title">Convergence Trend</h3>
          <div class="convergence-mini">
            ${this._renderConvergenceBar()}
          </div>
        </div>
      ` : ''}
    `;
  }

  _renderConvergenceBar() {
    const points = this._convergence.slice(-20);
    if (points.length === 0) return '<span class="text-muted">No data</span>';

    const maxFiles = Math.max(...points.map(p => p.files_changed), 1);
    return `
      <div class="bar-chart">
        ${points.map(p => {
          const height = Math.max(4, (p.files_changed / maxFiles) * 60);
          const isStagnant = p.no_change_streak > 0;
          return `
            <div class="bar-wrapper" title="Iter ${p.iteration}: ${p.files_changed} files changed">
              <div class="bar ${isStagnant ? 'bar-stagnant' : 'bar-active'}" style="height: ${height}px"></div>
              <div class="bar-label">${p.iteration}</div>
            </div>
          `;
        }).join('')}
      </div>
    `;
  }

  _renderDecisions() {
    if (this._verdicts.length === 0) {
      return `<div class="empty-state">No review decisions yet. The council checks for completion every ${this._councilState?.check_interval || 5} build steps.</div>`;
    }

    return `
      <div class="decision-list">
        ${this._verdicts.slice().reverse().map(v => `
          <div class="decision-card ${v.result === 'APPROVED' ? 'decision-approved' : 'decision-rejected'}">
            <div class="decision-header">
              <span class="decision-result ${v.result === 'APPROVED' ? 'text-green' : 'text-warn'}">
                ${v.result}
              </span>
              <span class="decision-iter">Iteration ${v.iteration}</span>
              <span class="decision-time">${this._formatTime(v.timestamp)}</span>
            </div>
            <div class="decision-votes">
              <span class="vote-approve">${v.approve} Approve</span>
              <span class="vote-reject">${v.reject} Reject</span>
            </div>
          </div>
        `).join('')}
      </div>
    `;
  }

  _renderConvergence() {
    if (this._convergence.length === 0) {
      return '<div class="empty-state">No convergence data available yet.</div>';
    }

    return `
      <div class="section">
        <h3 class="section-title">Files Changed Per Iteration</h3>
        <div class="convergence-chart">
          ${this._renderConvergenceBar()}
        </div>
      </div>

      <div class="section">
        <h3 class="section-title">Convergence Log</h3>
        <div class="convergence-table">
          <table>
            <thead>
              <tr>
                <th>Iteration</th>
                <th>Files Changed</th>
                <th>No-Change Streak</th>
                <th>Done Signals</th>
              </tr>
            </thead>
            <tbody>
              ${this._convergence.slice().reverse().map(p => `
                <tr class="${p.no_change_streak >= 3 ? 'row-warn' : ''}">
                  <td>${p.iteration}</td>
                  <td>${p.files_changed}</td>
                  <td>${p.no_change_streak}</td>
                  <td>${p.done_signals}</td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
      </div>
    `;
  }

  _renderAgents() {
    if (this._agents.length === 0) {
      return '<div class="empty-state">No agents registered.</div>';
    }

    const html = `
      <div class="agents-list">
        ${this._agents.map((agent, idx) => `
          <div class="agent-card ${this._selectedAgent?.id === agent.id ? 'agent-selected' : ''}"
               data-agent-index="${idx}">
            <div class="agent-header">
              <span class="agent-name">${this._escapeHtml(agent.name || agent.id || 'Unknown')}</span>
              <span class="agent-status ${agent.alive ? 'status-alive' : 'status-dead'}">
                ${agent.alive ? 'Running' : 'Stopped'}
              </span>
            </div>
            <div class="agent-meta">
              ${agent.type ? `<span class="agent-type">${this._escapeHtml(agent.type)}</span>` : ''}
              ${agent.pid ? `<span class="agent-pid">PID: ${agent.pid}</span>` : ''}
              ${agent.task ? `<span class="agent-task">Task: ${this._escapeHtml(agent.task)}</span>` : ''}
            </div>
            ${this._selectedAgent?.id === agent.id ? `
              <div class="agent-actions">
                ${agent.alive ? `
                  <button class="btn btn-sm btn-warn" data-action="pause" data-agent-id="${this._escapeHtml(agent.id || agent.name)}">
                    Pause
                  </button>
                  <button class="btn btn-sm btn-danger" data-action="kill" data-agent-id="${this._escapeHtml(agent.id || agent.name)}">
                    Kill
                  </button>
                ` : `
                  <button class="btn btn-sm btn-primary" data-action="resume" data-agent-id="${this._escapeHtml(agent.id || agent.name)}">
                    Resume
                  </button>
                `}
              </div>
            ` : ''}
          </div>
        `).join('')}
      </div>
    `;

    // Defer event binding until after render inserts this HTML.
    // Store rAF id so render() can cancel stale callbacks.
    this._pendingRaf = requestAnimationFrame(() => {
      this._pendingRaf = null;
      const s = this.shadowRoot;
      if (!s) return;
      s.querySelectorAll('.agent-card[data-agent-index]').forEach(card => {
        const idx = parseInt(card.dataset.agentIndex, 10);
        const agent = this._agents[idx];
        if (!agent) return;
        card.addEventListener('click', () => this._selectAgent(agent));
        card.querySelectorAll('[data-action]').forEach(btn => {
          btn.addEventListener('click', (e) => {
            e.stopPropagation();
            const action = btn.dataset.action;
            const agentId = btn.dataset.agentId;
            if (action === 'pause') this._pauseAgent(agentId);
            else if (action === 'kill') this._killAgent(agentId);
            else if (action === 'resume') this._resumeAgent(agentId);
          });
        });
      });
    });

    return html;
  }

  _formatTime(timestamp) {
    if (!timestamp) return '';
    try {
      const d = new Date(timestamp);
      return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    } catch {
      return timestamp;
    }
  }

  _escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

