        .logo-brand {
          font-family: 'Fraunces', Georgia, serif;
          font-size: 18px;
          font-weight: 400;
          color: var(--loki-text-primary);
          letter-spacing: -0.01em;
          white-space: nowrap;
        }

        .logo-subtitle {
          font-size: 11px;
          color: var(--loki-text-muted);
          text-transform: uppercase;
          letter-spacing: 0.05em;
          white-space: nowrap;
        }

        .header-right {
          display: flex;
          align-items: center;
          gap: 16px;
          flex-shrink: 0;
        }

        .connection-status {
          display: flex;
          align-items: center;
          gap: 6px;
          font-size: 11px;
          color: var(--loki-text-muted);
        }

        .conn-dot {
          width: 8px;
          height: 8px;
          border-radius: 50%;
          flex-shrink: 0;
        }

        .conn-dot.connected {
          background: var(--loki-green);
          box-shadow: 0 0 6px var(--loki-green);
        }

        .conn-dot.disconnected {
          background: var(--loki-red);
        }

        .session-info {
          display: flex;
          align-items: center;
          gap: 12px;
