          </div>
          <div class="list-items" role="list">
            ${(success_patterns || []).slice(0, 5).map(s => `
              <div class="list-item success-item" data-type="success_pattern" data-id="${this._escapeHtml(s.pattern_name)}" tabindex="0" role="listitem">
