      </style>
    `;

    let content;
    if (this._loading) {
      content = '<div class="loading">Loading learning metrics...</div>';
    } else if (this._error) {
      content = `<div class="error-state">Error: ${this._escapeHtml(this._error)}</div>`;
    } else {
      content = `
        <div class="content-main">
          ${this._renderSummaryCards()}
          ${this._renderTrendChart()}
          ${this._renderTopLists()}
          ${this._renderRecentSignals()}
        </div>
        ${this._renderDetailPanel()}
      `;
    }

    this.shadowRoot.innerHTML = `
      ${styles}
      <div class="learning-dashboard">
        <div class="dashboard-header">
          <span class="dashboard-title">
            <svg width="16" height="16" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2" fill="none">
              <path d="M12 20V10"/>
              <path d="M18 20V4"/>
              <path d="M6 20v-4"/>
            </svg>
            Learning Metrics Dashboard
          </span>
        </div>
        ${this._renderFilters()}
        <div class="dashboard-content">
          ${content}
        </div>
      </div>
    `;

    this._attachEventListeners();
  }

  _attachEventListeners() {
    // Filter selects
    const timeRangeSelect = this.shadowRoot.getElementById('time-range-select');
    if (timeRangeSelect) {
      timeRangeSelect.addEventListener('change', (e) => this._setFilter('timeRange', e.target.value));
    }

    const signalTypeSelect = this.shadowRoot.getElementById('signal-type-select');
    if (signalTypeSelect) {
      signalTypeSelect.addEventListener('change', (e) => this._setFilter('signalType', e.target.value));
    }

    const sourceSelect = this.shadowRoot.getElementById('source-select');
    if (sourceSelect) {
      sourceSelect.addEventListener('change', (e) => this._setFilter('source', e.target.value));
    }

    // Refresh button
    const refreshBtn = this.shadowRoot.getElementById('refresh-btn');
    if (refreshBtn) {
      refreshBtn.addEventListener('click', () => this._loadData());
    }

    // Close detail button
    const closeBtn = this.shadowRoot.getElementById('close-detail');
    if (closeBtn) {
      closeBtn.addEventListener('click', () => this._closeDetail());
    }

    // List items
    this.shadowRoot.querySelectorAll('.list-item').forEach(item => {
      item.addEventListener('click', () => {
        const type = item.dataset.type;
        const id = item.dataset.id;
        const itemData = this._findItemData(type, id);
        if (itemData) {
          this._selectMetric(type, itemData);
        }
      });

      item.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          item.click();
        }
      });
    });
  }

  _findItemData(type, id) {
    if (!this._metrics?.aggregation) return null;

    switch (type) {
      case 'preference':
        return this._metrics.aggregation.preferences?.find(p => p.preference_key === id);
      case 'error_pattern':
        return this._metrics.aggregation.error_patterns?.find(e => e.error_type === id);
      case 'success_pattern':
        return this._metrics.aggregation.success_patterns?.find(s => s.pattern_name === id);
      case 'tool_efficiency':
        return this._metrics.aggregation.tool_efficiencies?.find(t => t.tool_name === id);
      default:
        return null;
    }
  }
}

// Register the component
if (!customElements.get('loki-learning-dashboard')) {
  customElements.define('loki-learning-dashboard', LokiLearningDashboard);
}

export default LokiLearningDashboard;

/**
 * @fileoverview Loki Log Stream Component - real-time log viewer with level
 * filtering, text search, auto-scroll, and download capabilities. Supports
 * both API polling and file-based log sources. Styled as a terminal emulator
 * with monospace font and colored log levels.
 *
 * @example
 * <loki-log-stream api-url="http://localhost:57374" max-lines="500" auto-scroll theme="dark"></loki-log-stream>
 */

import { LokiElement } from '../core/loki-theme.js';
import { getApiClient, ApiEvents } from '../core/loki-api-client.js';
import { registerPoll } from '../core/loki-poll-registry.js';

/** @type {Object<string, {color: string, label: string}>} Log level display configuration */
const LOG_LEVELS = {
  info: { color: 'var(--loki-blue)', label: 'INFO' },
  success: { color: 'var(--loki-green)', label: 'SUCCESS' },
  warning: { color: 'var(--loki-yellow)', label: 'WARN' },
  error: { color: 'var(--loki-red)', label: 'ERROR' },
  step: { color: 'var(--loki-purple)', label: 'STEP' },
  agent: { color: 'var(--loki-accent)', label: 'AGENT' },
  debug: { color: 'var(--loki-text-muted)', label: 'DEBUG' },
};

/**
 * @class LokiLogStream
 * @extends LokiElement
 * @fires log-received - When a new log message arrives
 * @fires logs-cleared - When the log buffer is cleared
 * @property {string} api-url - API base URL (default: window.location.origin)
 * @property {number} max-lines - Maximum log lines to retain (default: 500)
 * @property {boolean} auto-scroll - Auto-scroll to bottom on new messages
 * @property {string} theme - 'light' or 'dark' (default: auto-detect)
 * @property {string} log-file - Path to log file for file-based polling
 */
export class LokiLogStream extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'max-lines', 'auto-scroll', 'theme', 'log-file'];
  }

  constructor() {
    super();
    this._logs = [];
    this._maxLines = 500;
    this._autoScroll = true;
    this._filter = '';
    this._levelFilter = 'all';
    this._api = null;
    this._pollInterval = null;
    this._logMessageHandler = null;
    // Heavy-logs duplicate suppression: track how many lines we have already
    // ingested and a lightweight signature of the last response so an unchanged
    // 200-line log does not get re-processed every cycle. The poll itself is
    // gated to the active + visible Insights section by the central registry.
    this._apiLastCount = 0;
    this._apiLastSig = null;
    this._fileLastSize = 0;
    this._fileLastSig = null;
  }

  connectedCallback() {
    super.connectedCallback();
    this._maxLines = parseInt(this.getAttribute('max-lines')) || 500;
    this._autoScroll = this.hasAttribute('auto-scroll');
    this._setupApi();
    this._startLogPolling();
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this._stopLogPolling();
    this._teardownApiListeners();
  }

  _teardownApiListeners() {
    if (this._api && this._logMessageHandler) {
      this._api.removeEventListener(ApiEvents.LOG_MESSAGE, this._logMessageHandler);
    }
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;

    switch (name) {
      case 'api-url':
        if (this._api) {
          // Adopt the correct per-URL client instead of mutating the cached
          // singleton's baseUrl (which leaks one project's logs into another).
          // Detach our LOG_MESSAGE listener from the old instance, swap, and
          // re-subscribe. Reset the accumulated log buffer so the switched
          // project starts clean rather than appending to the prior project.
          this._teardownApiListeners();
          this._logs = [];
          this._apiLastCount = 0;
          this._apiLastSig = null;
          this._setupApi();
          this.render();
        }
        break;
      case 'max-lines':
        this._maxLines = parseInt(newValue) || 500;
        this._trimLogs();
        this.render();
        break;
      case 'auto-scroll':
        this._autoScroll = this.hasAttribute('auto-scroll');
        this.render();
        break;
      case 'theme':
        this._applyTheme();
        break;
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });

    this._logMessageHandler = (e) => this._addLog(e.detail);
    this._api.addEventListener(ApiEvents.LOG_MESSAGE, this._logMessageHandler);
  }

  _startLogPolling() {
    const logFile = this.getAttribute('log-file');
    if (logFile) {
      this._pollLogFile(logFile);
    } else {
      // Poll /api/logs endpoint as fallback when no log-file attribute
      this._pollApiLogs();
    }
    // WebSocket-based logs are handled via event listener
  }

  async _pollApiLogs() {
    // Run once now, then register the recurring poll on the central registry so
    // the heavy /api/logs?lines=200 endpoint only fetches when the Logs view
    // (Insights section) is active AND the tab is visible. The interval is
    // deliberately LONGER than the light status polls (5s vs the 2s it used to
    // run at on every page) because logs are heavy and the WebSocket push path
    // delivers live lines in real time when connected.
    await this._apiLogPollTick();
    this._poll = registerPoll({
      loadFn: () => this._apiLogPollTick(),
      intervalMs: 5000,
      element: this,
      immediate: false,
    });
  }

  async _apiLogPollTick() {
    try {
      const entries = await this._api.getLogs(200);
      if (!Array.isArray(entries)) return;
      // Duplicate-suppression: skip all work if the response is identical to
      // the last one (same count + same last-line signature). This avoids
      // re-walking and re-rendering an unchanged 200-line log every cycle.
      const sig = entries.length
        ? `${entries.length}:${entries[entries.length - 1]?.timestamp || ''}:${entries[entries.length - 1]?.message || ''}`
        : '0';
      if (sig === this._apiLastSig) return;
      this._apiLastSig = sig;
      if (entries.length > this._apiLastCount) {
        const newEntries = entries.slice(this._apiLastCount);
        for (const entry of newEntries) {
          if (entry.message && entry.message.trim()) {
            this._addLog({
              message: entry.message,
              level: entry.level || 'info',
              timestamp: entry.timestamp || new Date().toLocaleTimeString(),
            });
          }
        }
      } else if (entries.length < this._apiLastCount) {
        // Log rotated/truncated: reset and ingest from the top next cycle.
        this._apiLastCount = 0;
      }
      this._apiLastCount = entries.length;
    } catch (error) {
      // API not available, will retry on next poll
    }
  }

  async _pollLogFile(logFile) {
    // Run once now, then register the recurring file poll on the central
    // registry (active + visible section only). Kept at 1s for file tails since
    // a static file read is cheap, but still gated so a hidden tab or a
    // background section does no I/O.
    await this._fileLogPollTick(logFile);
    this._poll = registerPoll({
      loadFn: () => this._fileLogPollTick(logFile),
      intervalMs: 1000,
      element: this,
      immediate: false,
    });
  }

  async _fileLogPollTick(logFile) {
    try {
      const response = await fetch(`${logFile}?t=${Date.now()}`, { credentials: 'include' });
      if (!response.ok) return;

      const text = await response.text();
      // Duplicate-suppression: identical file content -> no work.
      const sig = `${text.length}`;
      if (sig === this._fileLastSig) return;
      this._fileLastSig = sig;
      const lines = text.split('\n');

      // Only process new lines
      if (lines.length > this._fileLastSize) {
        const newLines = lines.slice(this._fileLastSize);
        for (const line of newLines) {
          if (line.trim()) {
            this._addLog(this._parseLine(line));
          }
        }
      } else if (lines.length < this._fileLastSize) {
        this._fileLastSize = 0;
      }
      this._fileLastSize = lines.length;
    } catch (error) {
      // Silently ignore file read errors
    }
  }

  _stopLogPolling() {
    if (this._poll) {
      this._poll.stop();
      this._poll = null;
    }
  }

  _parseLine(line) {
    // Try to parse structured log format: [TIMESTAMP] [LEVEL] message
    const match = line.match(/^\[([^\]]+)\]\s*\[([^\]]+)\]\s*(.+)$/);
    if (match) {
      return {
        timestamp: match[1],
        level: match[2].toLowerCase(),
        message: match[3],
      };
    }

    // Try simpler format: TIMESTAMP LEVEL message
    const simpleMatch = line.match(/^(\d{2}:\d{2}:\d{2})\s+(\w+)\s+(.+)$/);
    if (simpleMatch) {
      return {
        timestamp: simpleMatch[1],
        level: simpleMatch[2].toLowerCase(),
        message: simpleMatch[3],
      };
    }

    // Default: treat as info message
    return {
      timestamp: new Date().toLocaleTimeString(),
      level: 'info',
      message: line,
    };
  }

  _addLog(log) {
    if (!log) return;

    const entry = {
      id: Date.now() + Math.random(),
      timestamp: log.timestamp || new Date().toLocaleTimeString(),
      level: (log.level || 'info').toLowerCase(),
      message: log.message || log,
    };

    this._logs.push(entry);
    this._trimLogs();

    this.dispatchEvent(new CustomEvent('log-received', { detail: entry }));

    this._renderLogs();

    if (this._autoScroll) {
      this._scrollToBottom();
    }
  }

  _trimLogs() {
    if (this._logs.length > this._maxLines) {
      this._logs = this._logs.slice(-this._maxLines);
    }
  }

  _clearLogs() {
    this._logs = [];
    this.dispatchEvent(new CustomEvent('logs-cleared'));
    this._renderLogs();
  }

  _toggleAutoScroll() {
    this._autoScroll = !this._autoScroll;
    this.render();
    if (this._autoScroll) {
      this._scrollToBottom();
    }
  }

  _scrollToBottom() {
    requestAnimationFrame(() => {
      const output = this.shadowRoot.getElementById('log-output');
      if (output) {
        output.scrollTop = output.scrollHeight;
      }
    });
  }

  _downloadLogs() {
    const content = this._logs
      .map(log => `[${log.timestamp}] [${log.level.toUpperCase()}] ${log.message}`)
      .join('\n');

    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `loki-logs-${new Date().toISOString().split('T')[0]}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  }

  _setFilter(filter) {
    this._filter = filter.toLowerCase();
    this._renderLogs();
  }

  _setLevelFilter(level) {
    this._levelFilter = level;
    this._renderLogs();
  }

  _getFilteredLogs() {
    return this._logs.filter(log => {
      // Level filter
      if (this._levelFilter !== 'all' && log.level !== this._levelFilter) {
        return false;
      }

      // Text filter
      if (this._filter && !log.message.toLowerCase().includes(this._filter)) {
        return false;
      }

      return true;
    });
  }

  _renderLogs() {
    const output = this.shadowRoot.getElementById('log-output');
    if (!output) return;

    const filteredLogs = this._getFilteredLogs();

    if (filteredLogs.length === 0) {
      output.innerHTML = '<div class="log-empty">No log output yet. Terminal will update when Loki Mode is running.</div>';
      return;
    }

    output.innerHTML = filteredLogs.map(log => {
      const levelConfig = LOG_LEVELS[log.level] || LOG_LEVELS.info;
      return `
        <div class="log-line">
          <span class="timestamp">${this._escapeHtml(log.timestamp)}</span>
          <span class="level" style="color: ${levelConfig.color}">[${this._escapeHtml(levelConfig.label)}]</span>
          <span class="message">${this._escapeHtml(log.message)}</span>
        </div>
      `;
    }).join('');

    if (this._autoScroll) {
      this._scrollToBottom();
    }
  }

  _escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  render() {
    const styles = `
      <style>
        ${this.getBaseStyles()}

        :host {
          display: block;
        }

        .terminal-container {
          background: #1A0F2E;
          border: 1px solid #2A1F3E;
          border-radius: 5px;
          overflow: hidden;
        }

        .terminal-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          padding: 10px 14px;
          background: #140B24;
          border-bottom: 1px solid #2A1F3E;
        }

        .terminal-title {
          display: flex;
          align-items: center;
          gap: 8px;
          font-size: 12px;
          font-weight: 600;
          color: #C0B8D0;
        }

        .terminal-dots {
          display: flex;
          gap: 6px;
        }

        .terminal-dot {
          width: 10px;
          height: 10px;
          border-radius: 50%;
        }

        .terminal-dot.red { background: #ff5f56; }
        .terminal-dot.yellow { background: #ffbd2e; }
        .terminal-dot.green { background: #27c93f; }

        .terminal-controls {
          display: flex;
          gap: 8px;
          align-items: center;
        }

        .terminal-btn {
          padding: 4px 10px;
          background: #2A1F4A;
          border: 1px solid #3D3060;
          border-radius: 4px;
          color: #C0B8D0;
          font-size: 11px;
          cursor: pointer;
          transition: all var(--loki-transition);
        }

        .terminal-btn:hover {
          background: #3D3060;
          color: #F0ECF8;
        }

        .terminal-btn.active {
          background: var(--loki-accent);
          border-color: var(--loki-accent);
          color: white;
        }

        .filter-input {
          padding: 4px 10px;
          background: #2A1F4A;
          border: 1px solid #3D3060;
          border-radius: 4px;
          color: #F0ECF8;
          font-size: 11px;
          width: 120px;
        }

        .filter-input:focus {
          outline: none;
          border-color: var(--loki-accent);
        }

        .filter-input::placeholder {
          color: #8B7FA8;
        }

        .level-select {
          padding: 4px 10px;
          background: #2A1F4A;
          border: 1px solid #3D3060;
          border-radius: 4px;
          color: #C0B8D0;
          font-size: 11px;
          cursor: pointer;
        }

        .log-output {
          padding: 14px;
          max-height: 350px;
          overflow-y: auto;
          font-family: 'JetBrains Mono', monospace;
          font-size: 12px;
          line-height: 1.6;
          color: #F0ECF8;
          background: #1A0F2E;
        }

        .log-line {
          display: flex;
          gap: 10px;
          white-space: pre-wrap;
          word-break: break-all;
        }

        .log-line .timestamp {
          color: var(--loki-text-muted);
          flex-shrink: 0;
        }

        .log-line .level {
          flex-shrink: 0;
          font-weight: 500;
        }

        .log-line .message {
          flex: 1;
        }

        .log-empty {
          color: var(--loki-text-muted);
          text-align: center;
          padding: 40px;
        }

        .log-count {
          font-size: 10px;
          color: var(--loki-text-muted);
          padding: 4px 14px;
          border-top: 1px solid var(--loki-border);
          background: var(--loki-bg-secondary);
        }

        /* Scrollbar */
        .log-output::-webkit-scrollbar { width: 6px; }
        .log-output::-webkit-scrollbar-track { background: var(--loki-bg-secondary); }
        .log-output::-webkit-scrollbar-thumb { background: var(--loki-border-light); border-radius: 3px; }
        .log-output::-webkit-scrollbar-thumb:hover { background: var(--loki-text-muted); }
      </style>
    `;

    this.shadowRoot.innerHTML = `
      ${styles}
      <div class="terminal-container">
        <div class="terminal-header">
          <div class="terminal-title">
            <div class="terminal-dots">
              <span class="terminal-dot red"></span>
              <span class="terminal-dot yellow"></span>
              <span class="terminal-dot green"></span>
            </div>
            loki-mode -- agent output
          </div>
          <div class="terminal-controls">
            <input type="text" class="filter-input" id="filter-input" placeholder="Filter logs...">
            <select class="level-select" id="level-select">
              <option value="all">All Levels</option>
              <option value="info">Info</option>
              <option value="success">Success</option>
              <option value="warning">Warning</option>
              <option value="error">Error</option>
              <option value="step">Step</option>
              <option value="agent">Agent</option>
              <option value="debug">Debug</option>
            </select>
            <button class="terminal-btn ${this._autoScroll ? 'active' : ''}" id="auto-scroll-btn" aria-label="Toggle auto-scroll" aria-pressed="${this._autoScroll}">Auto-scroll</button>
            <button class="terminal-btn" id="clear-btn" aria-label="Clear all logs">Clear</button>
            <button class="terminal-btn" id="download-btn" aria-label="Download logs as text file">Download</button>
          </div>
        </div>
        <div class="log-output" id="log-output" role="log" aria-live="polite" aria-label="Log output">
          <div class="log-empty">No log output yet. Terminal will update when Loki Mode is running.</div>
        </div>
        <div class="log-count">
          ${this._logs.length} lines (${this._getFilteredLogs().length} shown)
        </div>
      </div>
    `;

    this._attachEventListeners();
    this._renderLogs();
  }

  _attachEventListeners() {
    const filterInput = this.shadowRoot.getElementById('filter-input');
    const levelSelect = this.shadowRoot.getElementById('level-select');
    const autoScrollBtn = this.shadowRoot.getElementById('auto-scroll-btn');
    const clearBtn = this.shadowRoot.getElementById('clear-btn');
    const downloadBtn = this.shadowRoot.getElementById('download-btn');

    if (filterInput) {
      filterInput.value = this._filter;
      filterInput.addEventListener('input', (e) => this._setFilter(e.target.value));
    }

    if (levelSelect) {
      levelSelect.value = this._levelFilter;
      levelSelect.addEventListener('change', (e) => this._setLevelFilter(e.target.value));
    }

    if (autoScrollBtn) {
      autoScrollBtn.addEventListener('click', () => this._toggleAutoScroll());
    }

    if (clearBtn) {
      clearBtn.addEventListener('click', () => this._clearLogs());
    }

    if (downloadBtn) {
      downloadBtn.addEventListener('click', () => this._downloadLogs());
    }
  }

  /**
   * Public API to add a log entry programmatically
   */
  addLog(message, level = 'info') {
    this._addLog({ message, level, timestamp: new Date().toLocaleTimeString() });
  }

  /**
   * Public API to clear all logs
   */
  clear() {
    this._clearLogs();
  }
}

// Register the component
if (!customElements.get('loki-log-stream')) {
  customElements.define('loki-log-stream', LokiLogStream);
}

export default LokiLogStream;

/**
 * @fileoverview Loki Managed Memory Panel
 *
 * Read-only viewer for the Anthropic Managed Memory beta surface.
 * Polls /api/managed/status on mount; if disabled, renders a
 * disabled-state notice and performs no further network activity.
 * When enabled, lists recent managed-memory events (limit=50) and
 * supports ad-hoc memory-version lookup by ID.
 *
 * Out of scope for v1: write operations, event filtering DSL,
 * websocket streaming, charts.
 *
 * @example
 * <loki-managed-memory-panel api-url="http://localhost:57374" theme="dark"></loki-managed-memory-panel>
 */

import { LokiElement } from '../core/loki-theme.js';
import { getApiClient } from '../core/loki-api-client.js';

const DEFAULT_EVENT_LIMIT = 50;

/**
 * @class LokiManagedMemoryPanel
 * @extends LokiElement
 * @property {string} api-url - API base URL (default: window.location.origin)
 * @property {string} theme - Theme override (light, dark, high-contrast, etc.)
 */
export class LokiManagedMemoryPanel extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'theme'];
  }

  constructor() {
    super();
    this._api = null;

    // Status state
    this._statusLoading = false;
    this._statusError = null;
    this._status = null; // {enabled, parent_flag, child_flags, beta_header, last_fallback_ts}

    // Events state
    this._eventsLoading = false;
    this._eventsError = null;
    this._events = [];
    this._eventsSource = null;
    this._eventsCount = 0;

    // Memory-version lookup state
    this._lookupId = '';
    this._lookupLoading = false;
    this._lookupError = null;
    this._lookupResult = null;
  }

  connectedCallback() {
    super.connectedCallback();
    this._setupApi();
    this._loadStatus();
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    // No polling/timers in v1; method kept for symmetry with other panels.
    this._stopPolling();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    switch (name) {
      case 'api-url':
        if (this._api) {
          this._api = getApiClient({ baseUrl: newValue });
          this._loadStatus();
        }
        break;
      case 'theme':
        this._applyTheme();
        this.render();
        break;
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });
  }

  _stopPolling() {
    // Reserved for future polling lifecycle; intentionally a no-op in v1.
  }

  async _loadStatus() {
    // Capture the api instance so a mid-flight api-url switch can be detected.
    const api = this._api;
    this._statusLoading = true;
    this._statusError = null;
    this.render();

    try {
      const status = await api.get('/api/managed/status');
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      this._status = status;
    } catch (err) {
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      this._statusError = (err && err.message) ? err.message : 'Failed to load managed status';
      this._status = null;
    } finally {
      this._statusLoading = false;
    }

    // Only fan out to events when the surface is actually enabled.
    if (this._status && this._status.enabled) {
      await this._loadEvents();
    } else {
      this.render();
    }
  }

  async _loadEvents(limit = DEFAULT_EVENT_LIMIT) {
    // Capture the api instance so a mid-flight api-url switch can be detected.
    const api = this._api;
    this._eventsLoading = true;
    this._eventsError = null;
    this.render();

    try {
      const data = await api.get('/api/managed/events?limit=' + encodeURIComponent(limit));
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      // Endpoint shape: {events, count, source}; tolerate plain arrays too.
      if (Array.isArray(data)) {
        this._events = data;
        this._eventsCount = data.length;
        this._eventsSource = null;
      } else if (data && typeof data === 'object') {
        this._events = Array.isArray(data.events) ? data.events : [];
        this._eventsCount = typeof data.count === 'number' ? data.count : this._events.length;
        this._eventsSource = data.source || null;
      } else {
        this._events = [];
        this._eventsCount = 0;
        this._eventsSource = null;
      }
    } catch (err) {
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      this._eventsError = (err && err.message) ? err.message : 'Failed to load managed events';
      this._events = [];
      this._eventsCount = 0;
      this._eventsSource = null;
    } finally {
      this._eventsLoading = false;
      this.render();
    }
  }

  async _lookupMemoryVersion() {
    const id = (this._lookupId || '').trim();
    if (!id) {
      this._lookupError = 'Enter a memory ID to look up';
      this._lookupResult = null;
      this.render();
      return;
    }

    // Capture the api instance so a mid-flight api-url switch can be detected.
    const api = this._api;
    this._lookupLoading = true;
    this._lookupError = null;
    this._lookupResult = null;
    this.render();

    try {
      const path = '/api/managed/memory_versions/' + encodeURIComponent(id);
      const result = await api.get(path);
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      this._lookupResult = result;
    } catch (err) {
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      this._lookupError = (err && err.message) ? err.message : 'Failed to load memory versions';
      this._lookupResult = null;
    } finally {
      this._lookupLoading = false;
      this.render();
    }
  }

  _onLookupInput(event) {
    this._lookupId = event && event.target ? event.target.value : '';
  }

  _onLookupKeyDown(event) {
    if (event && event.key === 'Enter') {
      event.preventDefault();
      this._lookupMemoryVersion();
    }
  }

  _attachEventHandlers() {
    const root = this.shadowRoot;
    if (!root) return;

    const refreshBtn = root.querySelector('#refresh-status-btn');
    if (refreshBtn) {
      refreshBtn.addEventListener('click', () => this._loadStatus());
    }

    const refreshEventsBtn = root.querySelector('#refresh-events-btn');
    if (refreshEventsBtn) {
      refreshEventsBtn.addEventListener('click', () => this._loadEvents());
    }

    const lookupInput = root.querySelector('#lookup-input');
    if (lookupInput) {
      lookupInput.addEventListener('input', (e) => this._onLookupInput(e));
      lookupInput.addEventListener('keydown', (e) => this._onLookupKeyDown(e));
    }

    const lookupBtn = root.querySelector('#lookup-btn');
    if (lookupBtn) {
      lookupBtn.addEventListener('click', () => this._lookupMemoryVersion());
    }
  }

  _escapeHtml(value) {
    if (value === null || value === undefined) return '';
    return String(value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  _formatTimestamp(ts) {
    if (!ts) return '';
    // Accept seconds, milliseconds, or ISO strings.
    let date;
    if (typeof ts === 'number') {
      date = new Date(ts > 1e12 ? ts : ts * 1000);
    } else {
      date = new Date(ts);
    }
    if (Number.isNaN(date.getTime())) return String(ts);
    return date.toISOString().replace('T', ' ').replace(/\.\d+Z$/, 'Z');
  }

  _renderStatusSection() {
    if (this._statusLoading) {
      return '<div class="status-row muted">Loading managed memory status...</div>';
    }
    if (this._statusError) {
      return `
        <div class="error-banner" role="alert">
          <strong>Status error:</strong>
          <span>${this._escapeHtml(this._statusError)}</span>
        </div>
      `;
    }
    if (!this._status) {
      return '<div class="status-row muted">No managed memory status available.</div>';
    }

    const enabled = !!this._status.enabled;
    const parent = this._status.parent_flag;
    const child = this._status.child_flags;
    const beta = this._status.beta_header;
    const fallback = this._status.last_fallback_ts;

    const childSummary = child && typeof child === 'object'
      ? Object.entries(child)
          .map(([k, v]) => `${this._escapeHtml(k)}=${this._escapeHtml(v)}`)
          .join(', ')
      : (child === undefined || child === null ? '' : String(child));

    return `
      <div class="status-grid">
        <div class="status-cell">
          <div class="status-label">Enabled</div>
          <div class="status-value ${enabled ? 'on' : 'off'}">${enabled ? 'true' : 'false'}</div>
        </div>
        <div class="status-cell">
          <div class="status-label">Parent flag</div>
          <div class="status-value">${this._escapeHtml(parent === undefined ? '-' : parent)}</div>
        </div>
        <div class="status-cell">
          <div class="status-label">Child flags</div>
          <div class="status-value">${this._escapeHtml(childSummary || '-')}</div>
        </div>
        <div class="status-cell">
          <div class="status-label">Beta header</div>
          <div class="status-value mono">${this._escapeHtml(beta || '-')}</div>
        </div>
        <div class="status-cell">
          <div class="status-label">Last fallback</div>
          <div class="status-value mono">${this._escapeHtml(this._formatTimestamp(fallback) || '-')}</div>
        </div>
      </div>
    `;
  }

  _renderDisabledNotice() {
    return `
      <div class="disabled-notice" role="status">
        <div class="disabled-title">Managed memory is disabled</div>
        <div class="disabled-body">
          The managed memory beta surface is not active for this session.
          Enable it via the parent feature flag and reload to view events
          and memory versions.
        </div>
      </div>
    `;
  }

  _renderEventsSection() {
    if (this._eventsLoading) {
      return '<div class="events-empty muted">Loading events...</div>';
    }
    if (this._eventsError) {
      return `
        <div class="error-banner" role="alert">
          <strong>Events error:</strong>
          <span>${this._escapeHtml(this._eventsError)}</span>
        </div>
      `;
    }
    if (!this._events.length) {
      return '<div class="events-empty muted">No managed memory events recorded yet.</div>';
    }

    const rows = this._events.map((event) => {
      const ts = this._formatTimestamp(event && (event.ts || event.timestamp || event.time));
      const type = event && (event.type || event.event_type || event.kind || 'event');
      const memoryId = event && (event.memory_id || event.memoryId || event.id || '');
      const summaryRaw = event && (event.summary || event.message || event.detail || '');
      const summary = typeof summaryRaw === 'string'
        ? summaryRaw
        : JSON.stringify(summaryRaw);

      return `
        <tr>
          <td class="mono nowrap">${this._escapeHtml(ts)}</td>
          <td><span class="badge">${this._escapeHtml(type)}</span></td>
          <td class="mono">${this._escapeHtml(memoryId)}</td>
          <td>${this._escapeHtml(summary)}</td>
        </tr>
      `;
    }).join('');

    const sourceLabel = this._eventsSource
      ? `<span class="source-tag">source: ${this._escapeHtml(this._eventsSource)}</span>`
      : '';

    return `
      <div class="events-meta">
        <span class="muted">${this._eventsCount} event(s)</span>
        ${sourceLabel}
      </div>
      <div class="events-table-wrap">
        <table class="events-table">
          <thead>
            <tr>
              <th>Timestamp</th>
              <th>Type</th>
              <th>Memory ID</th>
              <th>Summary</th>
            </tr>
          </thead>
          <tbody>${rows}</tbody>
        </table>
      </div>
    `;
  }

  _renderLookupSection() {
    let resultBlock = '';
    if (this._lookupLoading) {
      resultBlock = '<div class="lookup-result muted">Loading memory versions...</div>';
    } else if (this._lookupError) {
      resultBlock = `
        <div class="error-banner" role="alert">
          <strong>Lookup error:</strong>
          <span>${this._escapeHtml(this._lookupError)}</span>
        </div>
      `;
    } else if (this._lookupResult !== null && this._lookupResult !== undefined) {
      let pretty;
      try {
        pretty = JSON.stringify(this._lookupResult, null, 2);
      } catch (e) {
        pretty = String(this._lookupResult);
      }
      resultBlock = `<pre class="lookup-result mono">${this._escapeHtml(pretty)}</pre>`;
    }

    const inputValue = this._escapeHtml(this._lookupId || '');

    return `
      <div class="lookup-controls">
        <input
          id="lookup-input"
          type="text"
          class="lookup-input"
          placeholder="Memory ID (e.g. mem_abc123)"
          value="${inputValue}"
          autocomplete="off"
          spellcheck="false"
        />
        <button id="lookup-btn" class="btn btn-primary" type="button">
          Look up versions
        </button>
      </div>
      ${resultBlock}
    `;
  }

  render() {
    if (!this.shadowRoot) return;

