/**
 * @fileoverview <loki-mascot-presence> - a small, honest Loki presence for the
 * dashboard chrome. Renders the brand mascot (<loki-mascot>) and picks his
 * expression from the live run state, so the engine's own dashboard shows the
 * same character that appears everywhere else the engine is used.
 *
 * Honesty: the top-level /api/status only distinguishes idle / running /
 * autonomous / paused / stopped. It carries NO verified/failed signal, so this
 * component deliberately maps ONLY to states it can prove:
 *   - idle / stopped / offline        -> Loki "idle"     (resting, claims nothing)
 *   - running / autonomous            -> Loki "building" (focused work)
 *   - paused                          -> Loki "sleeping" (paused; not done, not failed)
 * It never shows "celebrating" (a VERIFIED result) or "concerned" (a failure),
 * because neither is reachable from this surface without real proof plumbing.
 * Mapping reference: packages/loki-mascot/CHARACTER.md (build-state mapping).
 *
 * It reuses the shared API client's STATUS_UPDATE stream (the same one the rest
 * of the dashboard listens to) rather than starting its own poll.
 *
 * @example
 * <loki-mascot-presence api-url="http://localhost:57374" size="34"></loki-mascot-presence>
 */

import { getApiClient, ApiEvents } from '../core/loki-api-client.js';
import { registerPoll } from '../core/loki-poll-registry.js';
// Side-effect import: registers the <loki-mascot> custom element. Vendored from
// autonomi-saas (see components/vendor/loki-mascot/PROVENANCE.md).
import './vendor/loki-mascot/loki-mascot.js';

/** Map a top-level run status to an honest Loki emotion. */
function emotionForStatus(status) {
  switch ((status || '').toLowerCase()) {
    case 'running':
    case 'autonomous':
      return 'building';
    case 'paused':
      return 'sleeping';
    // idle, stopped, offline, '' and anything unknown -> calm, claims nothing.
    default:
      return 'idle';
  }
}

export class LokiMascotPresence extends HTMLElement {
  static get observedAttributes() {
    return ['api-url', 'size'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this._status = 'idle';
    this._api = null;
    this._statusHandler = null;
    this._discHandler = null;
    this._poll = null;
  }

  connectedCallback() {
    this._setupApi();
    this._loadStatus();
    this._startPolling();
    this.render();
  }

  disconnectedCallback() {
    if (this._poll) {
      this._poll.stop();
      this._poll = null;
    }
    this._teardownApiListeners();
  }

  _teardownApiListeners() {
    if (this._api) {
      if (this._statusHandler) this._api.removeEventListener(ApiEvents.STATUS_UPDATE, this._statusHandler);
      if (this._discHandler) this._api.removeEventListener(ApiEvents.DISCONNECTED, this._discHandler);
    }
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    if (name === 'api-url' && this._api) {
      // Adopt the correct per-URL client (no in-place baseUrl mutation, which
      // leaks across projects). Detach from the old instance, swap, re-subscribe.
      this._teardownApiListeners();
      this._setupApi();
      this._loadStatus();
    }
    if (name === 'size') {
      this.render();
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });

    this._statusHandler = (e) => this._updateFromStatus(e.detail);
    // A dropped connection means we cannot prove a run is happening: rest.
    this._discHandler = () => { this._status = 'offline'; this.render(); };

    this._api.addEventListener(ApiEvents.STATUS_UPDATE, this._statusHandler);
    this._api.addEventListener(ApiEvents.DISCONNECTED, this._discHandler);
  }

  _startPolling() {
    // Header chrome (always visible, not inside a section page), so it opts OUT
    // of section gating (sectionId: null) and polls on tab visibility only. The
    // STATUS_UPDATE subscription gives instant updates when the shared WS is
    // connected; this poll guarantees the expression still tracks a run that
    // starts later even if no other component has opened the WS. connectedCallback
    // already did the first load, so immediate is disabled (no duplicate fetch).
    this._poll = registerPoll({
      loadFn: () => this._loadStatus(),
      intervalMs: 10000,
      sectionId: null,
      immediate: false,
    });
  }

  async _loadStatus() {
    const api = this._api;
    try {
      const status = await api.getStatus();
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      this._updateFromStatus(status);
    } catch {
      if (api !== this._api) return;
      this._status = 'offline';
      this.render();
    }
  }

  _updateFromStatus(status) {
    if (!status) return;
    const next = status.status || 'idle';
    if (next !== this._status) {
      this._status = next;
      this.render();
    }
  }

  render() {
    if (!this.shadowRoot) return;
    const size = this.getAttribute('size') || '34';
    const emotion = emotionForStatus(this._status);

    // The mascot is self-contained (Shadow DOM, brand-exact, a11y, reduced
    // motion). We only host it and size it; its own aria-label names the state.
    this.shadowRoot.innerHTML = `
      <style>
        :host { display: inline-flex; align-items: center; line-height: 0; }
        loki-mascot { display: inline-block; }
      </style>
      <loki-mascot emotion="${emotion}" size="${size}"></loki-mascot>
    `;
  }
}

if (!customElements.get('loki-mascot-presence')) {
  customElements.define('loki-mascot-presence', LokiMascotPresence);
}

export default LokiMascotPresence;

/**
 * @fileoverview Loki Memory Browser Component - tabbed browser for the
 * Loki Mode memory system covering episodic, semantic, and procedural
 * memory layers. Includes summary view, detail panels, token economics,
 * and memory consolidation controls.
 *
 * @example
 * <loki-memory-browser api-url="http://localhost:57374" theme="dark" tab="summary"></loki-memory-browser>
 */

import { LokiElement } from '../core/loki-theme.js';
import { getApiClient } from '../core/loki-api-client.js';

/** @type {Array<{id: string, label: string, icon: string}>} Tab definitions with SVG path data */
const TABS = [
  { id: 'summary', label: 'Summary', icon: 'M4 6h16M4 12h16M4 18h16' },
  { id: 'search', label: 'Search', icon: 'M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z' },
  { id: 'episodes', label: 'Episodes', icon: 'M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z' },
  { id: 'patterns', label: 'Patterns', icon: 'M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z' },
  { id: 'skills', label: 'Skills', icon: 'M13 10V3L4 14h7v7l9-11h-7z' },
];

/**
 * @class LokiMemoryBrowser
 * @extends LokiElement
 * @fires episode-select - When an episode item is clicked
 * @fires pattern-select - When a pattern item is clicked
 * @fires skill-select - When a skill item is clicked
 * @property {string} api-url - API base URL (default: window.location.origin)
 * @property {string} theme - 'light' or 'dark' (default: auto-detect)
 * @property {string} tab - Initial active tab ('summary'|'episodes'|'patterns'|'skills')
 */
export class LokiMemoryBrowser extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'theme', 'tab'];
  }

  constructor() {
    super();
    this._activeTab = 'summary';
    this._loading = false;
    this._error = null;
    this._api = null;

    // Data
    this._summary = null;
    this._stats = null;
    this._episodes = [];
    this._patterns = [];
    this._skills = [];
    this._tokenEconomics = null;
    this._selectedItem = null;
    this._lastFocusedElement = null;

    // Search state
    this._searchQuery = '';
    this._searchCollection = 'all';
    this._searchResults = [];
    this._searchLoading = false;
    this._searchError = null;
  }

  connectedCallback() {
    super.connectedCallback();
    this._activeTab = this.getAttribute('tab') || 'summary';
    this._setupApi();
    this._loadData();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;

    switch (name) {
      case 'api-url':
        if (this._api) {
          this._api = getApiClient({ baseUrl: newValue });
          this._loadData();
        }
        break;
      case 'theme':
        this._applyTheme();
        break;
      case 'tab':
        this._setTab(newValue);
        break;
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });
  }

  async _loadData() {
    // Drop a stale response if the api-url switched mid-flight.
    const api = this._api;
    this._loading = true;
    this._error = null;
    this.render();

    try {
      // Load summary and stats in parallel
      const [summary, economics, stats] = await Promise.allSettled([
        api.getMemorySummary(),
        api.getTokenEconomics(),
        api.getMemoryStats(),
      ]);
      if (api !== this._api) return;
      this._summary = summary.status === 'fulfilled' ? summary.value : null;
      this._tokenEconomics = economics.status === 'fulfilled' ? economics.value : null;
      this._stats = stats.status === 'fulfilled' ? stats.value : null;

      // Load tab-specific data
      await this._loadTabData();
      if (api !== this._api) return;
    } catch (error) {
      if (api !== this._api) return;
      this._error = error.message || 'Failed to load memory data';
    }

    this._loading = false;
    this.render();
  }

  async _loadTabData() {
    // Drop a stale response if the api-url switched mid-flight.
    const api = this._api;
    switch (this._activeTab) {
      case 'episodes': {
        const episodes = await api.listEpisodes({ limit: 50 }).catch(() => []);
        if (api !== this._api) return;
        this._episodes = episodes;
        break;
      }
      case 'patterns': {
        const patterns = await api.listPatterns().catch(() => []);
        if (api !== this._api) return;
        this._patterns = patterns;
        break;
      }
      case 'skills': {
        const skills = await api.listSkills().catch(() => []);
        if (api !== this._api) return;
        this._skills = skills;
        break;
      }
    }
  }

  _setTab(tab) {
    if (this._activeTab === tab) return;

    this._activeTab = tab;
    this._selectedItem = null;
    this._loadTabData().then(() => this.render());
  }

  async _selectEpisode(episodeId) {
    // Drop a stale response if the api-url switched mid-flight.
    const api = this._api;
    try {
      this._lastFocusedElement = this.shadowRoot.activeElement;
      const item = await api.getEpisode(episodeId);
      if (api !== this._api) return;
      this._selectedItem = item;
      this.dispatchEvent(new CustomEvent('episode-select', { detail: this._selectedItem }));
      this.render();
      this._focusDetailPanel();
    } catch (error) {
      console.error('Failed to load episode:', error);
    }
  }

  async _selectPattern(patternId) {
    // Drop a stale response if the api-url switched mid-flight.
    const api = this._api;
    try {
      this._lastFocusedElement = this.shadowRoot.activeElement;
      const item = await api.getPattern(patternId);
      if (api !== this._api) return;
      this._selectedItem = item;
      this.dispatchEvent(new CustomEvent('pattern-select', { detail: this._selectedItem }));
      this.render();
      this._focusDetailPanel();
    } catch (error) {
      console.error('Failed to load pattern:', error);
    }
  }

  async _selectSkill(skillId) {
    // Drop a stale response if the api-url switched mid-flight.
    const api = this._api;
    try {
      this._lastFocusedElement = this.shadowRoot.activeElement;
      const item = await api.getSkill(skillId);
      if (api !== this._api) return;
      this._selectedItem = item;
      this.dispatchEvent(new CustomEvent('skill-select', { detail: this._selectedItem }));
      this.render();
      this._focusDetailPanel();
    } catch (error) {
      console.error('Failed to load skill:', error);
    }
  }

  _focusDetailPanel() {
    requestAnimationFrame(() => {
      const closeBtn = this.shadowRoot.getElementById('close-detail');
      if (closeBtn) {
        closeBtn.focus();
      }
    });
  }

  _closeDetail() {
    this._selectedItem = null;
    this.render();
    // Return focus to last focused element
    if (this._lastFocusedElement) {
      requestAnimationFrame(() => {
        this._lastFocusedElement.focus();
        this._lastFocusedElement = null;
      });
    }
  }

  async _triggerConsolidation() {
    try {
      const result = await this._api.consolidateMemory(24);
      alert(`Consolidation complete:\n- Patterns created: ${result.patternsCreated}\n- Patterns merged: ${result.patternsMerged}\n- Episodes processed: ${result.episodesProcessed}`);
      this._loadData();
    } catch (error) {
      alert('Consolidation failed: ' + error.message);
    }
  }

  async _executeSearch() {
    const query = this._searchQuery.trim();
    if (!query) return;

    // Drop a stale response if the api-url switched mid-flight.
    const api = this._api;
    this._searchLoading = true;
    this._searchError = null;
    this.render();

    try {
      const result = await api.searchMemory(query, this._searchCollection, 20);
      if (api !== this._api) return;
      this._searchResults = result.results || [];
    } catch (error) {
      if (api !== this._api) return;
      this._searchError = error.message || 'Search failed';
      this._searchResults = [];
    }

    this._searchLoading = false;
    this.render();
    // Re-focus the search input after render
    requestAnimationFrame(() => {
      const input = this.shadowRoot.getElementById('memory-search-input');
      if (input) input.focus();
    });
  }

  _renderSearch() {
    const collectionOptions = ['all', 'episodes', 'patterns', 'skills'];
    return `
      <div class="search-panel">
        <div class="search-bar">
          <input type="text" id="memory-search-input" class="search-input"
                 placeholder="Search memory..."
                 value="${this._escapeHtml(this._searchQuery)}"
                 aria-label="Search memory">
          <select id="memory-search-collection" class="search-select" aria-label="Collection filter">
            ${collectionOptions.map(c => `<option value="${c}" ${this._searchCollection === c ? 'selected' : ''}>${c}</option>`).join('')}
          </select>
          <button class="btn btn-primary" id="search-btn" ${this._searchLoading ? 'disabled' : ''}>
            ${this._searchLoading ? 'Searching...' : 'Search'}
          </button>
        </div>
        ${this._searchError ? `<div class="search-error">Error: ${this._escapeHtml(this._searchError)}</div>` : ''}
        ${this._searchResults.length > 0 ? `
          <div class="search-results-header">
            <span>${this._searchResults.length} result${this._searchResults.length !== 1 ? 's' : ''} for "${this._escapeHtml(this._searchQuery)}"</span>
          </div>
          <div class="item-list" role="list" aria-label="Search results">
            ${this._searchResults.map(r => `
              <div class="item-card search-result" tabindex="0" role="listitem"
                   aria-label="${this._escapeHtml(r.collection || 'unknown')}: ${this._escapeHtml(r.snippet || r.id)}">
                <div class="item-header">
                  <span class="item-category">${this._escapeHtml(r.collection || 'unknown')}</span>
                  <span class="item-id mono">${this._escapeHtml(r.id || '')}</span>
                </div>
                <div class="item-title">${this._escapeHtml(r.snippet || r.id || '')}</div>
                <div class="item-meta">
                  ${r.rank != null ? `<span>Rank: ${r.rank}</span>` : ''}
                  ${r.category ? `<span>${this._escapeHtml(r.category)}</span>` : ''}
                  ${r.timestamp ? `<span>${new Date(r.timestamp).toLocaleString()}</span>` : ''}
                </div>
              </div>
            `).join('')}
          </div>
        ` : (!this._searchLoading && this._searchQuery ? '<div class="empty-state">No results found</div>' : '')}
        ${!this._searchQuery ? '<div class="empty-state">Enter a query to search across all memory layers using full-text search</div>' : ''}
