              <span class="detail-value">${item.durationSeconds || 0}s</span>
            </div>
            <div class="detail-row">
              <span class="detail-label">Tokens Used</span>
              <span class="detail-value">${item.tokensUsed?.toLocaleString() || 0}</span>
            </div>
            ${item.goal ? `
