              <div class="detail-section">
                <div class="detail-label">Prerequisites</div>
                <ul class="detail-list">
                  ${item.prerequisites.map(p => `<li>${this._escapeHtml(p)}</li>`).join('')}
                </ul>
              </div>
            ` : ''}
            ${item.steps?.length ? `
              <div class="detail-section">
                <div class="detail-label">Steps</div>
                <ol class="detail-list numbered">
                  ${item.steps.map(s => `<li>${this._escapeHtml(s)}</li>`).join('')}
                </ol>
              </div>
            ` : ''}
            ${item.exitCriteria?.length ? `
              <div class="detail-section">
                <div class="detail-label">Exit Criteria</div>
                <ul class="detail-list">
                  ${item.exitCriteria.map(e => `<li>${this._escapeHtml(e)}</li>`).join('')}
                </ul>
              </div>
            ` : ''}
          </div>
        </div>
      `;
    }

    return '';
  }

  _escapeHtml(text) {
    if (text === null || text === undefined) return '';
    // Quote-safe: the textContent round-trip escapes < > & but NOT quotes, and
    // this value is interpolated into double-quoted HTML attributes (data-id,
    // aria-label). A raw " would break out of the attribute and inject an event
    // handler, so we escape quotes explicitly too.
    return String(text)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

