/**
 * @fileoverview Loki Migration Dashboard Component - displays migration status,
 * phase progress, feature tracking, seam summary, and migration history.
 *
 * Polls /api/migration/list on load, then /api/migration/{id}/status every 15s
 * for active migrations.
 *
 * @example
 * <loki-migration-dashboard api-url="http://localhost:57374"></loki-migration-dashboard>
 */

import { LokiElement } from '../core/loki-theme.js';
import { getApiClient } from '../core/loki-api-client.js';
import { registerPoll } from '../core/loki-poll-registry.js';

const PHASES = ['understand', 'guardrail', 'migrate', 'verify'];
const PHASE_LABELS = { understand: 'Understand', guardrail: 'Guardrail', migrate: 'Migrate', verify: 'Verify' };
const PHASE_COLORS = { understand: '#5b9bd5', guardrail: '#e8b84a', migrate: '#5bb870', verify: '#5bc8c8' };

/**
 * @class LokiMigrationDashboard
 * @extends LokiElement
 * @property {string} api-url - API base URL (default: window.location.origin)
 */
export class LokiMigrationDashboard extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'theme'];
  }

  constructor() {
    super();
    this._migration = null;
    this._migrations = [];
    this._loading = true;
    this._error = null;
    this._api = null;
    this._pollInterval = null;
  }

  connectedCallback() {
    super.connectedCallback();
    this._setupApi();
    this._fetchMigrations();
    // Central registry gates this poll to the active + visible section (one
    // place enforces visibility + active-view); the initial load above runs
    // eagerly, so immediate is disabled to avoid a duplicate fetch.
    this._poll = registerPoll({
      loadFn: () => this._fetchData(),
      intervalMs: 15000,
      element: this,
      immediate: false,
    });
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    if (this._poll) {
      this._poll.stop();
      this._poll = null;
    }
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    if (name === 'api-url' && this._api) {
      this._api = getApiClient({ baseUrl: newValue });
      this._fetchMigrations();
    }
    if (name === 'theme') {
      this._applyTheme();
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });
  }

  async _fetchMigrations() {
    // Drop a stale response if the api-url switched mid-flight.
    const api = this._api;
    try {
      const result = await api._get('/api/migration/list');
      if (api !== this._api) return;
      this._migrations = Array.isArray(result) ? result : (result.migrations || []);
      this._error = null;
      const active = this._migrations.find(m => m.status === 'in_progress' || m.status === 'active');
      if (active) {
        await this._fetchStatus(active.migration_id || active.id);
        if (api !== this._api) return;
      } else {
        this._migration = null;
      }
    } catch (err) {
      if (api !== this._api) return;
      this._error = err.message;
      this._migrations = [];
      this._migration = null;
    }
    this._loading = false;
    this.render();
  }

  async _fetchStatus(id) {
    // Drop a stale response if the api-url switched mid-flight.
    const api = this._api;
    try {
      const migration = await api._get(`/api/migration/${encodeURIComponent(id)}/status`);
      if (api !== this._api) return;
      this._migration = migration;
      this._error = null;
    } catch (err) {
      if (api !== this._api) return;
      this._error = err.message;
    }
  }

  async _fetchData() {
    // Drop a stale response if the api-url switched mid-flight.
    const api = this._api;
    const id = this._migration && (this._migration.migration_id || this._migration.id);
    if (id) {
      await this._fetchStatus(id);
      if (api !== this._api) return;
      this.render();
    } else {
      await this._fetchMigrations();
    }
  }

  _escapeHtml(str) {
    if (!str) return '';
    return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#039;');
  }

  _getPhaseIcon(phase, currentPhase, completedPhases) {
    const completed = completedPhases || [];
    if (completed.includes(phase)) return '[x]';
    if (phase === currentPhase) return '[>]';
    return '[ ]';
  }

  _getPhaseIndex(phase) {
    const idx = PHASES.indexOf(phase);
    return idx >= 0 ? idx : 0;
  }

  _renderPhaseBar(currentPhase, completedPhases) {
    const completed = completedPhases || [];
    return PHASES.map(phase => {
      const isDone = completed.includes(phase);
      const isActive = phase === currentPhase;
      const color = PHASE_COLORS[phase];
      const opacity = isDone ? '1' : isActive ? '0.7' : '0.2';
      const icon = this._getPhaseIcon(phase, currentPhase, completedPhases);
      return `
        <div class="phase-segment">
          <div class="phase-bar-fill" style="background:${color};opacity:${opacity};"></div>
          <div class="phase-label">
            <span class="phase-icon">${icon}</span>
            ${PHASE_LABELS[phase]}
          </div>
        </div>
      `;
    }).join('');
  }

  _renderFeatureStats(features) {
    if (!features) return '';
    const passing = features.passing || 0;
    const total = features.total || 0;
    const pct = total > 0 ? Math.round((passing / total) * 100) : 0;
    const barColor = pct >= 80 ? 'var(--loki-success)' : pct >= 50 ? 'var(--loki-warning)' : 'var(--loki-error)';
    return `
      <div class="stat-card">
        <div class="stat-header">Feature Tracking</div>
        <div class="stat-value">${passing} / ${total}</div>
        <div class="stat-pct">${pct}% passing</div>
        <div class="progress-bar">
          <div class="progress-fill" style="width:${pct}%;background:${barColor};"></div>
        </div>
      </div>
    `;
  }

  _renderStepProgress(steps) {
    if (!steps) return '';
    const current = steps.current || 0;
    const total = steps.total || 0;
    const pct = total > 0 ? Math.round((current / total) * 100) : 0;
    return `
      <div class="stat-card">
        <div class="stat-header">Step Progress</div>
        <div class="stat-value">${current} / ${total}</div>
        <div class="stat-pct">${pct}% complete</div>
        <div class="progress-bar">
          <div class="progress-fill" style="width:${pct}%;background:var(--loki-accent);"></div>
        </div>
      </div>
    `;
  }

  _renderSeamSummary(seams) {
    if (!seams) return '';
    const total = seams.total || 0;
    const high = seams.high || 0;
    const medium = seams.medium || 0;
    const low = seams.low || 0;
    return `
      <div class="stat-card">
        <div class="stat-header">Seam Summary</div>
        <div class="stat-value">${total} seams</div>
        <div class="seam-breakdown">
          <span class="seam-badge seam-high">High: ${high}</span>
          <span class="seam-badge seam-medium">Med: ${medium}</span>
          <span class="seam-badge seam-low">Low: ${low}</span>
        </div>
      </div>
    `;
  }

  _renderCheckpoint(checkpoint) {
    if (!checkpoint) return '';
    const ts = checkpoint.timestamp ? new Date(checkpoint.timestamp).toLocaleString() : '--';
    const stepId = this._escapeHtml(checkpoint.step_id || checkpoint.stepId || '--');
    return `
      <div class="checkpoint-section">
        <div class="section-label">Last Checkpoint</div>
        <div class="checkpoint-row">
          <span class="checkpoint-label">Time:</span>
          <span class="checkpoint-value">${this._escapeHtml(ts)}</span>
        </div>
        <div class="checkpoint-row">
          <span class="checkpoint-label">Step:</span>
          <span class="checkpoint-value mono">${stepId}</span>
        </div>
      </div>
    `;
  }

  _renderMigrationList() {
    if (this._migrations.length === 0) {
      return '<div class="empty-state">No migrations found</div>';
    }
    const rows = this._migrations.map(m => {
      const id = this._escapeHtml(m.migration_id || m.id || '--');
      const source = this._escapeHtml(m.source || '--');
      const target = this._escapeHtml(m.target || '--');
      const status = this._escapeHtml(m.status || '--');
      const statusCls = m.status === 'completed' ? 'status-done' : m.status === 'failed' ? 'status-failed' : 'status-pending';
      return `
        <tr>
          <td class="mono">${id}</td>
          <td>${source} -> ${target}</td>
          <td><span class="status-badge ${statusCls}">${status}</span></td>
        </tr>
      `;
    }).join('');
    return `
      <table class="migration-table">
        <thead>
          <tr><th>ID</th><th>Migration</th><th>Status</th></tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    `;
  }

  render() {
    const styles = `
      ${this.getBaseStyles()}

      :host { display: block; }

      .migration-container {
        background: var(--loki-bg-card);
        border: 1px solid var(--loki-glass-border);
        border-radius: 5px;
        padding: 16px;
        transition: all var(--loki-transition);
      }

      .migration-header {
        display: flex;
        align-items: center;
        gap: 8px;
        margin-bottom: 14px;
      }

      .migration-header svg {
        width: 16px;
        height: 16px;
        color: var(--loki-text-muted);
        flex-shrink: 0;
      }

      .migration-title {
        font-size: 12px;
        font-weight: 600;
        text-transform: uppercase;
        letter-spacing: 0.05em;
        color: var(--loki-text-muted);
      }

      .migration-id {
        margin-left: auto;
        font-size: 11px;
        font-family: 'JetBrains Mono', monospace;
        color: var(--loki-text-muted);
      }

      .meta-row {
        display: flex;
        align-items: center;
        gap: 16px;
        margin-bottom: 14px;
        flex-wrap: wrap;
      }

      .meta-item {
        font-size: 12px;
        color: var(--loki-text-secondary);
      }

      .meta-label {
        font-weight: 600;
        color: var(--loki-text-muted);
        font-size: 10px;
        text-transform: uppercase;
        letter-spacing: 0.05em;
        display: block;
        margin-bottom: 2px;
      }

      .mono {
        font-family: 'JetBrains Mono', monospace;
      }

      .phase-bar-container {
        display: grid;
        grid-template-columns: repeat(4, 1fr);
        gap: 4px;
        margin-bottom: 16px;
      }

      .phase-segment {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 4px;
      }

      .phase-bar-fill {
        width: 100%;
        height: 8px;
        border-radius: 4px;
        transition: opacity 0.3s ease;
      }

      .phase-label {
        font-size: 10px;
        font-weight: 600;
        text-transform: uppercase;
        letter-spacing: 0.03em;
        color: var(--loki-text-muted);
        display: flex;
        align-items: center;
        gap: 4px;
      }

      .phase-icon {
        font-family: 'JetBrains Mono', monospace;
        font-size: 9px;
      }

      .stats-grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
        gap: 10px;
        margin-bottom: 14px;
      }

      .stat-card {
        background: var(--loki-bg-secondary);
        border: 1px solid var(--loki-border);
        border-radius: 5px;
        padding: 10px 12px;
      }

      .stat-header {
        font-size: 10px;
        font-weight: 600;
        text-transform: uppercase;
        letter-spacing: 0.05em;
        color: var(--loki-text-muted);
        margin-bottom: 6px;
      }

      .stat-value {
        font-size: 20px;
        font-weight: 700;
        font-family: 'JetBrains Mono', monospace;
        color: var(--loki-text-primary);
        line-height: 1;
        margin-bottom: 4px;
      }

      .stat-pct {
        font-size: 11px;
        color: var(--loki-text-muted);
        margin-bottom: 6px;
      }

      .progress-bar {
        width: 100%;
        height: 6px;
        background: var(--loki-bg-tertiary);
        border-radius: 3px;
        overflow: hidden;
      }

      .progress-fill {
        height: 100%;
        border-radius: 3px;
        transition: width 0.3s ease;
      }

      .seam-breakdown {
        display: flex;
        gap: 6px;
        margin-top: 6px;
        flex-wrap: wrap;
      }

      .seam-badge {
        display: inline-block;
        padding: 2px 8px;
        border-radius: 4px;
        font-size: 10px;
        font-weight: 500;
        font-family: 'JetBrains Mono', monospace;
      }

      .seam-high {
        background: rgba(224, 112, 112, 0.15);
        color: var(--loki-error);
      }

      .seam-medium {
        background: rgba(232, 184, 74, 0.15);
        color: var(--loki-warning);
      }

      .seam-low {
        background: var(--loki-bg-tertiary);
        color: var(--loki-text-muted);
      }

      .checkpoint-section {
        margin-bottom: 14px;
      }

      .section-label {
        font-size: 11px;
        font-weight: 600;
        text-transform: uppercase;
        letter-spacing: 0.05em;
        color: var(--loki-text-muted);
        margin-bottom: 8px;
      }

      .checkpoint-row {
        display: flex;
        gap: 8px;
        align-items: baseline;
        margin-bottom: 4px;
        font-size: 12px;
      }

      .checkpoint-label {
        color: var(--loki-text-muted);
        min-width: 40px;
      }

      .checkpoint-value {
        color: var(--loki-text-secondary);
      }

      .migration-table {
        width: 100%;
        border-collapse: collapse;
        font-size: 12px;
      }

      .migration-table th {
        text-align: left;
        font-size: 10px;
        font-weight: 600;
        text-transform: uppercase;
        letter-spacing: 0.05em;
        color: var(--loki-text-muted);
        padding: 6px 10px;
        border-bottom: 1px solid var(--loki-border);
      }

      .migration-table td {
        padding: 8px 10px;
        color: var(--loki-text-secondary);
        border-bottom: 1px solid var(--loki-border);
      }

      .migration-table tbody tr:last-child td {
        border-bottom: none;
      }

      .status-badge {
        display: inline-block;
        padding: 2px 8px;
        border-radius: 4px;
        font-size: 10px;
        font-weight: 500;
      }

      .status-done {
        background: rgba(91, 184, 112, 0.15);
        color: var(--loki-success);
      }

      .status-failed {
        background: rgba(224, 112, 112, 0.15);
        color: var(--loki-error);
      }

      .status-pending {
        background: var(--loki-bg-tertiary);
        color: var(--loki-text-muted);
      }

      .empty-state {
        text-align: center;
        padding: 20px;
        color: var(--loki-text-muted);
        font-size: 12px;
      }

      .loading-state {
        display: flex;
        align-items: center;
        justify-content: center;
        padding: 20px;
        gap: 8px;
        color: var(--loki-text-muted);
        font-size: 12px;
      }

      .spinner {
        width: 14px;
        height: 14px;
        border: 2px solid var(--loki-border);
        border-top-color: var(--loki-accent);
        border-radius: 50%;
        animation: spin 0.8s linear infinite;
      }

      @keyframes spin {
        to { transform: rotate(360deg); }
      }
    `;

    const icon = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="16 3 21 3 21 8"/><line x1="4" y1="20" x2="21" y2="3"/><polyline points="21 16 21 21 16 21"/><line x1="15" y1="15" x2="21" y2="21"/><line x1="4" y1="4" x2="9" y2="9"/></svg>`;

    if (this._loading) {
      this.shadowRoot.innerHTML = `
        <style>${styles}</style>
        <div class="migration-container">
          <div class="loading-state"><div class="spinner"></div> Loading migrations...</div>
        </div>
      `;
      return;
    }

    if (this._error && !this._migration && this._migrations.length === 0) {
      this.shadowRoot.innerHTML = `
        <style>${styles}</style>
        <div class="migration-container">
          <div class="migration-header">
            ${icon}
            <span class="migration-title">Migration Dashboard</span>
          </div>
          <div class="empty-state">No migration data available</div>
        </div>
      `;
      return;
    }

    // Active migration view
    if (this._migration) {
      const m = this._migration;
      const migId = this._escapeHtml(m.migration_id || m.id || '--');
      const source = this._escapeHtml(m.source || '--');
      const target = this._escapeHtml(m.target || '--');
      const currentPhase = m.current_phase || m.phase || 'understand';
      const completedPhases = m.completed_phases || [];

      this.shadowRoot.innerHTML = `
        <style>${styles}</style>
        <div class="migration-container">
          <div class="migration-header">
            ${icon}
            <span class="migration-title">Migration Dashboard</span>
            <span class="migration-id">${migId}</span>
          </div>

          <div class="meta-row">
            <div class="meta-item">
              <span class="meta-label">Source</span>
              <span class="mono">${source}</span>
            </div>
            <div class="meta-item">
              <span class="meta-label">-></span>
            </div>
            <div class="meta-item">
              <span class="meta-label">Target</span>
              <span class="mono">${target}</span>
            </div>
            <div class="meta-item">
              <span class="meta-label">Phase</span>
              <span>${PHASE_LABELS[currentPhase] || this._escapeHtml(currentPhase)}</span>
            </div>
          </div>

          <div class="section-label">Phase Progress</div>
          <div class="phase-bar-container">
            ${this._renderPhaseBar(currentPhase, completedPhases)}
          </div>

          <div class="stats-grid">
            ${this._renderFeatureStats(m.features)}
            ${this._renderStepProgress(m.steps)}
            ${this._renderSeamSummary(m.seams)}
          </div>

          ${this._renderCheckpoint(m.last_checkpoint || m.checkpoint)}
        </div>
      `;
      return;
    }

    // Migration list view (no active migration)
    this.shadowRoot.innerHTML = `
      <style>${styles}</style>
      <div class="migration-container">
        <div class="migration-header">
          ${icon}
          <span class="migration-title">Migration Dashboard</span>
        </div>
        <div class="section-label">Migrations</div>
        ${this._renderMigrationList()}
      </div>
    `;
  }
}

if (!customElements.get('loki-migration-dashboard')) {
  customElements.define('loki-migration-dashboard', LokiMigrationDashboard);
}

export default LokiMigrationDashboard;

/**
 * @fileoverview Loki Notification Center Component - enhanced notification
 * system with bell icon, unread count badge, notification categories
 * (Build, Quality, System, Security), time grouping, mark as read/unread,
 * action buttons, and trigger configuration.
 *
 * @example
 * <loki-notification-center api-url="http://localhost:57374" theme="dark"></loki-notification-center>
 */

import { LokiElement } from '../core/loki-theme.js';
import { getApiClient } from '../core/loki-api-client.js';
import { registerPoll } from '../core/loki-poll-registry.js';

/**
 * Severity color mapping used for dots and badges.
 * @type {Object<string, string>}
 */
const SEVERITY_COLORS = {
  critical: 'var(--loki-red, #ef4444)',
  warning:  'var(--loki-yellow, #eab308)',
  info:     'var(--loki-blue, #3b82f6)',
  success:  'var(--loki-green, #1FC5A8)',
};

/**
 * Notification categories with icons and labels.
 * @type {Object<string, {label: string, icon: string}>}
 */
const CATEGORIES = {
  build:    { label: 'Build',    icon: 'B' },
  quality:  { label: 'Quality',  icon: 'Q' },
  system:   { label: 'System',   icon: 'S' },
  security: { label: 'Security', icon: '!' },
};

/**
 * @class LokiNotificationCenter
 * @extends LokiElement
 * @property {string} api-url - API base URL (default: window.location.origin)
 * @property {string} theme - 'light' or 'dark' (default: auto-detect)
 */
export class LokiNotificationCenter extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'theme'];
  }

  constructor() {
    super();
    this._notifications = [];
    this._triggers = [];
    this._summary = {};
    this._connected = false;
    this._activeTab = 'feed';
    this._categoryFilter = 'all';
    this._panelOpen = true;
    this._pollInterval = null;
  }

  connectedCallback() {
    super.connectedCallback();
    this._loadNotifications();
    this._loadTriggers();
    this._startPolling();
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this._stopPolling();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    if (name === 'api-url') {
      this._loadNotifications();
      this._loadTriggers();
    }
    if (name === 'theme') {
      this._applyTheme();
    }
  }

  // -- Data fetching --

  async _loadNotifications() {
    try {
      const apiUrl = this.getAttribute('api-url') || window.location.origin;
      const resp = await fetch(apiUrl + '/api/notifications');
      if (resp.ok) {
        const data = await resp.json();
        this._notifications = data.notifications || [];
        this._summary = data.summary || {};
        this._connected = true;
      }
    } catch {
      this._connected = false;
    }
    this.render();
  }

  async _loadTriggers() {
    try {
      const apiUrl = this.getAttribute('api-url') || window.location.origin;
      const resp = await fetch(apiUrl + '/api/notifications/triggers');
      if (resp.ok) {
        const data = await resp.json();
        this._triggers = data.triggers || [];
      }
    } catch {
      // Keep existing triggers
    }
  }

  async _acknowledgeNotification(id) {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    try {
      await fetch(apiUrl + '/api/notifications/' + encodeURIComponent(id) + '/acknowledge', { method: 'POST' });
    } catch {
      // Network/abort failure on acknowledge is non-fatal; the reload below
      // (also guarded) reflects the true server state. Swallow so it does not
      // surface as an unhandled promise rejection in the console.
    }
    this._loadNotifications();
  }

  async _unacknowledgeNotification(id) {
    // Mark as unread by toggling acknowledge state
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    await fetch(apiUrl + '/api/notifications/' + encodeURIComponent(id) + '/unacknowledge', { method: 'POST' });
    this._loadNotifications();
  }

  async _acknowledgeAll() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    const unacked = this._notifications.filter(n => !n.acknowledged);
    for (const n of unacked) {
      await fetch(apiUrl + '/api/notifications/' + encodeURIComponent(n.id) + '/acknowledge', { method: 'POST' });
    }
    this._loadNotifications();
  }

  async _toggleTrigger(triggerId, enabled) {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    const triggers = this._triggers.map(t => t.id === triggerId ? { ...t, enabled } : t);
    await fetch(apiUrl + '/api/notifications/triggers', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ triggers }),
    });
    this._triggers = triggers;
    this.render();
  }

  // -- Polling --

  _startPolling() {
    // Central registry (core/loki-poll-registry.js) gates this poll to the
    // active + visible section in ONE place, so a hidden tab or background
    // section does not fetch. connectedCallback already did the first load,
    // so immediate is disabled to avoid a duplicate fetch.
    this._poll = registerPoll({
      loadFn: () => {
        this._loadNotifications();
        this._loadTriggers();
      },
      intervalMs: 5000,
      element: this,
      immediate: false,
    });
  }

  _stopPolling() {
    if (this._poll) {
      this._poll.stop();
      this._poll = null;
    }
  }

  // -- Helpers --

  _formatTime(timestamp) {
    if (!timestamp) return '';
    try {
      const date = new Date(timestamp);
      const now = new Date();
      const diffMs = now - date;
      const diffSec = Math.floor(diffMs / 1000);
      const diffMin = Math.floor(diffSec / 60);
      const diffHr = Math.floor(diffMin / 60);
      const diffDay = Math.floor(diffHr / 24);

      if (diffSec < 60) return diffSec + 's ago';
      if (diffMin < 60) return diffMin + 'm ago';
      if (diffHr < 24) return diffHr + 'h ago';
      if (diffDay < 7) return diffDay + 'd ago';
      return date.toLocaleDateString();
    } catch {
      return String(timestamp);
    }
  }

  _getTimeGroup(timestamp) {
    if (!timestamp) return 'Other';
    try {
      const date = new Date(timestamp);
      const now = new Date();
      const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      const yesterday = new Date(today);
      yesterday.setDate(yesterday.getDate() - 1);
      const weekAgo = new Date(today);
      weekAgo.setDate(weekAgo.getDate() - 7);

      if (date >= today) return 'Today';
      if (date >= yesterday) return 'Yesterday';
      if (date >= weekAgo) return 'This Week';
      return 'Earlier';
    } catch {
      return 'Other';
    }
  }

  _escapeHTML(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  _getSeverityColor(severity) {
    return SEVERITY_COLORS[severity] || SEVERITY_COLORS.info;
  }

  _getCategory(notification) {
    return notification.category || notification.type || 'system';
  }

  // -- Tab switching --

  _switchTab(tab) {
    this._activeTab = tab;
    this.render();
  }

  _setCategoryFilter(cat) {
    this._categoryFilter = cat;
    this.render();
  }

  _togglePanel() {
    this._panelOpen = !this._panelOpen;
    this.render();
  }

  // -- Event binding --

  _bindEvents() {
    const root = this.shadowRoot;

    // Tab buttons
    root.querySelectorAll('.tab').forEach(btn => {
      btn.addEventListener('click', () => {
        this._switchTab(btn.dataset.tab);
      });
    });

    // Category filter buttons
    root.querySelectorAll('.cat-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        this._setCategoryFilter(btn.dataset.cat);
      });
    });

    // Acknowledge buttons
    root.querySelectorAll('.ack-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        this._acknowledgeNotification(btn.dataset.id);
      });
    });

    // Mark as unread buttons
    root.querySelectorAll('.unread-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        this._unacknowledgeNotification(btn.dataset.id);
      });
    });

    // Acknowledge All / Mark all as read button
    const ackAllBtn = root.querySelector('.ack-all-btn');
    if (ackAllBtn) {
      ackAllBtn.addEventListener('click', () => {
        this._acknowledgeAll();
      });
    }

    // Bell icon toggle
    const bellBtn = root.querySelector('.bell-icon');
    if (bellBtn) {
      bellBtn.addEventListener('click', () => {
        this._togglePanel();
      });
    }

    // Toggle switches
    root.querySelectorAll('.toggle input').forEach(input => {
      input.addEventListener('change', () => {
        this._toggleTrigger(input.dataset.triggerId, input.checked);
      });
    });

    // Dismiss buttons
    root.querySelectorAll('.dismiss-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        this._acknowledgeNotification(btn.dataset.id);
      });
    });
  }

  // -- Render helpers --

  _renderBellIcon() {
    const unread = this._summary.unacknowledged || 0;
    return `
      <div class="bell-container">
        <button class="bell-icon" title="${unread} unread notifications">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"></path>
            <path d="M13.73 21a2 2 0 0 1-3.46 0"></path>
          </svg>
          ${unread > 0 ? `<span class="badge">${unread > 99 ? '99+' : unread}</span>` : ''}
        </button>
      </div>
    `;
  }

  _renderSummaryBar() {
    const total = this._summary.total || 0;
    const unack = this._summary.unacknowledged || 0;
    const critical = this._summary.critical || 0;

    return `
      <div class="summary-row">
        <div class="summary-grid">
          <div class="summary-card">
            <div class="card-label">Total</div>
            <div class="card-value">${total}</div>
          </div>
          <div class="summary-card">
            <div class="card-label">Unread</div>
            <div class="card-value">${unack}</div>
          </div>
          <div class="summary-card">
            <div class="card-label">Critical</div>
            <div class="card-value" style="color: ${SEVERITY_COLORS.critical}">${critical}</div>
          </div>
        </div>
        ${unack > 0 ? `
          <button class="ack-all-btn">Mark All as Read</button>
        ` : ''}
      </div>
    `;
  }

  _renderCategoryFilter() {
    const cats = ['all', 'build', 'quality', 'system', 'security'];
    return `
      <div class="category-bar">
        ${cats.map(cat => {
          const isActive = this._categoryFilter === cat;
          const label = cat === 'all' ? 'All' : (CATEGORIES[cat]?.label || cat);
          return `<button class="cat-btn ${isActive ? 'active' : ''}" data-cat="${cat}">${label}</button>`;
        }).join('')}
      </div>
    `;
  }

  _renderNotificationList() {
    let filtered = [...this._notifications].sort((a, b) => {
      return new Date(b.timestamp) - new Date(a.timestamp);
    });

    if (this._categoryFilter !== 'all') {
      filtered = filtered.filter(n => this._getCategory(n) === this._categoryFilter);
    }

    if (filtered.length === 0) {
      return '<div class="empty-state">No notifications</div>';
    }

    // Group by time
    const groups = {};
    for (const n of filtered) {
      const group = this._getTimeGroup(n.timestamp);
      if (!groups[group]) groups[group] = [];
      groups[group].push(n);
    }

    const groupOrder = ['Today', 'Yesterday', 'This Week', 'Earlier', 'Other'];
    let html = '';

    for (const group of groupOrder) {
      if (!groups[group] || groups[group].length === 0) continue;
      html += `<div class="time-group-label">${group}</div>`;
      html += groups[group].map(n => {
        const acked = n.acknowledged;
        const severityColor = this._getSeverityColor(n.severity);
        const category = this._getCategory(n);
        const catCfg = CATEGORIES[category] || { label: category, icon: '?' };

        return `
          <div class="notif-row ${acked ? 'acknowledged' : ''}">
            <span class="severity-dot" style="background: ${severityColor};" title="${this._escapeHTML(n.severity)}"></span>
            <span class="cat-icon" title="${this._escapeHTML(catCfg.label)}">${catCfg.icon}</span>
            <span class="notif-time">${this._formatTime(n.timestamp)}</span>
            <span class="notif-message">${this._escapeHTML(n.message)}</span>
            ${n.iteration != null ? `<span class="notif-iteration">iter ${n.iteration}</span>` : ''}
            <span class="notif-actions">
              ${!acked
                ? `<button class="ack-btn" data-id="${this._escapeHTML(n.id)}" title="Mark as read">Read</button>`
                : `<button class="unread-btn" data-id="${this._escapeHTML(n.id)}" title="Mark as unread">Unread</button>`}
              <button class="dismiss-btn" data-id="${this._escapeHTML(n.id)}" title="Dismiss">&#10005;</button>
            </span>
          </div>
        `;
      }).join('');
    }

    return html;
  }

  _renderTriggerList() {
    if (this._triggers.length === 0) {
      return '<div class="empty-state">No triggers configured</div>';
    }

    return this._triggers.map(t => {
      const severityColor = this._getSeverityColor(t.severity);
      const thresholdInfo = t.threshold_pct != null
        ? `Threshold: ${t.threshold_pct}%`
        : (t.pattern || '');

      return `
        <div class="trigger-row">
          <label class="toggle">
            <input type="checkbox" data-trigger-id="${this._escapeHTML(t.id)}" ${t.enabled ? 'checked' : ''}>
            <span class="toggle-slider"></span>
          </label>
          <span class="trigger-name">${this._escapeHTML(t.id)}</span>
          <span class="trigger-badge type-badge">${this._escapeHTML(t.type || 'custom')}</span>
          <span class="trigger-badge severity-badge" style="background: ${severityColor}; color: #fff;">${this._escapeHTML(t.severity || 'info')}</span>
          ${thresholdInfo ? `<span class="trigger-info">${this._escapeHTML(thresholdInfo)}</span>` : ''}
        </div>
      `;
    }).join('');
  }

