/**
 * @fileoverview Loki Overview Component - displays system overview cards
 * in a responsive grid showing session status, phase, iteration, provider,
 * agents, tasks, uptime, and complexity.
 *
 * Polls /api/status every 5 seconds and listens to ApiEvents.STATUS_UPDATE
 * for immediate updates.
 *
 * @example
 * <loki-overview api-url="http://localhost:57374" theme="dark"></loki-overview>
 */

import { LokiElement } from '../core/loki-theme.js';
import { getApiClient, ApiEvents } from '../core/loki-api-client.js';
import { registerPoll } from '../core/loki-poll-registry.js';

/**
 * @class LokiOverview
 * @extends LokiElement
 * @property {string} api-url - API base URL (default: window.location.origin)
 * @property {string} theme - 'light' or 'dark' (default: auto-detect)
 */
export class LokiOverview extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'theme'];
  }

  constructor() {
    super();
    this._data = {
      status: 'offline',
      phase: null,
      iteration: null,
      provider: null,
      running_agents: 0,
      pending_tasks: null,
      uptime_seconds: 0,
      complexity: null,
      connected: false,
    };
    this._api = null;
    this._pollInterval = null;
    this._statusUpdateHandler = null;
    this._connectedHandler = null;
    this._disconnectedHandler = null;
    this._checklistSummary = null;
    this._appRunnerStatus = null;
    this._playwrightResults = null;
    this._gateStatus = null;
  }

  connectedCallback() {
    super.connectedCallback();
    this._setupApi();
    this._loadStatus();
    this._startPolling();
    // Connect WebSocket for real-time server push (supplements polling)
    this._api.connect().catch(() => {});
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this._stopPolling();
    // Abort any in-flight API requests to prevent memory leaks
    if (this._loadAbortController) {
      this._loadAbortController.abort();
      this._loadAbortController = null;
    }
    this._teardownApiListeners();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;

    if (name === 'api-url' && this._api) {
      // Re-fetch the correct per-URL client instead of mutating baseUrl on the
      // cached singleton (which would corrupt the shared instance for the old
      // URL and leak the new project's data to other components). Detach our
      // listeners from the old instance, adopt the new one, re-subscribe, and
      // open its WebSocket so live push follows the switched project.
      //
      // Capture the previous client before _setupApi reassigns this._api, then
      // disconnect it so its WebSocket + reconnect timer + global listeners are
      // released. Without this, every project switch adopts a different per-URL
      // singleton and leaves the old one's socket open with its reconnect timer
      // firing forever. Guard on identity: if the new URL resolves to the same
      // singleton (e.g. both fall back to window.location.origin), do not
      // disconnect the client we just adopted. Note: these clients are per-URL
      // singletons shared across components; disconnecting assumes the api-url
      // switch is whole-app (no refcounting exists), which holds for the
      // dashboard's single-project-at-a-time navigation.
      const oldApi = this._api;
      this._teardownApiListeners();
      this._setupApi();
      if (oldApi && oldApi !== this._api) {
        oldApi.disconnect();
      }
      this._api.connect().catch(() => {});
      this._loadStatus();
    }
    if (name === 'theme') {
      this._applyTheme();
    }
  }

  _teardownApiListeners() {
    if (this._api) {
      if (this._statusUpdateHandler) this._api.removeEventListener(ApiEvents.STATUS_UPDATE, this._statusUpdateHandler);
      if (this._connectedHandler) this._api.removeEventListener(ApiEvents.CONNECTED, this._connectedHandler);
      if (this._disconnectedHandler) this._api.removeEventListener(ApiEvents.DISCONNECTED, this._disconnectedHandler);
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });

    this._statusUpdateHandler = (e) => this._updateFromStatus(e.detail);
    this._connectedHandler = () => { this._data.connected = true; this.render(); };
    this._disconnectedHandler = () => { this._data.connected = false; this._data.status = 'offline'; this.render(); };

    this._api.addEventListener(ApiEvents.STATUS_UPDATE, this._statusUpdateHandler);
    this._api.addEventListener(ApiEvents.CONNECTED, this._connectedHandler);
    this._api.addEventListener(ApiEvents.DISCONNECTED, this._disconnectedHandler);
  }

  async _loadStatus() {
    // Abort any in-flight requests from a previous _loadStatus call
    if (this._loadAbortController) {
      this._loadAbortController.abort();
    }
    this._loadAbortController = new AbortController();
    const { signal } = this._loadAbortController;

    try {
      const [status, checklistSummary, appRunnerStatus, playwrightResults, gateStatus] = await Promise.allSettled([
        this._api.getStatus(),
        this._api.getChecklistSummary(),
        this._api.getAppRunnerStatus(),
        this._api.getPlaywrightResults(),
        this._api.getCouncilGate(),
      ]);
      // If aborted while awaiting, don't update state
      if (signal.aborted) return;

      if (status.status === 'fulfilled') {
        this._updateFromStatus(status.value);
      } else {
        this._data.connected = false;
        this._data.status = 'offline';
      }
      if (checklistSummary.status === 'fulfilled') {
        this._checklistSummary = checklistSummary.value?.summary || null;
      }
      if (appRunnerStatus.status === 'fulfilled') {
        this._appRunnerStatus = appRunnerStatus.value;
      }
      if (playwrightResults.status === 'fulfilled') {
        this._playwrightResults = playwrightResults.value;
      }
      if (gateStatus.status === 'fulfilled') {
        this._gateStatus = gateStatus.value;
      }
      this.render();
    } catch (error) {
      if (signal.aborted) return;
      this._data.connected = false;
      this._data.status = 'offline';
      this.render();
    }
  }

  _updateFromStatus(status) {
    if (!status) return;

    this._data = {
      ...this._data,
      connected: true,
      status: status.status || 'offline',
      phase: status.phase || null,
      iteration: status.iteration != null ? status.iteration : null,
      provider: status.provider || null,
      running_agents: status.running_agents || 0,
      pending_tasks: status.pending_tasks != null ? status.pending_tasks : null,
      uptime_seconds: status.uptime_seconds || 0,
      complexity: status.complexity || null,
    };
  }

  _startPolling() {
    // Central registry (core/loki-poll-registry.js) gates this poll to the
    // active + visible section in ONE place, so a hidden tab or background
    // section does not fetch. The inline body preserves the original
    // connected/offline error handling. connectedCallback already did the
    // first load, so immediate is disabled to avoid a duplicate fetch.
    this._poll = registerPoll({
      loadFn: async () => {
        try {
          await this._loadStatus();
        } catch (error) {
          this._data.connected = false;
          this._data.status = 'offline';
          this.render();
        }
      },
      intervalMs: 5000,
      element: this,
      immediate: false,
    });
  }

  _stopPolling() {
    if (this._poll) {
      this._poll.stop();
      this._poll = null;
    }
  }

  _formatUptime(seconds) {
    if (!seconds || seconds < 0) return '--';
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = Math.floor(seconds % 60);

    if (hours > 0) {
      return `${hours}h ${minutes}m`;
    }
    if (minutes > 0) {
      return `${minutes}m ${secs}s`;
    }
    return `${secs}s`;
  }

  _getStatusDotClass() {
    switch (this._data.status) {
      case 'running':
      case 'autonomous':
        return 'active';
      case 'paused':
        return 'paused';
      case 'stopped':
        return 'stopped';
      case 'error':
        return 'error';
      default:
        return 'offline';
    }
  }

  _escapeHtml(str) {
    if (!str) return '';
    return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  _renderAppRunnerCard() {
    const s = this._appRunnerStatus;
    if (!s || s.status === 'not_initialized') {
      const isRunning = this._data.status === 'running' || this._data.status === 'autonomous';
      const label = isRunning ? 'Starting...' : 'Not started';
      return `
        <div class="overview-card">
          <div class="card-label">App Status</div>
          <div class="card-value small-text">${label}</div>
        </div>
      `;
    }
    const statusColors = {
      running: 'var(--loki-green, #22c55e)',
      starting: 'var(--loki-yellow, #f59e0b)',
      crashed: 'var(--loki-red, #ef4444)',
      stopped: 'var(--loki-text-muted, #a1a1aa)',
    };
    const color = statusColors[s.status] || 'var(--loki-text-muted)';
    const dotClass = s.status === 'running' ? 'active' : s.status === 'crashed' ? 'error' : 'offline';
    const label = (s.status || 'unknown').toUpperCase();
    const port = s.port ? `:${s.port}` : '';
    // v7.6.2 B-16 fix: when App Runner has a URL, make the whole card clickable
    // to open the running app in a new tab. The backend `/api/app-runner/status`
    // returns `url` for compose / npm / python servers. Fall back to
    // http://localhost:<port> when only a port is present and status is running.
    let appUrl = s.url && typeof s.url === 'string' ? s.url : null;
    if (!appUrl && s.port && s.status === 'running') {
      appUrl = `http://localhost:${s.port}`;
    }
    const inner = `
      <div class="card-label">App Status${appUrl ? ' <span style="font-size:10px;color:var(--loki-text-muted);">(click to open)</span>' : ''}</div>
      <div class="card-value small-text">
        <span class="status-dot ${dotClass}"></span>
        ${label}${port}
      </div>
      ${s.method ? `<div style="font-size:10px;color:var(--loki-text-muted);margin-top:2px;">${this._escapeHtml(s.method)}</div>` : ''}
    `;
    if (appUrl) {
      return `
        <a class="overview-card overview-card-link" href="${this._escapeHtml(appUrl)}" target="_blank" rel="noopener noreferrer"
           style="text-decoration:none;color:inherit;display:block;cursor:pointer;"
           title="Open ${this._escapeHtml(appUrl)} in new tab">
          ${inner}
        </a>
      `;
    }
    return `
      <div class="overview-card">
        ${inner}
      </div>
    `;
  }

  _renderPlaywrightCard() {
    const r = this._playwrightResults;
    if (!r || r === 'null' || !r.verified_at) {
      const isRunning = this._data.status === 'running' || this._data.status === 'autonomous';
      const label = isRunning ? 'Pending' : 'Not run';
      return `
        <div class="overview-card">
          <div class="card-label">Verification</div>
          <div class="card-value small-text">${label}</div>
        </div>
      `;
    }
    const passed = r.passed === true;
    const color = passed ? 'var(--loki-green, #22c55e)' : 'var(--loki-red, #ef4444)';
    const label = passed ? 'PASSED' : 'FAILED';
    const dotClass = passed ? 'active' : 'error';
    const checks = r.checks || {};
    const failCount = Object.values(checks).filter(v => !v).length;
    return `
      <div class="overview-card">
        <div class="card-label">Verification</div>
        <div class="card-value small-text">
          <span class="status-dot ${dotClass}"></span>
          ${label}
        </div>
        ${!passed && failCount > 0 ? `<div style="font-size:10px;color:var(--loki-red,#ef4444);margin-top:2px;">${failCount} check(s) failed</div>` : ''}
      </div>
    `;
  }

  _renderChecklistCard() {
    const s = this._checklistSummary;
    if (!s || !s.total) {
      const isRunning = this._data.status === 'running' || this._data.status === 'autonomous';
      const label = isRunning ? 'Analyzing spec...' : 'No checklist';
      return `
        <div class="overview-card">
          <div class="card-label">Spec Progress</div>
          <div class="card-value small-text">${label}</div>
        </div>
      `;
    }
    const pct = Math.round((s.verified / s.total) * 100);
    const barColor = s.failing > 0 ? 'var(--loki-yellow, #f59e0b)' : 'var(--loki-green, #22c55e)';
    return `
      <div class="overview-card">
        <div class="card-label">Spec Progress</div>
        <div class="card-value small-text">${s.verified}/${s.total} (${pct}%)</div>
        <div class="mini-progress" style="margin-top:4px;height:4px;background:var(--loki-bg-secondary,#e4e4e7);border-radius:2px;overflow:hidden;">
          <div style="width:${pct}%;height:100%;background:${barColor};transition:width 0.3s;"></div>
        </div>
        ${s.failing ? `<div style="font-size:10px;color:var(--loki-red,#ef4444);margin-top:2px;">${s.failing} failing</div>` : ''}
      </div>
    `;
  }

  _renderCouncilGateCard() {
    const g = this._gateStatus;
    if (!g || !g.status) {
      const isRunning = this._data.status === 'running' || this._data.status === 'autonomous';
      const label = isRunning ? 'Pending review' : 'Not evaluated';
      return `
        <div class="overview-card">
          <div class="card-label">Council Gate</div>
          <div class="card-value small-text">
            <span class="status-dot ${isRunning ? 'paused' : 'offline'}"></span>
            ${label}
          </div>
        </div>
      `;
    }
    if (g.status === 'blocked') {
      const criticals = g.critical_failures || 0;
      return `
        <div class="overview-card">
          <div class="card-label">Council Gate</div>
          <div class="card-value small-text">
            <span class="status-dot error"></span>
            BLOCKED
          </div>
          ${criticals > 0 ? `<div style="font-size:10px;color:var(--loki-red,#ef4444);margin-top:2px;">${criticals} critical failure${criticals !== 1 ? 's' : ''}</div>` : ''}
        </div>
      `;
    }
    return `
      <div class="overview-card">
        <div class="card-label">Council Gate</div>
        <div class="card-value small-text">
          <span class="status-dot active"></span>
          PASSED
        </div>
      </div>
    `;
  }

  render() {
    const statusDotClass = this._getStatusDotClass();
    const statusLabel = this._escapeHtml((this._data.status || 'OFFLINE').toUpperCase());
    const phase = this._escapeHtml(this._data.phase || '--');
    const iteration = this._escapeHtml(this._data.iteration != null ? String(this._data.iteration) : '0');
    const provider = this._escapeHtml((this._data.provider || 'CLAUDE').toUpperCase());
    const isSessionActive = this._data.status === 'running' || this._data.status === 'autonomous';
    const agentCount = this._data.running_agents || 0;
    const agents = isSessionActive && agentCount === 0 ? 'Sequential' : this._escapeHtml(String(agentCount));
    const tasks = this._escapeHtml(this._data.pending_tasks != null ? `${this._data.pending_tasks} pending` : (isSessionActive ? 'Inline' : '--'));
    const uptime = this._escapeHtml(this._formatUptime(this._data.uptime_seconds));
    const complexity = this._escapeHtml((this._data.complexity || 'STANDARD').toUpperCase());

    this.shadowRoot.innerHTML = `
      <style>
        ${this.getBaseStyles()}

        :host {
          display: block;
        }

        .overview-container {
          background: var(--loki-bg-card);
          border: 1px solid var(--loki-border);
          border-radius: 5px;
          padding: 16px;
          transition: all var(--loki-transition);
        }

        .overview-header {
          display: flex;
          align-items: center;
          gap: 8px;
          margin-bottom: 14px;
        }

        .overview-header svg {
          width: 16px;
          height: 16px;
          color: var(--loki-text-muted);
          flex-shrink: 0;
        }

        .overview-title {
          font-size: 12px;
          font-weight: 600;
          text-transform: uppercase;
          letter-spacing: 0.05em;
          color: var(--loki-text-muted);
        }

        .overview-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
          gap: 10px;
        }

        .overview-card {
          background: var(--loki-bg-secondary);
          border: 1px solid var(--loki-border);
          border-radius: 5px;
          padding: 12px 14px;
          transition: background var(--loki-transition);
        }

        .overview-card:hover {
          background: var(--loki-bg-hover);
        }

        .card-label {
          font-size: 10px;
          font-weight: 600;
          text-transform: uppercase;
          letter-spacing: 0.05em;
          color: var(--loki-text-muted);
          margin-bottom: 6px;
        }

        .card-value {
          font-size: 18px;
          font-weight: 600;
          font-family: 'JetBrains Mono', monospace;
          color: var(--loki-accent);
          display: flex;
          align-items: center;
          gap: 8px;
          line-height: 1.2;
          min-width: 0;
          overflow: hidden;
          text-overflow: ellipsis;
          white-space: nowrap;
        }

        .card-value.small-text {
          font-size: 14px;
        }

        .status-dot {
          width: 12px;
          height: 6px;
          border-radius: 2px;
          flex-shrink: 0;
        }

        .status-dot.active {
          background: var(--loki-green);
          animation: pulse 2s infinite;
        }

        .status-dot.paused {
          background: var(--loki-yellow);
        }

        .status-dot.stopped {
          background: var(--loki-red);
        }

        .status-dot.error {
          background: var(--loki-red);
        }

        .status-dot.offline {
          background: var(--loki-text-muted);
        }

        @keyframes pulse {
          0%, 100% { opacity: 1; }
          50% { opacity: 0.5; }
        }
      </style>

      <div class="overview-container">
        <div class="overview-header">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
            <circle cx="12" cy="12" r="10"></circle>
            <polyline points="12 6 12 12 16 14"></polyline>
          </svg>
          <span class="overview-title">Overview</span>
        </div>

        <div class="overview-grid">
          <div class="overview-card">
            <div class="card-label">Session</div>
            <div class="card-value">
              <span class="status-dot ${statusDotClass}"></span>
              ${statusLabel}
            </div>
          </div>

          <div class="overview-card">
            <div class="card-label">Phase</div>
            <div class="card-value small-text">${phase}</div>
          </div>

          <div class="overview-card">
            <div class="card-label">Iteration</div>
            <div class="card-value">${iteration}</div>
          </div>

          <div class="overview-card">
            <div class="card-label">Provider</div>
            <div class="card-value small-text">${provider}</div>
          </div>

          <div class="overview-card">
            <div class="card-label">Agents running</div>
            <div class="card-value">${agents}</div>
          </div>

          <div class="overview-card">
            <div class="card-label">Tasks</div>
            <div class="card-value small-text">${tasks}</div>
          </div>

          ${this._renderChecklistCard()}

          ${this._renderAppRunnerCard()}

          ${this._renderPlaywrightCard()}

          ${this._renderCouncilGateCard()}

          <div class="overview-card">
            <div class="card-label">Uptime</div>
            <div class="card-value small-text">${uptime}</div>
          </div>

          <div class="overview-card">
            <div class="card-label">Complexity</div>
            <div class="card-value small-text">${complexity}</div>
          </div>
        </div>
      </div>
    `;
  }
}

// Register the component
if (!customElements.get('loki-overview')) {
  customElements.define('loki-overview', LokiOverview);
}

export default LokiOverview;

/**
 * @fileoverview Build Pipeline Visualizer - horizontal pipeline showing
 * build stages with status indicators, animated flow dots for active
 * connections, and pulsing animation for the current stage.
 *
 * Stages: Planning -> Scaffolding -> Implementation -> Testing -> Review -> Deploy
 *
 * @example
 * <loki-pipeline-view api-url="http://localhost:57374" theme="dark"></loki-pipeline-view>
 */

import { LokiElement } from '../core/loki-theme.js';
import { getApiClient } from '../core/loki-api-client.js';
import { registerPoll } from '../core/loki-poll-registry.js';

/** @type {Array<{id: string, label: string, icon: string}>} */
const PIPELINE_STAGES = [
  { id: 'planning',       label: 'Planning',       icon: 'P' },
  { id: 'scaffolding',    label: 'Scaffolding',    icon: 'S' },
  { id: 'implementation', label: 'Implementation', icon: 'I' },
  { id: 'testing',        label: 'Testing',        icon: 'T' },
  { id: 'review',         label: 'Review',         icon: 'R' },
  { id: 'deploy',         label: 'Deploy',         icon: 'D' },
];

const STAGE_STATUS = {
  waiting:  { color: 'var(--loki-text-muted, #939084)',  bgColor: 'var(--loki-bg-tertiary, #ECEAE3)', label: 'Waiting' },
  active:   { color: 'var(--loki-accent, #553DE9)',      bgColor: 'var(--loki-accent-muted, rgba(85, 61, 233, 0.10))', label: 'Active' },
  complete: { color: 'var(--loki-green, #1FC5A8)',       bgColor: 'var(--loki-green-muted, rgba(31, 197, 168, 0.12))', label: 'Complete' },
  failed:   { color: 'var(--loki-red, #C45B5B)',         bgColor: 'var(--loki-red-muted, rgba(196, 91, 91, 0.12))', label: 'Failed' },
};

/**
 * @class LokiPipelineView
 * @extends LokiElement
 * @property {string} api-url - API base URL (default: window.location.origin)
 * @property {string} theme - Theme name (default: auto-detect)
 */
export class LokiPipelineView extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'theme'];
  }

  constructor() {
    super();
    this._stages = [];
    this._api = null;
    this._pollInterval = null;
  }

  connectedCallback() {
    super.connectedCallback();
    this._setupApi();
    this._loadData();
    this._startPolling();
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this._stopPolling();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    if (name === 'api-url' && this._api) {
      this._api = getApiClient({ baseUrl: newValue });
      this._loadData();
    }
    if (name === 'theme') {
      this._applyTheme();
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });
  }

  _startPolling() {
    // Central registry (core/loki-poll-registry.js) gates this poll to the
    // active + visible section in ONE place, so a hidden tab or background
    // section does not fetch. connectedCallback already did the first load,
    // so immediate is disabled to avoid a duplicate fetch.
    this._poll = registerPoll({
      loadFn: () => this._loadData(),
      intervalMs: 5000,
      element: this,
      immediate: false,
    });
  }

  _stopPolling() {
    if (this._poll) {
      this._poll.stop();
      this._poll = null;
    }
  }

  async _loadData() {
    // Capture the api instance so a mid-flight api-url switch can be detected.
    const api = this._api;
    try {
      const data = await api._get('/api/v2/pipeline/status');
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      this._stages = data.stages || [];
    } catch {
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      // Use demo data if API unavailable
      if (this._stages.length === 0) {
        this._stages = this._getDemoData();
      }
    }
    this.render();
  }

  _getDemoData() {
    return [
      { id: 'planning',       status: 'complete', errors: 0, duration_ms: 12500 },
      { id: 'scaffolding',    status: 'complete', errors: 0, duration_ms: 8300 },
      { id: 'implementation', status: 'active',   errors: 0, duration_ms: 45000 },
      { id: 'testing',        status: 'waiting',  errors: 0, duration_ms: null },
      { id: 'review',         status: 'waiting',  errors: 0, duration_ms: null },
      { id: 'deploy',         status: 'waiting',  errors: 0, duration_ms: null },
    ];
  }

  _getStageData(stageId) {
    return this._stages.find(s => s.id === stageId) || { id: stageId, status: 'waiting', errors: 0 };
  }

  _formatDuration(ms) {
    if (ms == null || ms < 0) return '';
    if (ms < 1000) return ms + 'ms';
    const sec = Math.floor(ms / 1000);
    if (sec < 60) return sec + 's';
    const min = Math.floor(sec / 60);
    const remainSec = sec % 60;
    return min + 'm ' + remainSec + 's';
  }

  _getStyles() {
    return `
      :host {
        display: block;
      }

      .pipeline-container {
        font-family: var(--loki-font-family, 'Inter', -apple-system, sans-serif);
        color: var(--loki-text-primary, #201515);
      }

      .header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        margin-bottom: 16px;
      }

      .title {
        font-size: 16px;
        font-weight: 600;
        margin: 0;
      }

      .pipeline-track {
        display: flex;
        align-items: center;
        gap: 0;
        padding: 20px 12px;
        background: var(--loki-bg-card, #ffffff);
        border: 1px solid var(--loki-border, #ECEAE3);
        border-radius: 5px;
        overflow-x: auto;
      }

      .stage-node {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 8px;
        min-width: 90px;
        flex-shrink: 0;
      }

      .stage-circle {
        width: 48px;
        height: 48px;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 16px;
        font-weight: 700;
        transition: all 0.3s;
        position: relative;
      }

      .stage-circle.active {
        animation: stagePulse 2s ease-in-out infinite;
      }

      @keyframes stagePulse {
        0%, 100% { box-shadow: 0 0 0 0 rgba(85, 61, 233, 0.3); }
        50% { box-shadow: 0 0 0 10px rgba(85, 61, 233, 0); }
      }

      .stage-check {
        font-size: 18px;
        line-height: 1;
      }

      .stage-label {
        font-size: 11px;
        font-weight: 600;
        color: var(--loki-text-secondary, #36342E);
        text-align: center;
        max-width: 90px;
      }

      .stage-duration {
        font-size: 10px;
        font-family: 'JetBrains Mono', monospace;
        color: var(--loki-text-muted, #939084);
      }

      .stage-error-count {
        font-size: 10px;
        font-weight: 600;
        color: var(--loki-red, #C45B5B);
        background: var(--loki-red-muted, rgba(196, 91, 91, 0.12));
        padding: 1px 6px;
        border-radius: 4px;
      }

      .connector {
        flex: 1;
        height: 3px;
        min-width: 24px;
        position: relative;
        overflow: hidden;
        margin: 0 -2px;
        align-self: center;
        margin-bottom: 36px;
      }

      .connector-line {
        position: absolute;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        border-radius: 2px;
      }

      .connector-line.completed {
        background: var(--loki-green, #1FC5A8);
      }

      .connector-line.pending {
        background: var(--loki-border, #ECEAE3);
      }

      .connector-line.active {
        background: var(--loki-border, #ECEAE3);
      }

      .flow-dot {
        position: absolute;
        top: -1px;
        width: 5px;
        height: 5px;
        border-radius: 50%;
        background: var(--loki-accent, #553DE9);
        animation: flowDot 1.5s linear infinite;
      }

      @keyframes flowDot {
        0% { left: 0; opacity: 0; }
        10% { opacity: 1; }
        90% { opacity: 1; }
        100% { left: 100%; opacity: 0; }
      }

      .status-legend {
        display: flex;
        gap: 16px;
        margin-top: 14px;
        flex-wrap: wrap;
      }

      .legend-item {
        display: flex;
        align-items: center;
        gap: 6px;
        font-size: 11px;
        color: var(--loki-text-muted, #939084);
      }

      .legend-dot {
        width: 8px;
        height: 8px;
        border-radius: 50%;
        flex-shrink: 0;
      }
    `;
  }

  render() {
    const s = this.shadowRoot;
    if (!s) return;

    const stageNodes = PIPELINE_STAGES.map((stage, idx) => {
      const data = this._getStageData(stage.id);
      const statusCfg = STAGE_STATUS[data.status] || STAGE_STATUS.waiting;
      const isComplete = data.status === 'complete';
      const isActive = data.status === 'active';
      const isFailed = data.status === 'failed';

      const circleContent = isComplete
        ? '<span class="stage-check">&#10003;</span>'
        : (isFailed ? '<span class="stage-check">&#10007;</span>' : stage.icon);

      const stageHtml = `
        <div class="stage-node">
          <div class="stage-circle ${isActive ? 'active' : ''}"
               style="background: ${statusCfg.bgColor}; color: ${statusCfg.color}; border: 2px solid ${statusCfg.color};">
            ${circleContent}
          </div>
          <span class="stage-label">${stage.label}</span>
          ${data.duration_ms ? `<span class="stage-duration">${this._formatDuration(data.duration_ms)}</span>` : ''}
          ${data.errors > 0 ? `<span class="stage-error-count">${data.errors} error${data.errors > 1 ? 's' : ''}</span>` : ''}
        </div>
      `;

      // Add connector after each stage except the last
      if (idx < PIPELINE_STAGES.length - 1) {
        const nextData = this._getStageData(PIPELINE_STAGES[idx + 1].id);
        const isConnectorCompleted = isComplete;
        const isConnectorActive = isActive || (isComplete && (nextData.status === 'active' || nextData.status === 'waiting'));

        const connectorClass = isConnectorCompleted ? 'completed' : (isActive ? 'active' : 'pending');
        const flowDot = isActive ? '<div class="flow-dot"></div>' : '';

        return stageHtml + `
          <div class="connector">
            <div class="connector-line ${connectorClass}"></div>
            ${flowDot}
          </div>
        `;
      }

      return stageHtml;
    }).join('');

    const legendItems = Object.entries(STAGE_STATUS).map(([key, cfg]) => {
      return `<div class="legend-item">
        <div class="legend-dot" style="background: ${cfg.color};"></div>
        <span>${cfg.label}</span>
      </div>`;
    }).join('');

    s.innerHTML = `
      <style>${this.getBaseStyles()}${this._getStyles()}</style>
      <div class="pipeline-container">
        <div class="header">
          <h3 class="title">Build Pipeline</h3>
        </div>
        <div class="pipeline-track">
          ${stageNodes}
        </div>
        <div class="status-legend">
          ${legendItems}
        </div>
      </div>
    `;
  }
}

