import { LokiElement } from '../core/loki-theme.js';
import { getApiClient } from '../core/loki-api-client.js';
import { registerPoll } from '../core/loki-poll-registry.js';

/** @type {Object<string, {initial: string, color: string, bgColor: string}>} */
const PROVIDER_ICONS = {
  claude:  { initial: 'C', color: '#553DE9', bgColor: 'rgba(85, 61, 233, 0.12)' },
  codex:   { initial: 'X', color: '#1FC5A8', bgColor: 'rgba(31, 197, 168, 0.12)' },
  cline:   { initial: 'L', color: '#D4A03C', bgColor: 'rgba(212, 160, 60, 0.12)' },
  aider:   { initial: 'A', color: '#C45B5B', bgColor: 'rgba(196, 91, 91, 0.12)' },
};

const STATUS_COLORS = {
  healthy:  'var(--loki-green, #1FC5A8)',
  degraded: 'var(--loki-yellow, #D4A03C)',
  down:     'var(--loki-red, #C45B5B)',
  unknown:  'var(--loki-text-muted, #939084)',
};

/**
 * @class LokiProviderHealth
 * @extends LokiElement
 * @property {string} api-url - API base URL (default: window.location.origin)
 * @property {string} theme - Theme name (default: auto-detect)
 */
export class LokiProviderHealth extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'theme'];
  }

  constructor() {
    super();
    this._providers = [];
    this._expandedProvider = null;
    this._api = null;
    this._pollInterval = null;
  }

  connectedCallback() {
    super.connectedCallback();
    this._setupApi();
    this._loadData();
    this._startPolling();
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this._stopPolling();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    if (name === 'api-url' && this._api) {
      this._api = getApiClient({ baseUrl: newValue });
      this._loadData();
    }
    if (name === 'theme') {
      this._applyTheme();
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });
  }

  _startPolling() {
    // Central registry (core/loki-poll-registry.js) gates this poll to the
    // active + visible section in ONE place, so a hidden tab or background
    // section does not fetch. connectedCallback already did the first load,
    // so immediate is disabled to avoid a duplicate fetch.
    this._poll = registerPoll({
      loadFn: () => this._loadData(),
      intervalMs: 10000,
      element: this,
      immediate: false,
    });
  }

  _stopPolling() {
    if (this._poll) {
      this._poll.stop();
      this._poll = null;
    }
  }

  async _loadData() {
    // Drop a stale response if the api-url switched mid-flight.
    const api = this._api;
    try {
      const data = await api._get('/api/v2/providers/health');
      if (api !== this._api) return;
      this._providers = data.providers || [];
    } catch {
      if (api !== this._api) return;
      // Use demo data if API unavailable
      if (this._providers.length === 0) {
        this._providers = this._getDemoData();
      }
    }
    this.render();
  }

  _getDemoData() {
    return [
      {
        name: 'claude', status: 'healthy', latency_ms: 245,
        tokens_used: 125400, model: 'claude-opus-4-7',
        api_version: 'v1', rate_limit: { remaining: 45, limit: 50 },
        cost_usd: 3.42,
      },
      {
        name: 'codex', status: 'degraded', latency_ms: 890,
        tokens_used: 45200, model: 'gpt-5.3-codex',
        api_version: 'v1', rate_limit: { remaining: 12, limit: 60 },
        cost_usd: 0.87,
      },
      {
        name: 'cline', status: 'healthy', latency_ms: 320,
        tokens_used: 78600, model: 'cline-default',
        api_version: 'v1', rate_limit: { remaining: 55, limit: 60 },
        cost_usd: 1.15,
      },
    ];
  }

  _formatTokens(n) {
    if (n == null) return '--';
    if (n >= 1000000) return (n / 1000000).toFixed(1) + 'M';
    if (n >= 1000) return (n / 1000).toFixed(1) + 'K';
    return String(n);
  }

  _formatLatency(ms) {
    if (ms == null) return '--';
    if (ms < 1000) return ms + 'ms';
    return (ms / 1000).toFixed(1) + 's';
  }

  _formatCost(usd) {
    if (usd == null) return '--';
    return '$' + usd.toFixed(2);
  }

  _escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  _toggleExpand(providerName) {
    this._expandedProvider = this._expandedProvider === providerName ? null : providerName;
    this.render();
  }

  _bindEvents() {
    const root = this.shadowRoot;
    root.querySelectorAll('.provider-card').forEach(card => {
      card.addEventListener('click', () => {
        this._toggleExpand(card.dataset.provider);
      });
    });
  }

  _getStyles() {
    return `
      :host {
        display: block;
      }

      .health-container {
        font-family: var(--loki-font-family, 'Inter', -apple-system, sans-serif);
        color: var(--loki-text-primary, #201515);
      }

      .header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        margin-bottom: 16px;
      }

      .title {
        font-size: 16px;
        font-weight: 600;
        margin: 0;
