                <div class="detail-row">
                  <span class="detail-label">Rate Limit</span>
                  <span class="detail-value">${p.rate_limit ? p.rate_limit.remaining + '/' + p.rate_limit.limit : '--'}</span>
                  ${p.rate_limit ? `
