  _renderPlaceholderTimeline() {
    const segments = PHASE_ORDER.map(phase => {
      const cfg = PHASE_CONFIG[phase];
      return `<div class="phase-segment-interactive"
                   data-phase="${phase}"
                   style="width: 25%; background: ${cfg.color}; opacity: 0.3;"
                   title="${cfg.label}: awaiting data">
                ${cfg.label}
              </div>`;
    }).join('');

    const legendItems = PHASE_ORDER.map(phase => {
      const cfg = PHASE_CONFIG[phase];
      return `<div class="legend-item-interactive" data-phase="${phase}">
                <span class="legend-dot" style="background: ${cfg.color}; opacity: 0.4;"></span>
                <span class="legend-label">${cfg.label}</span>
                <span class="legend-duration">--</span>
              </div>`;
    }).join('');

    return `
      <div class="empty-state" style="padding: 0; text-align: left;">
        <div class="timeline-bar" style="opacity: 0.5;">${segments}</div>
        <div class="legend">${legendItems}</div>
        <div style="text-align: center; margin-top: 12px; font-size: 12px; color: var(--loki-text-muted, #939084);">
          Each step fills in as your build progresses
        </div>
      </div>
    `;
  }

  _renderPhaseDetail(phase) {
    const cfg = PHASE_CONFIG[phase];
    if (!cfg) return '';

    const phases = this._timeline?.phases || [];
    const phaseData = phases.find(p => p.phase === phase);

    return `
      <div class="phase-detail">
        <div class="detail-header">
          <div class="detail-title">
            <div class="detail-title-dot" style="background: ${cfg.color};"></div>
            ${cfg.label} Phase
          </div>
          <button class="close-detail" title="Close">&#10005;</button>
        </div>
        <div class="detail-description">${cfg.description}</div>
        <div class="detail-metrics">
          <div class="detail-metric">
            <span class="detail-metric-label">Time Spent</span>
            <span class="detail-metric-value">${formatDuration(phaseData?.duration_ms)}</span>
          </div>
          <div class="detail-metric">
            <span class="detail-metric-label">Tokens Used</span>
            <span class="detail-metric-value">${formatTokens(phaseData?.tokens_used)}</span>
          </div>
          <div class="detail-metric">
            <span class="detail-metric-label">Quality</span>
            <span class="detail-metric-value">${phaseData?.quality_score != null ? phaseData.quality_score.toFixed(1) : '--'}</span>
          </div>
          <div class="detail-metric">
            <span class="detail-metric-label">Actions</span>
            <span class="detail-metric-value">${phaseData?.action_count != null ? phaseData.action_count : '--'}</span>
          </div>
        </div>
      </div>
    `;
  }

  _renderCycleHistory() {
    if (this._cycleHistory.length === 0) return '';

    const cycles = this._cycleHistory.slice(-8); // Show last 8 cycles
    const cycleHtml = cycles.map((cycle, idx) => {
      const dots = PHASE_ORDER.map(phase => {
        const phaseData = cycle.phases?.find(p => p.phase === phase);
        const cfg = PHASE_CONFIG[phase];
        const status = phaseData?.status || 'pending';
        const opacity = status === 'complete' ? '0.8' : (status === 'active' ? '1' : '0.3');
        return `<div class="history-dot" style="background: ${cfg.color}; opacity: ${opacity};"
                  title="Cycle ${idx + 1}: ${cfg.label} - ${formatDuration(phaseData?.duration_ms)}"></div>`;
      }).join('');

      return `<div class="history-cycle">${dots}</div>`;
    }).join('<div class="history-separator"></div>');

    return `
      <div class="cycle-history">
        <div class="history-label">Past Cycles (${this._cycleHistory.length} total)</div>
        <div class="history-cycles">${cycleHtml}</div>
      </div>
    `;
  }

  _escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  render() {
    const s = this.shadowRoot;
    if (!s) return;

    const runId = this.runId;
    const timeline = this._timeline;
    const phases = timeline?.phases || [];
    const currentPhase = timeline?.current_phase || null;
    const phaseWidths = computePhaseWidths(phases);

    let content;
    if (this._loading && !timeline) {
      content = '<div class="loading">Loading timeline...</div>';
    } else if (runId == null) {
      content = this._renderPlaceholderTimeline();
    } else if (phases.length === 0) {
      content = this._renderPlaceholderTimeline();
    } else {
      const barSegments = phaseWidths.map(pw => {
        const cfg = PHASE_CONFIG[pw.phase] || { color: 'var(--loki-text-muted)', label: pw.phase };
        const isCurrent = currentPhase === pw.phase;
        const isSelected = this._selectedPhase === pw.phase;
        return `<div class="phase-segment-interactive ${isCurrent ? 'current' : ''} ${isSelected ? 'selected' : ''}"
                     data-phase="${pw.phase}"
                     style="width: ${Math.max(pw.pct, 2)}%; background: ${cfg.color};"
                     title="${cfg.label}: ${formatDuration(pw.duration)}">
                  ${pw.pct > 12 ? cfg.label : ''}
                </div>`;
      }).join('');

      const legendItems = phases.map(p => {
        const cfg = PHASE_CONFIG[p.phase] || { color: 'var(--loki-text-muted)', label: p.phase };
        const isCurrent = currentPhase === p.phase;
        const isSelected = this._selectedPhase === p.phase;
        return `<div class="legend-item-interactive ${isSelected ? 'selected' : ''}" data-phase="${p.phase}">
                  <span class="legend-dot" style="background: ${cfg.color}"></span>
                  <span class="legend-label">${cfg.label}</span>
                  <span class="legend-duration">${formatDuration(p.duration_ms)}</span>
                  ${isCurrent ? '<span class="phase-current-tag">ACTIVE</span>' : ''}
                </div>`;
      }).join('');

      const detailPanel = this._selectedPhase ? this._renderPhaseDetail(this._selectedPhase) : '';
      const historyPanel = this._renderCycleHistory();

      content = `
        <div class="timeline-bar">${barSegments}</div>
        <div class="legend">${legendItems}</div>
        ${detailPanel}
        ${historyPanel}
      `;
    }

    s.innerHTML = `
      <style>${this.getBaseStyles()}${this._getStyles()}</style>
      <div class="timeline-container">
        <div class="header">
          <h3 class="title">RARV Timeline</h3>
          ${runId != null ? `<span class="run-label">Run #${runId}</span>` : ''}
        </div>
        ${content}
        ${this._error ? `<div class="error-banner">${this._escapeHtml(this._error)}</div>` : ''}
      </div>
    `;

    this._bindEvents();
  }
}

if (!customElements.get('loki-rarv-timeline')) {
  customElements.define('loki-rarv-timeline', LokiRarvTimeline);
}

export default LokiRarvTimeline;

/**
 * @fileoverview Run Manager - displays a table of runs with cancel and replay
 * controls. Shows run ID, project, status, trigger, start time, and duration.
 * Running runs can be cancelled, completed/failed runs can be replayed.
 *
 * @example
 * <loki-run-manager api-url="http://localhost:57374" project-id="5" theme="dark"></loki-run-manager>
 */

import { LokiElement } from '../core/loki-theme.js';
import { getApiClient } from '../core/loki-api-client.js';
import { registerPoll } from '../core/loki-poll-registry.js';

/** @type {Object<string, {color: string, bg: string, label: string}>} */
const RUN_STATUS_CONFIG = {
  running:   { color: 'var(--loki-green, #22c55e)',      bg: 'var(--loki-green-muted, rgba(34, 197, 94, 0.15))',  label: 'Running' },
  completed: { color: 'var(--loki-blue, #3b82f6)',       bg: 'var(--loki-blue-muted, rgba(59, 130, 246, 0.15))',  label: 'Completed' },
  failed:    { color: 'var(--loki-red, #ef4444)',        bg: 'var(--loki-red-muted, rgba(239, 68, 68, 0.15))',    label: 'Failed' },
  cancelled: { color: 'var(--loki-yellow, #eab308)',     bg: 'var(--loki-yellow-muted, rgba(234, 179, 8, 0.15))', label: 'Cancelled' },
  pending:   { color: 'var(--loki-text-muted, #939084)', bg: 'var(--loki-bg-tertiary, #ECEAE3)',                   label: 'Pending' },
  queued:    { color: 'var(--loki-text-muted, #939084)', bg: 'var(--loki-bg-tertiary, #ECEAE3)',                   label: 'Queued' },
};

/**
 * Format a duration from milliseconds or compute from start/end timestamps.
 * @param {number|null} durationMs - Duration in ms, or null
 * @param {string|null} startedAt - ISO start timestamp
 * @param {string|null} endedAt - ISO end timestamp
 * @returns {string}
 */
export function formatRunDuration(durationMs, startedAt, endedAt) {
  let ms = durationMs;
  if (ms == null && startedAt) {
    const start = new Date(startedAt).getTime();
    const end = endedAt ? new Date(endedAt).getTime() : Date.now();
    ms = end - start;
  }
  if (ms == null || ms < 0) return '--';
  if (ms < 1000) return `${ms}ms`;
  const sec = Math.floor(ms / 1000);
  if (sec < 60) return `${sec}s`;
  const min = Math.floor(sec / 60);
  const remainSec = sec % 60;
  if (min < 60) return `${min}m ${remainSec}s`;
  const hr = Math.floor(min / 60);
  const remainMin = min % 60;
  return `${hr}h ${remainMin}m`;
}

/**
 * Format a timestamp for display in the run table.
 * @param {string|null} timestamp - ISO timestamp
 * @returns {string}
 */
export function formatRunTime(timestamp) {
  if (!timestamp) return '--';
  try {
    const d = new Date(timestamp);
    return d.toLocaleString([], {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  } catch {
    return String(timestamp);
  }
}

/**
 * @class LokiRunManager
 * @extends LokiElement
 * @property {string} api-url - API base URL
 * @property {number} project-id - Optional project ID filter
 * @property {string} theme - 'light' or 'dark'
 */
export class LokiRunManager extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'project-id', 'theme'];
  }

  constructor() {
    super();
    this._loading = false;
    this._error = null;
    this._api = null;
    this._runs = [];
    this._pollInterval = null;
    this._lastDataHash = null;
  }

  get projectId() {
    const val = this.getAttribute('project-id');
    return val ? parseInt(val, 10) : null;
  }

  set projectId(val) {
    if (val != null) {
      this.setAttribute('project-id', String(val));
    } else {
      this.removeAttribute('project-id');
    }
  }

  connectedCallback() {
    super.connectedCallback();
    this._setupApi();
    this._loadData();
    this._startPolling();
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this._stopPolling();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    if (name === 'api-url' && this._api) {
      this._api = getApiClient({ baseUrl: newValue });
      this._loadData();
    }
    if (name === 'project-id') {
      this._loadData();
    }
    if (name === 'theme') {
      this._applyTheme();
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });
  }

  _startPolling() {
    // Central registry (core/loki-poll-registry.js) gates this poll to the
    // active + visible section in ONE place, replacing the per-component
    // visibilitychange handler. connectedCallback already did the first load,
    // so immediate is disabled to avoid a duplicate fetch.
    this._poll = registerPoll({
      loadFn: () => this._loadData(),
      intervalMs: 5000,
      element: this,
      immediate: false,
    });
  }

  _stopPolling() {
    if (this._poll) {
      this._poll.stop();
      this._poll = null;
    }
  }

  async _loadData() {
    const api = this._api;
    try {
      const projectId = this.projectId;
      const query = projectId != null ? `?project_id=${projectId}` : '';
      const data = await api._get(`/api/v2/runs${query}`);
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      const runs = data?.runs || data || [];
      const dataHash = JSON.stringify(runs);
      if (dataHash === this._lastDataHash) return;
      this._lastDataHash = dataHash;
      this._runs = Array.isArray(runs) ? runs : [];
      this._error = null;
    } catch (err) {
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      if (!this._error) {
        this._error = `Failed to load runs: ${err.message}`;
      }
    } finally {
      this._loading = false;
    }

    this.render();
  }

  async _cancelRun(runId) {
    try {
      await this._api._post(`/api/v2/runs/${runId}/cancel`);
      await this._loadData();
    } catch (err) {
      this._error = `Cancel failed: ${err.message}`;
      this.render();
    }
  }

  async _replayRun(runId) {
    try {
      await this._api._post(`/api/v2/runs/${runId}/replay`);
      await this._loadData();
    } catch (err) {
      this._error = `Replay failed: ${err.message}`;
      this.render();
    }
  }

  _escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  _getStyles() {
    return `
      :host {
        display: block;
      }

      .run-manager {
        padding: 16px;
        font-family: var(--loki-font-family, 'Inter', -apple-system, sans-serif);
        color: var(--loki-text-primary, #201515);
      }

      .header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        margin-bottom: 16px;
      }

      .title {
        font-size: 18px;
        font-weight: 600;
        margin: 0;
      }

      .btn {
        padding: 4px 10px;
        border: 1px solid var(--loki-border, #ECEAE3);
        border-radius: 5px;
        background: var(--loki-bg-tertiary, #ECEAE3);
        color: var(--loki-text-primary, #201515);
        cursor: pointer;
        font-size: 11px;
        font-weight: 500;
        transition: all 0.15s ease;
      }

      .btn:hover {
        background: var(--loki-bg-hover, #1f1f23);
        border-color: var(--loki-border-light, #C5C0B1);
      }

      .btn-cancel {
        border-color: var(--loki-red, #ef4444);
        color: var(--loki-red, #ef4444);
      }

      .btn-cancel:hover {
        background: var(--loki-red-muted, rgba(239, 68, 68, 0.15));
      }

      .btn-replay {
        border-color: var(--loki-accent, #553DE9);
        color: var(--loki-accent, #553DE9);
      }

      .btn-replay:hover {
        background: var(--loki-accent-muted, rgba(139, 92, 246, 0.15));
      }

      .btn-refresh {
        padding: 6px 14px;
        font-size: 12px;
      }

      .runs-table-wrapper {
        background: var(--loki-bg-card, #ffffff);
        border: 1px solid var(--loki-border, #ECEAE3);
        border-radius: 5px;
        overflow: auto;
      }

      table {
        width: 100%;
        border-collapse: collapse;
        font-size: 12px;
      }

      th {
        text-align: left;
        padding: 10px 14px;
        font-size: 11px;
        font-weight: 600;
        text-transform: uppercase;
        letter-spacing: 0.05em;
        color: var(--loki-text-muted, #939084);
        border-bottom: 1px solid var(--loki-border, #ECEAE3);
        background: var(--loki-bg-tertiary, #ECEAE3);
        white-space: nowrap;
      }

      td {
        padding: 8px 14px;
        border-bottom: 1px solid var(--loki-border, #ECEAE3);
        white-space: nowrap;
      }

      tr:last-child td {
        border-bottom: none;
      }

      tr:hover td {
        background: var(--loki-bg-hover, #1f1f23);
      }

      .run-id {
        font-family: 'JetBrains Mono', monospace;
        font-weight: 600;
        color: var(--loki-accent, #553DE9);
        font-size: 12px;
      }

      .status-badge {
        display: inline-block;
        font-size: 10px;
        font-weight: 600;
        padding: 2px 8px;
        border-radius: 5px;
        text-transform: uppercase;
      }

      .actions-cell {
        display: flex;
        gap: 6px;
      }

      .empty-state {
        text-align: center;
        padding: 40px;
        color: var(--loki-text-muted, #939084);
        font-size: 13px;
      }

      .error-banner {
        margin-top: 12px;
        padding: 8px 12px;
        background: var(--loki-red-muted, rgba(239, 68, 68, 0.15));
        color: var(--loki-red, #ef4444);
        border-radius: 4px;
        font-size: 12px;
      }

      .loading {
        text-align: center;
        padding: 24px;
        color: var(--loki-text-muted, #939084);
        font-size: 13px;
      }

      .run-count {
        font-size: 12px;
        color: var(--loki-text-muted, #939084);
        margin-bottom: 8px;
      }
    `;
  }

  render() {
    const s = this.shadowRoot;
    if (!s) return;

    const runs = this._runs;

    let content;
    if (this._loading && runs.length === 0) {
      content = '<div class="loading">Loading runs...</div>';
    } else if (runs.length === 0) {
      content = '<div class="empty-state">No runs found.</div>';
    } else {
      const rows = runs.map(run => {
        const status = (run.status || 'pending').toLowerCase();
        const cfg = RUN_STATUS_CONFIG[status] || RUN_STATUS_CONFIG.pending;
        const isRunning = status === 'running';
        const canReplay = status === 'completed' || status === 'failed' || status === 'cancelled';
        const duration = formatRunDuration(run.duration_ms, run.started_at, run.ended_at);

        return `
          <tr>
            <td><span class="run-id">#${run.id}</span></td>
            <td>${this._escapeHtml(run.project_name || run.project || (run.project_id ? `Project #${run.project_id}` : '--'))}</td>
            <td><span class="status-badge" style="background: ${cfg.bg}; color: ${cfg.color};">${cfg.label}</span></td>
            <td>${this._escapeHtml(run.trigger || run.trigger_type || '--')}</td>
            <td>${formatRunTime(run.started_at)}</td>
            <td>${duration}</td>
            <td>
              <div class="actions-cell">
                ${isRunning ? `<button class="btn btn-cancel" data-action="cancel" data-run-id="${run.id}">Cancel</button>` : ''}
                ${canReplay ? `<button class="btn btn-replay" data-action="replay" data-run-id="${run.id}">Replay</button>` : ''}
              </div>
            </td>
          </tr>
        `;
      }).join('');

      content = `
        <div class="run-count">${runs.length} runs</div>
        <div class="runs-table-wrapper">
          <table>
            <thead>
              <tr>
                <th>Run ID</th>
                <th>Project</th>
                <th>Status</th>
                <th>Trigger</th>
                <th>Started</th>
                <th>Duration</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>${rows}</tbody>
          </table>
        </div>
      `;
    }

    s.innerHTML = `
      <style>${this.getBaseStyles()}${this._getStyles()}</style>
      <div class="run-manager">
        <div class="header">
          <h2 class="title">Run Manager</h2>
          <button class="btn btn-refresh" id="refresh-btn">Refresh</button>
        </div>
        ${content}
        ${this._error ? `<div class="error-banner">${this._escapeHtml(this._error)}</div>` : ''}
      </div>
    `;

    this._attachEventListeners();
  }

  _attachEventListeners() {
    const s = this.shadowRoot;
    if (!s) return;

    const refreshBtn = s.getElementById('refresh-btn');
    if (refreshBtn) refreshBtn.addEventListener('click', () => this._loadData());

    s.querySelectorAll('[data-action="cancel"]').forEach(btn => {
      btn.addEventListener('click', () => this._cancelRun(btn.dataset.runId));
    });

    s.querySelectorAll('[data-action="replay"]').forEach(btn => {
      btn.addEventListener('click', () => this._replayRun(btn.dataset.runId));
    });
  }
}

if (!customElements.get('loki-run-manager')) {
  customElements.define('loki-run-manager', LokiRunManager);
}

export default LokiRunManager;

/**
 * @fileoverview Loki Session Control Component - control panel for managing
 * the Loki Mode session lifecycle. Provides start, pause, resume, and stop
 * controls with both compact and full layout modes. Displays connection
 * status, version info, agent/task counts, and session metadata.
 *
 * @example
 * <loki-session-control api-url="http://localhost:57374" theme="dark" compact></loki-session-control>
 */

import { LokiElement } from '../core/loki-theme.js';
import { getApiClient, ApiEvents } from '../core/loki-api-client.js';
import { getState } from '../core/loki-state.js';
import { registerPoll } from '../core/loki-poll-registry.js';

/**
 * @class LokiSessionControl
 * @extends LokiElement
 * @fires session-start - When the start button is clicked
 * @fires session-pause - When the pause button is clicked
 * @fires session-resume - When the resume button is clicked
 * @fires session-stop - When the stop button is clicked
 * @property {string} api-url - API base URL (default: window.location.origin)
 * @property {string} theme - 'light' or 'dark' (default: auto-detect)
 * @property {boolean} compact - Show compact layout when present
 */
export class LokiSessionControl extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'theme', 'compact'];
  }

  constructor() {
    super();
    this._status = {
      mode: 'offline',
      phase: null,
      iteration: null,
      complexity: null,
      connected: false,
      version: null,
      uptime: 0,
      activeAgents: 0,
      pendingTasks: 0,
    };
    // Mid-flight model switching state.
    this._model = {
      override: null,     // currently-active override alias, or null
      default: 'sonnet',  // tier-mapping fallback
      effective: 'sonnet',// what the next iteration will use
      notice: '',         // inline disclosure shown after a change
    };
    this._modelBusy = false;
    // Browser PRD-input: start a build from a spec.
    this._startBusy = false;
    this._startNotice = '';
    this._specText = '';
    // Start-time model selection (applies to the whole run from iteration 1).
    // '' means "use the engine default" (Sonnet 5). Allowed: haiku|sonnet|opus.
    this._startModel = '';
    // Advisor / reviewer judge: '' = account default, 'opus' = opt-in Opus judge.
    this._advisorModel = '';
    this._api = null;
    this._state = getState();
    this._statusUpdateHandler = null;
    this._connectedHandler = null;
    this._disconnectedHandler = null;
  }

  connectedCallback() {
    super.connectedCallback();
    this._setupApi();
    this._loadStatus();
    this._loadModel();
    this._startPolling();
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this._stopPolling();
    this._teardownApiListeners();
  }

  _teardownApiListeners() {
    if (this._api) {
      if (this._statusUpdateHandler) this._api.removeEventListener(ApiEvents.STATUS_UPDATE, this._statusUpdateHandler);
      if (this._connectedHandler) this._api.removeEventListener(ApiEvents.CONNECTED, this._connectedHandler);
      if (this._disconnectedHandler) this._api.removeEventListener(ApiEvents.DISCONNECTED, this._disconnectedHandler);
    }
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;

    if (name === 'api-url' && this._api) {
      // Adopt the correct per-URL client (no in-place baseUrl mutation, which
      // leaks across projects). Detach from the old instance, swap, re-subscribe.
      this._teardownApiListeners();
      this._setupApi();
      this._loadStatus();
      this._loadModel();
    }
    if (name === 'theme') {
      this._applyTheme();
    }
    if (name === 'compact') {
      this.render();
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });

    this._statusUpdateHandler = (e) => this._updateFromStatus(e.detail);
    this._connectedHandler = () => { this._status.connected = true; this.render(); };
    this._disconnectedHandler = () => { this._status.connected = false; this._status.mode = 'offline'; this.render(); };

    this._api.addEventListener(ApiEvents.STATUS_UPDATE, this._statusUpdateHandler);
    this._api.addEventListener(ApiEvents.CONNECTED, this._connectedHandler);
    this._api.addEventListener(ApiEvents.DISCONNECTED, this._disconnectedHandler);
  }

  async _loadStatus() {
    const api = this._api;
    try {
      const status = await api.getStatus();
      // Drop a stale response if the api-url switched mid-flight (instance swap).
      if (api !== this._api) return;
      this._updateFromStatus(status);
    } catch (error) {
      if (api !== this._api) return;
      this._status.connected = false;
      this._status.mode = 'offline';
      this.render();
    }
  }

  _updateFromStatus(status) {
    if (!status) return;

    this._status = {
      ...this._status,
      connected: true,
      mode: status.status || 'running',
      version: status.version,
      uptime: status.uptime_seconds || 0,
      activeAgents: status.running_agents || 0,
      pendingTasks: status.pending_tasks || 0,
      phase: status.phase,
      iteration: status.iteration,
      complexity: status.complexity,
    };

    this._state.updateSession({
      connected: true,
      mode: this._status.mode,
      lastSync: new Date().toISOString(),
    });

    this.render();
  }

  _startPolling() {
    // The session control lives in the right status sidebar (not inside a
    // .section-page), so it opts OUT of section gating (sectionId:
    // null) and is gated on tab visibility ONLY: a hidden tab does not poll,
    // but it stays fresh on every active section. connectedCallback already did
    // the first load, so immediate is disabled to avoid a duplicate fetch.
    this._poll = registerPoll({
      loadFn: () => this._loadStatus(),
      intervalMs: 3000,
      sectionId: null,
      immediate: false,
    });
  }

  _stopPolling() {
    if (this._poll) {
      this._poll.stop();
      this._poll = null;
    }
  }

  _formatUptime(seconds) {
    if (!seconds || seconds < 0) return '--';
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = Math.floor(seconds % 60);

    if (hours > 0) {
      return `${hours}h ${minutes}m`;
    }
    if (minutes > 0) {
      return `${minutes}m ${secs}s`;
    }
    return `${secs}s`;
  }

  _escapeHtml(str) {
    const div = document.createElement('div');
    div.textContent = String(str ?? '');
    return div.innerHTML;
  }

  _getStatusClass() {
    switch (this._status.mode) {
      case 'running':
      case 'autonomous':
        return 'active';
      case 'paused':
        return 'paused';
      case 'stopped':
        return 'stopped';
      case 'error':
        return 'error';
      default:
        return 'offline';
    }
  }

  _getStatusLabel() {
    switch (this._status.mode) {
      case 'running':
      case 'autonomous':
        return 'AUTONOMOUS';
      case 'paused':
        return 'PAUSED';
      case 'stopped':
        return 'STOPPED';
      case 'error':
        return 'ERROR';
      default:
        return 'OFFLINE';
    }
  }

  async _triggerStart() {
    if (this._startBusy) return;
    const spec = (this._specText || '').trim();
    if (!spec) {
      this._startNotice = 'Enter a spec or one-line brief to start a build.';
      this.render();
      return;
    }
    if (!this._api || typeof this._api.startSession !== 'function') {
      this._startNotice = 'Start is not available on this server.';
      this.render();
      return;
    }
    this._startBusy = true;
    this._startNotice = 'Starting build...';
    this.render();
    try {
      const result = await this._api.startSession(spec, {
        provider: this._status.provider || 'claude',
        // '' -> engine default (Sonnet 5); the client omits empty values.
        model: this._startModel || '',
        advisorModel: this._advisorModel || '',
      });
      if (result && result.error) throw new Error(result.error);
      // Transition the UI to monitoring the new run.
      this._startBusy = false;
      this._startNotice = '';
      this._specText = '';
      this._status.mode = 'running';
      this._status.connected = true;
      this.render();
      // Pull fresh status so the panel reflects the live run promptly.
      this._loadStatus();
      this.dispatchEvent(new CustomEvent('session-start', {
        detail: { ...this._status, pid: result && result.pid, spec: result && result.spec },
      }));
    } catch (err) {
      console.error('Failed to start build:', err);
      this._startBusy = false;
      // Honest surfacing of single-flight / validation errors from the API.
      this._startNotice = (err && err.message)
        ? `Could not start: ${err.message}`
        : 'Could not start the build. Try again.';
      this.render();
    }
  }

  _onSpecInput(value) {
    // Store without re-render so typing is not interrupted.
    this._specText = value;
  }

  async _triggerPause() {
    try {
      const result = await this._api.pauseSession();
      if (result && result.error) throw new Error(result.error);
      this._status.mode = 'paused';
      this.render();
      this.dispatchEvent(new CustomEvent('session-pause', { detail: this._status }));
    } catch (err) {
      console.error('Failed to pause session:', err);
      this.render();
    }
  }

  async _triggerResume() {
    try {
      const result = await this._api.resumeSession();
      if (result && result.error) throw new Error(result.error);
      this._status.mode = 'running';
      this.render();
      this.dispatchEvent(new CustomEvent('session-resume', { detail: this._status }));
    } catch (err) {
      console.error('Failed to resume session:', err);
      this.render();
    }
  }

  async _triggerStop() {
    try {
      const result = await this._api.stopSession();
      if (result && result.error) throw new Error(result.error);
      this._status.mode = 'stopped';
      this.render();
      this.dispatchEvent(new CustomEvent('session-stop', { detail: this._status }));
    } catch (err) {
      console.error('Failed to stop session:', err);
      this.render();
    }
  }

  async _loadModel() {
    if (!this._api || typeof this._api.getSessionModel !== 'function') return;
    const api = this._api;
    try {
      const m = await api.getSessionModel();
      // Drop a stale response if the api-url switched mid-flight (instance swap).
      if (api !== this._api) return;
      if (m && !m.error) {
        this._model = {
          ...this._model,
          override: m.override ?? null,
          default: m.default || 'sonnet',
          effective: m.effective || m.default || 'sonnet',
        };
        this.render();
      }
    } catch (err) {
      // Older server without the endpoint, or offline: leave defaults.
    }
  }

  async _onModelChange(value) {
    if (this._modelBusy) return;
    this._modelBusy = true;
    // Empty option means "clear override" (revert to tier mapping).
    const next = value === '' ? null : value;
    try {
      const result = await this._api.setSessionModel(next);
      if (result && result.error) throw new Error(result.error);
      this._model.override = next;
      this._model.notice = next
        ? `Switching to ${next}. Applies from the next iteration, for the current run only.`
        : 'Override cleared. Reverts to the tier mapping from the next iteration.';
      // Refresh effective model from the server (authoritative).
      this._modelBusy = false;
      await this._loadModel();
    } catch (err) {
      console.error('Failed to set session model:', err);
      this._model.notice = 'Could not change the model. Try again.';
      this._modelBusy = false;
      this.render();
    }
  }

  _renderModelControl() {
    // The selected value: the active override if set, else empty (= default/
    // tier mapping). The empty option clears the override.
    const selected = this._model.override || '';
    const opts = [
      { value: '', label: `Default (tier: ${this._escapeHtml(this._model.default)})` },
      { value: 'haiku', label: 'Haiku (fastest, cheapest)' },
      { value: 'sonnet', label: 'Sonnet 5 (balanced)' },
      { value: 'opus', label: 'Opus (top coding)' },
      { value: 'fable', label: 'Fable 5 (2x Opus cost: $10/$50 per MTok)' },
    ];
    const optionsHtml = opts.map((o) => {
      const sel = o.value === selected ? ' selected' : '';
      return `<option value="${this._escapeHtml(o.value)}"${sel}>${this._escapeHtml(o.label)}</option>`;
    }).join('');
    const isFable = this._model.effective === 'fable';
    return `
      <div class="model-control">
        <div class="model-row">
          <label for="model-select">Model</label>
          <select class="model-select" id="model-select" aria-label="Run model"${this._modelBusy ? ' disabled' : ''}>
            ${optionsHtml}
          </select>
        </div>
        ${isFable ? `<div class="model-cost-note">Fable 5 costs 2x Opus per token ($10/$50 per MTok).</div>` : ''}
        <div class="model-disclosure">Model changes apply from the next iteration, for the current run only.</div>
        ${this._model.notice ? `<div class="model-notice">${this._escapeHtml(this._model.notice)}</div>` : ''}
      </div>
    `;
  }

  _renderStartControl() {
    // Browser PRD-input: a spec textarea + model picker + Start button, shown
    // when no run is active so a user can kick off a build (and choose the
    // execution model + optional Opus advisor) straight from the dashboard.
    // Start-time model options: haiku|sonnet|opus (NO fable at start time -- fable
    // is an advisory-only 2x-Opus model and is not a Claude API dispatch model).
    // The default '' pins nothing, so the engine uses Sonnet 5.
    const startModelOpts = [
      { value: '', label: 'Sonnet 5 (default)' },
      { value: 'haiku', label: 'Haiku (fastest, cheapest)' },
      { value: 'sonnet', label: 'Sonnet 5 (balanced)' },
      { value: 'opus', label: 'Opus (top coding, priciest)' },
    ];
    const startModelHtml = startModelOpts.map((o) => {
      const sel = o.value === this._startModel ? ' selected' : '';
      return `<option value="${this._escapeHtml(o.value)}"${sel}>${this._escapeHtml(o.label)}</option>`;
    }).join('');

    // Advisor judge: account default, or an opt-in Opus reviewer that judges the
    // code-review gate while execution stays on the chosen model.
    const advisorOpts = [
      { value: '', label: 'Account default' },
      { value: 'opus', label: 'Opus (stronger judge)' },
    ];
    const advisorHtml = advisorOpts.map((o) => {
      const sel = o.value === this._advisorModel ? ' selected' : '';
      return `<option value="${this._escapeHtml(o.value)}"${sel}>${this._escapeHtml(o.label)}</option>`;
    }).join('');

    return `
      <div class="start-control">
        <label class="start-label" for="spec-input">Start a build from a spec</label>
        <textarea
          class="spec-input"
          id="spec-input"
          rows="3"
          placeholder="Paste a PRD or type a one-line brief (e.g. 'a CLI todo app in Go with JSON storage')"
          aria-label="Spec or one-line brief"
          ${this._startBusy ? 'disabled' : ''}>${this._escapeHtml(this._specText)}</textarea>

        <div class="start-field">
          <label for="start-model-select">Model</label>
          <select
            class="model-select"
            id="start-model-select"
            aria-label="Execution model for this build"
            ${this._startBusy ? 'disabled' : ''}>
            ${startModelHtml}
          </select>
        </div>

        <div class="start-field">
          <label for="advisor-select">Advisor</label>
          <select
            class="model-select"
            id="advisor-select"
            aria-label="Advisor (code-review judge) model"
            ${this._startBusy ? 'disabled' : ''}>
            ${advisorHtml}
          </select>
        </div>
        <div class="start-hint" id="advisor-hint">Advisor judges the code-review gate; execution stays on the model above.</div>

        <button class="control-btn start" id="start-btn" aria-label="Start build" ${this._startBusy ? 'disabled' : ''}>
          <svg viewBox="0 0 24 24" aria-hidden="true"><polygon points="5 3 19 12 5 21 5 3"/></svg>
          ${this._startBusy ? 'Starting...' : 'Start Build'}
        </button>
        ${this._startNotice ? `<div class="start-notice">${this._escapeHtml(this._startNotice)}</div>` : ''}
      </div>
    `;
  }

  render() {
    // Do NOT rebuild the DOM while the user is interacting with the model
    // dropdown -- a poll-driven re-render replaces the <select> and slams the
    // open menu shut, making the picker unusable (user-reported). Defer: mark
    // that a render is pending and re-run it once the dropdown closes (blur/
    // change re-call render via _modelInteracting=false). A user-initiated
    // render (start/stop/model-change) clears the flag itself, so this only
    // skips the 3s background poll re-render, never a real state change.
    if (this._modelInteracting) { this._renderPending = true; return; }
    const isCompact = this.hasAttribute('compact');
    const statusClass = this._getStatusClass();
    const statusLabel = this._getStatusLabel();
    const isRunning = ['running', 'autonomous'].includes(this._status.mode);
    const isPaused = this._status.mode === 'paused';
    // Browser PRD-input: offer Start only when no run is active.
    const canStart = !isRunning && !isPaused;

    const styles = `
