        }

        .model-row {
          display: flex;
          align-items: center;
          gap: 8px;
        }

        .model-row label {
          font-size: 11px;
          color: var(--loki-text-secondary);
          white-space: nowrap;
        }

        .model-select {
          flex: 1;
          /* Allow the select to shrink below its longest option's intrinsic
             width (the flex min-content floor) so it never overflows a narrow
             sidebar column; the native control ellipsizes the label. */
          min-width: 0;
          padding: 5px 8px;
          border-radius: 4px;
          border: 1px solid var(--loki-border);
          background: var(--loki-bg-card);
          color: var(--loki-text-primary);
          font-size: 11px;
          cursor: pointer;
        }

        .model-select:disabled {
          opacity: 0.5;
          cursor: not-allowed;
        }

        .model-cost-note {
          font-size: 10px;
          color: var(--loki-yellow);
        }

        .model-disclosure {
          font-size: 10px;
          color: var(--loki-text-muted);
        }

        .model-notice {
          font-size: 10px;
          color: var(--loki-accent);
        }

        .start-control {
          margin-top: 8px;
          padding-top: 8px;
          border-top: 1px solid var(--loki-border);
          display: flex;
          flex-direction: column;
          gap: 6px;
        }

        .start-label {
          font-size: 11px;
          font-weight: 600;
          color: var(--loki-text-secondary);
        }

        .start-field {
          display: flex;
          align-items: center;
          gap: 8px;
        }

        .start-field label {
          font-size: 11px;
          color: var(--loki-text-secondary);
          white-space: nowrap;
          /* Fixed label column so the two selects line up. */
          flex: 0 0 48px;
        }

        .start-hint {
          font-size: 10px;
          color: var(--loki-text-muted);
          line-height: 1.4;
        }

