/**
 * @fileoverview Loki Spec Panel - shows WHAT Loki is building from.
 * Surfaces the active run's spec source (PRD file, GitHub issue, one-line
 * brief, generated/OpenAPI spec, or codebase analysis) prominently so a user
 * always knows what is being built, plus a collapsible history of past specs
 * for this codebase. Data comes from GET /api/spec and GET /api/spec/history,
 * which the backend resolves honestly from real .loki state + Evidence
 * Receipts; this component never fabricates a spec.
 *
 * @example
 * <loki-spec-panel api-url="http://localhost:57374" theme="dark"></loki-spec-panel>
 */

import { LokiElement } from '../core/loki-theme.js';
import { getApiClient } from '../core/loki-api-client.js';
import { renderMarkdown, MARKDOWN_STYLES } from '../core/loki-markdown.js';

/** Human labels + short descriptions for each honest spec type. */
const TYPE_LABELS = {
  prd: 'PRD file',
  spec: 'Generated spec',
  issue: 'GitHub issue',
  brief: 'One-line brief',
  'codebase-analysis': 'Codebase analysis',
  none: 'No spec yet',
  unknown: 'Unknown spec',
};

/**
 * @class LokiSpecPanel
 * @extends LokiElement
 * @property {string} api-url - API base URL (default: window.location.origin)
 * @property {string} theme - 'light' or 'dark'
 */
export class LokiSpecPanel extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'theme'];
  }

  constructor() {
    super();
    this._api = null;
    this._spec = null; // GET /api/spec
    this._history = null; // GET /api/spec/history -> array
    this._loading = false;
    this._error = null;
    this._historyError = null;
    this._historyOpen = false;
  }

  connectedCallback() {
    super.connectedCallback();
    this._setupApi();
    this._load();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (name === 'api-url' && this._api) {
      this._api = getApiClient({ baseUrl: newValue });
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });
  }

  async _load() {
    // Drop a stale response if the api-url switched mid-flight.
    const api = this._api;
    this._loading = true;
    this._error = null;
    this.render();
    try {
      const spec = await api._get('/api/spec');
      if (api !== this._api) return;
      this._spec = spec;
    } catch (e) {
      if (api !== this._api) return;
      this._error = (e && e.message) ? e.message : 'Failed to load spec';
    } finally {
      // Skip the stale render if the api swapped mid-flight (a return inside
      // try/catch still runs this finally, so guard it here instead).
      if (api === this._api) {
        this._loading = false;
        this.render();
      }
    }
    // History loads in the background; its failure must not block the active
    // spec (the prominent surface), so it has its own error channel.
    try {
      const data = await api._get('/api/spec/history');
      if (api !== this._api) return;
      this._history = (data && Array.isArray(data.history)) ? data.history : [];
    } catch (e) {
      if (api !== this._api) return;
      this._historyError = (e && e.message) ? e.message : 'Failed to load history';
      this._history = [];
    }
    this.render();
  }

  /** Escape untrusted text for safe insertion into HTML. */
  _esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  /** Format an ISO timestamp into a short, locale-aware label (honest fallback). */
  _when(iso) {
    if (!iso) return 'unknown time';
    const d = new Date(iso);
    if (isNaN(d.getTime())) return this._esc(iso);
    try {
      return d.toLocaleString();
    } catch (e) {
      return this._esc(iso);
    }
  }

  _typeLabel(type) {
    return TYPE_LABELS[type] || TYPE_LABELS.unknown;
  }

  /** Small pill showing the spec type. */
  _typeBadge(type) {
    return `<span class="badge badge-${this._esc(type)}">${this._esc(this._typeLabel(type))}</span>`;
  }

  /** The prominent active-spec block. */
  _renderActive() {
    if (this._loading) {
      return `<div class="es-loading"><span class="es-spinner"></span> Loading active spec...</div>`;
    }
    if (this._error) {
      return this._renderError(this._error);
    }
    const s = this._spec;
    if (!s || !s.type || s.type === 'none') {
      return this._renderEmpty();
    }

    const badge = this._typeBadge(s.type);
    let meta = '';
    let body = '';

    if (s.type === 'prd' || s.type === 'spec') {
      if (s.path) meta = `<code class="src">${this._esc(s.path)}</code>`;
      const content = s.content || '';
      if (content.trim()) {
        // Render the spec as a formatted document, not a raw markdown dump.
        // renderMarkdown escapes its input first, so a spec containing <script>
        // is shown as text and cannot inject.
        body = `<div class="body md-body">${renderMarkdown(content)}</div>`
          + (s.truncated ? `<p class="dim">Preview truncated -- see the full file on disk.</p>` : '');
      } else {
        body = `<p class="dim">No content available.</p>`;
      }
    } else if (s.type === 'issue') {
      const ref = s.ref ? `<code class="src">${this._esc(s.ref)}</code>` : '';
      meta = ref;
      const title = s.title ? `<p class="issue-title">${this._esc(s.title)}</p>` : '';
      const issueBody = (s.body || '').trim()
        ? `<div class="body md-body">${renderMarkdown(s.body)}</div>`
          + (s.truncated ? `<p class="dim">Preview truncated.</p>` : '')
        : '';
      body = `${title}${issueBody}`;
    } else if (s.type === 'brief') {
      const text = (s.text || '').trim();
      body = text
        ? `<pre class="body brief">${this._esc(text)}</pre>`
          + (s.truncated ? `<p class="dim">Preview truncated.</p>` : '')
        : `<p class="dim">No brief recorded.</p>`;
    } else if (s.type === 'codebase-analysis') {
      body = `<p class="dim">No explicit spec. Loki is building from an analysis of the existing codebase.</p>`;
    } else {
      body = `<p class="dim">The spec source could not be resolved.</p>`;
    }

    return `<div class="active">
      <div class="active-head">
        <span class="active-label">Building from</span>
        ${badge}
      </div>
      ${meta ? `<div class="active-meta">${meta}</div>` : ''}
      ${body}
    </div>`;
  }

  /** Collapsible history of past specs. */
  _renderHistory() {
    const list = this._history || [];
    const count = list.length;
    const caret = this._historyOpen ? 'open' : '';
    let inner = '';
    if (this._historyOpen) {
      if (this._historyError) {
        inner = `<div class="es-inline-error">${this._esc(this._historyError)}</div>`;
      } else if (count === 0) {
        inner = `<p class="dim hist-empty">No past specs yet. Each completed run records its spec here.</p>`;
      } else {
        const rows = list.map((h) => `
          <li class="hist-row">
            <span class="hist-when">${this._when(h.when)}</span>
            ${this._typeBadge(h.type)}
            <span class="hist-summary">${this._esc(h.summary || '')}</span>
          </li>`).join('');
        inner = `<ul class="hist-list">${rows}</ul>`;
      }
    }
    return `<div class="history">
      <button class="hist-toggle ${caret}" id="hist-toggle" aria-expanded="${this._historyOpen}">
        <svg class="caret" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
        Spec history${count ? ` <span class="dim">(${count})</span>` : ''}
      </button>
      ${inner}
    </div>`;
  }

  /** Honest empty state when no run has produced a spec yet. */
  _renderEmpty() {
    const fileIcon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>';
    return `<div class="es">
      <div class="es-icon">${fileIcon}</div>
      <div class="es-title">No spec yet</div>
      <div class="es-desc">When a run starts, the spec it builds from (a PRD, GitHub issue, one-line brief, or codebase analysis) appears here.</div>
    </div>`;
  }

  /** Branded error state with a retry button. */
  _renderError(message) {
    const alertIcon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>';
    return `<div class="es">
      <div class="es-icon es-icon-error">${alertIcon}</div>
      <div class="es-title">Couldn't load the spec</div>
      <div class="es-desc">${this._esc(message)}</div>
      <button class="es-cta" id="spec-retry-btn">Retry</button>
    </div>`;
  }

  render() {
    if (!this.shadowRoot) return;
    this.shadowRoot.innerHTML = `
      <style>
        ${this.getBaseStyles()}
        ${MARKDOWN_STYLES}
        :host { display: block; }
        .active { background: var(--loki-bg-secondary); border: 1px solid var(--loki-border);
          border-radius: var(--loki-radius-lg, 5px); padding: 16px; }
        .active-head { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }
        .active-label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.05em;
          color: var(--loki-text-muted); }
        .active-meta { margin-bottom: 10px; }
        .issue-title { font-size: 14px; font-weight: 600; color: var(--loki-text-primary);
          margin: 0 0 8px; }
        .badge { display: inline-block; padding: 2px 9px; border-radius: var(--loki-radius-full, 9999px);
          font-size: 11px; font-weight: 600; background: var(--loki-accent-muted); color: var(--loki-accent); }
        .badge-codebase-analysis { background: var(--loki-bg-tertiary); color: var(--loki-text-secondary); }
        .badge-none, .badge-unknown { background: var(--loki-bg-tertiary); color: var(--loki-text-muted); }
        .src { font-family: var(--loki-font-mono, monospace); font-size: 12px;
          background: var(--loki-bg-tertiary); color: var(--loki-text-secondary);
          padding: 2px 7px; border-radius: 3px; word-break: break-all; }
        /* Scroll chrome for the rendered spec/issue document. The markdown
           itself is styled by MARKDOWN_STYLES (.md-body), injected below. */
        .body { word-break: break-word;
          max-height: 320px; overflow: auto;
          background: var(--loki-bg-tertiary);
          padding: 12px; border-radius: var(--loki-radius-md, 4px);
          border: 1px solid var(--loki-border); margin: 0; }
        /* The brief is a one-line plain-text spec, kept as a preformatted block. */
        .body.brief { white-space: pre-wrap;
          font-family: var(--loki-font-mono, monospace); font-size: 12px;
          line-height: 1.6; color: var(--loki-text-primary); }
        .dim { color: var(--loki-text-muted); font-size: 12px; }

        /* History */
        .history { margin-top: 16px; }
        .hist-toggle { display: flex; align-items: center; gap: 6px; width: 100%;
          background: none; border: none; cursor: pointer; padding: 8px 0;
          font-size: 13px; font-weight: 600; font-family: inherit;
          color: var(--loki-text-primary); text-align: left; }
        .hist-toggle .caret { width: 14px; height: 14px; transition: transform 0.15s ease; }
        .hist-toggle.open .caret { transform: rotate(90deg); }
        .hist-list { list-style: none; margin: 4px 0 0; padding: 0;
          border-top: 1px solid var(--loki-border); }
        .hist-row { display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
          padding: 9px 2px; border-bottom: 1px solid var(--loki-border); font-size: 12px; }
        .hist-when { color: var(--loki-text-muted); min-width: 130px; }
        .hist-summary { color: var(--loki-text-secondary); flex: 1; word-break: break-word; }
        .hist-empty { padding: 8px 2px; }

        /* Branded empty / loading / error states */
        .es { display: flex; flex-direction: column; align-items: center;
          text-align: center; padding: 40px 24px; gap: 4px; }
        .es-icon { width: 44px; height: 44px; display: flex; align-items: center;
          justify-content: center; border-radius: var(--loki-radius-full, 9999px);
          background: var(--loki-accent-muted); color: var(--loki-accent); margin-bottom: 14px; }
        .es-icon-error { background: var(--loki-error-muted); color: var(--loki-error); }
        .es-icon svg { width: 22px; height: 22px; }
        .es-title { font-size: 15px; font-weight: 600; color: var(--loki-text-primary); }
        .es-desc { font-size: 13px; color: var(--loki-text-muted); line-height: 1.55; max-width: 400px; }
        .es-cta { margin-top: 16px; padding: 9px 18px; background: var(--loki-accent);
          color: var(--loki-text-inverse); border: none; border-radius: var(--loki-radius-md, 4px);
          font-size: 13px; font-weight: 500; font-family: inherit; cursor: pointer; }
        .es-cta:hover { background: var(--loki-accent-hover); }
        .es-loading { display: flex; align-items: center; justify-content: center; gap: 8px;
          padding: 40px 16px; color: var(--loki-text-muted); font-size: 13px; }
        .es-spinner { width: 14px; height: 14px; border: 2px solid var(--loki-border);
          border-top-color: var(--loki-accent); border-radius: 50%;
          animation: es-spin 0.8s linear infinite; }
        .es-inline-error { margin: 8px 0; padding: 10px 12px; font-size: 12px;
          color: var(--loki-error); background: var(--loki-error-muted);
          border-radius: var(--loki-radius-md, 4px); }
        @keyframes es-spin { to { transform: rotate(360deg); } }
      </style>
      <div class="active-wrap">${this._renderActive()}</div>
      ${(this._error || (this._spec && this._spec.type === 'none')) ? '' : this._renderHistory()}
    `;

    const retryBtn = this.shadowRoot.getElementById('spec-retry-btn');
    if (retryBtn) {
      retryBtn.addEventListener('click', () => this._load());
    }
    const toggle = this.shadowRoot.getElementById('hist-toggle');
    if (toggle) {
      toggle.addEventListener('click', () => {
        this._historyOpen = !this._historyOpen;
        this.render();
      });
    }
  }
}

if (!customElements.get('loki-spec-panel')) {
  customElements.define('loki-spec-panel', LokiSpecPanel);
}

export default LokiSpecPanel;

/**
 * @fileoverview Loki Task Board Component - a Kanban-style task board for
 * displaying and managing tasks across four columns: Pending, In Progress,
 * In Review, and Completed. Supports drag-and-drop reordering and
 * keyboard navigation.
 *
 * @example
 * <loki-task-board api-url="http://localhost:57374" project-id="1" theme="dark"></loki-task-board>
 */

import { LokiElement } from '../core/loki-theme.js';
import { getApiClient, ApiEvents } from '../core/loki-api-client.js';
import { getState } from '../core/loki-state.js';
import { renderMarkdown, MARKDOWN_STYLES } from '../core/loki-markdown.js';

/** @type {Array<{id: string, label: string, status: string, color: string}>} */
const COLUMNS = [
  { id: 'pending', label: 'Pending', status: 'pending', color: 'var(--loki-text-muted)' },
  { id: 'in_progress', label: 'In Progress', status: 'in_progress', color: 'var(--loki-blue)' },
  { id: 'review', label: 'In Review', status: 'review', color: 'var(--loki-purple)' },
  { id: 'done', label: 'Completed', status: 'done', color: 'var(--loki-green)' },
];

/**
 * @class LokiTaskBoard
 * @extends LokiElement
 * @fires task-moved - When a task is dragged to a new column
 * @fires add-task - When the add task button is clicked
 * @fires task-click - When a task card is clicked
 * @property {string} api-url - API base URL (default: window.location.origin)
 * @property {string} project-id - Filter tasks by project ID
 * @property {string} theme - 'light' or 'dark' (default: auto-detect)
 * @property {boolean} readonly - Disables drag-drop and editing when present
 */
export class LokiTaskBoard extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'project-id', 'theme', 'readonly'];
  }

  constructor() {
    super();
    this._tasks = [];
    this._loading = true;
    this._error = null;
    this._draggedTask = null;
    this._selectedTask = null;
    this._expandedCards = new Set();
    this._selectedTasks = new Set();
    this._bulkMode = false;
    this._activeFilter = 'all';
    this._searchQuery = '';
    // Per-column visible page count. Keyed by status; each column starts
    // capped at PAGE_SIZE and grows by PAGE_SIZE when "Show more" is used.
    // This bounds the DOM so a status with many tasks (e.g. dozens of pending
    // PRD items) does not become an endless vertical scroll.
    this._visibleCounts = {};
    this._api = null;
    this._state = getState();
  }

  /** Number of cards rendered per column page before "Show more" appears. */
  static get PAGE_SIZE() {
    return 10;
  }

  _getVisibleCount(status) {
    const n = this._visibleCounts[status];
    return typeof n === 'number' && n > 0 ? n : LokiTaskBoard.PAGE_SIZE;
  }

  _showMore(status) {
    this._visibleCounts[status] = this._getVisibleCount(status) + LokiTaskBoard.PAGE_SIZE;
    this.render();
  }

  _columnIcon(status) {
    switch (status) {
      case 'pending':
        return '<circle cx="12" cy="12" r="10"/>';
      case 'in_progress':
        return '<path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83"/>';
      case 'review':
        return '<path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/>';
      case 'done':
        return '<path d="M22 11.08V12a10 10 0 11-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/>';
      default:
        return '<circle cx="12" cy="12" r="10"/>';
    }
  }

  connectedCallback() {
    super.connectedCallback();
    this._setupApi();
    this._loadTasks();
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this._teardownApiListeners();
  }

  _teardownApiListeners() {
    // Detach from the CURRENT instance (must run before swapping this._api so we
    // remove from the right instance, not the new one).
    if (this._api && this._onTaskEvent) {
      this._api.removeEventListener(ApiEvents.TASK_CREATED, this._onTaskEvent);
      this._api.removeEventListener(ApiEvents.TASK_UPDATED, this._onTaskEvent);
      this._api.removeEventListener(ApiEvents.TASK_DELETED, this._onTaskEvent);
    }
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;

    if (name === 'api-url' && this._api) {
      // Adopt the correct per-URL client (no in-place baseUrl mutation, which
      // leaks one project's tasks into another). Detach from the old instance,
      // swap, re-subscribe.
      this._teardownApiListeners();
      this._setupApi();
      this._loadTasks();
    }
    if (name === 'project-id') {
      this._loadTasks();
    }
    if (name === 'theme') {
      this._applyTheme();
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });

    this._onTaskEvent = () => this._loadTasks();
    this._api.addEventListener(ApiEvents.TASK_CREATED, this._onTaskEvent);
    this._api.addEventListener(ApiEvents.TASK_UPDATED, this._onTaskEvent);
    this._api.addEventListener(ApiEvents.TASK_DELETED, this._onTaskEvent);
  }

  async _loadTasks() {
    // Capture the active client; a project/api-url switch swaps this._api.
    const api = this._api;
    this._loading = true;
    this._error = null;
    this.render();

    try {
      const projectId = this.getAttribute('project-id');
      const filters = projectId ? { projectId: parseInt(projectId) } : {};
      const tasks = await api.listTasks(filters);
      // Drop a stale response if the api-url switched mid-flight (instance swap)
      // so the old project's tasks never render against the new project.
      if (api !== this._api) return;
      this._tasks = tasks;

      // Merge with local tasks
      const localTasks = this._state.get('localTasks') || [];
      if (localTasks.length > 0) {
        this._tasks = [...this._tasks, ...localTasks.map(t => ({ ...t, isLocal: true }))];
      }

      this._state.update({ 'cache.tasks': this._tasks }, false);
    } catch (error) {
      if (api !== this._api) return;
      this._error = error.message;
      // Fall back to local tasks only
      this._tasks = (this._state.get('localTasks') || []).map(t => ({ ...t, isLocal: true }));
    }

    this._loading = false;
    this.render();
  }

  _getTasksByStatus(status) {
    const tasks = this._getFilteredTasks();
    return tasks.filter(t => {
      const taskStatus = t.status?.toLowerCase().replace(/-/g, '_');
      return taskStatus === status;
    });
  }

  _handleDragStart(e, task) {
    if (this.hasAttribute('readonly')) return;

    this._draggedTask = task;
    e.target.classList.add('dragging');
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', task.id.toString());
  }

  _handleDragEnd(e) {
    e.target.classList.remove('dragging');
    this._draggedTask = null;
    this.shadowRoot.querySelectorAll('.kanban-tasks').forEach(el => {
      el.classList.remove('drag-over');
    });
  }

  _handleDragOver(e) {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  }

  _handleDragEnter(e) {
    e.preventDefault();
    e.currentTarget.classList.add('drag-over');
  }

  _handleDragLeave(e) {
    if (!e.currentTarget.contains(e.relatedTarget)) {
      e.currentTarget.classList.remove('drag-over');
    }
  }

  async _handleDrop(e, newStatus) {
    e.preventDefault();
    e.currentTarget.classList.remove('drag-over');

    if (!this._draggedTask || this.hasAttribute('readonly')) return;

    const taskId = this._draggedTask.id;
    const task = this._tasks.find(t => t.id === taskId);
    if (!task) return;

    const oldStatus = task.status;
    if (oldStatus === newStatus) return;

    // Optimistic update
    task.status = newStatus;
    this.render();

    try {
      if (task.isLocal) {
        this._state.moveLocalTask(taskId, newStatus);
      } else {
        await this._api.moveTask(taskId, newStatus, 0);
      }

      this.dispatchEvent(new CustomEvent('task-moved', {
        detail: { taskId, oldStatus, newStatus }
      }));
    } catch (error) {
      // Revert on error
      task.status = oldStatus;
      this.render();
      console.error('Failed to move task:', error);
    }
  }

  _toggleCardExpand(taskId) {
    if (this._expandedCards.has(taskId)) {
      this._expandedCards.delete(taskId);
    } else {
      this._expandedCards.add(taskId);
    }
    this.render();
  }

  _toggleTaskSelection(taskId, event) {
    if (event) event.stopPropagation();
    if (this._selectedTasks.has(taskId)) {
      this._selectedTasks.delete(taskId);
    } else {
      this._selectedTasks.add(taskId);
    }
    this.render();
  }

  _toggleBulkMode() {
    this._bulkMode = !this._bulkMode;
    if (!this._bulkMode) {
      this._selectedTasks.clear();
    }
    this.render();
  }

  async _bulkMove(newStatus) {
    const taskIds = [...this._selectedTasks];
    for (const taskId of taskIds) {
      const task = this._tasks.find(t => String(t.id) === String(taskId));
      if (task && task.status !== newStatus) {
        try {
          if (task.isLocal) {
            this._state.moveLocalTask(taskId, newStatus);
          } else {
            await this._api.moveTask(taskId, newStatus, 0);
          }
          task.status = newStatus;
        } catch (error) {
          console.error('Failed to bulk move task:', taskId, error);
        }
      }
    }
    this._selectedTasks.clear();
    this._bulkMode = false;
    this.render();
    this._loadTasks();
  }

  async _bulkDelete() {
    const taskIds = [...this._selectedTasks];
    for (const taskId of taskIds) {
      try {
        await this._api.deleteTask(taskId);
      } catch (error) {
        console.error('Failed to delete task:', taskId, error);
      }
    }
    this._selectedTasks.clear();
    this._bulkMode = false;
    this._loadTasks();
  }

  _setFilter(filter) {
    this._activeFilter = filter;
    // Narrowing the set resets per-column paging so "Show more" state from a
    // wider view does not carry over to the narrower one.
    this._visibleCounts = {};
    this.render();
  }

  _setSearch(query) {
    this._searchQuery = query || '';
    this._visibleCounts = {};
    // Re-render the list region only; preserve focus + caret in the search box.
    this._renderTaskRegion();
    const input = this.shadowRoot.getElementById('task-search');
    if (input) {
      input.focus();
      const len = input.value.length;
      try { input.setSelectionRange(len, len); } catch (e) { /* non-text input */ }
    }
  }

  _getFilteredTasks() {
    let filtered = [...this._tasks];
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const weekAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);

    switch (this._activeFilter) {
      case 'today':
        filtered = filtered.filter(t => {
          const created = t.created_at ? new Date(t.created_at) : null;
          return created && created >= today;
        });
        break;
      case 'this-week':
        filtered = filtered.filter(t => {
          const created = t.created_at ? new Date(t.created_at) : null;
          return created && created >= weekAgo;
        });
        break;
      case 'running':
        filtered = filtered.filter(t => t.status === 'in_progress');
        break;
      case 'failed':
        filtered = filtered.filter(t => t.status === 'failed' || t.status === 'error');
        break;
      default:
        break;
    }

    const q = this._searchQuery.trim().toLowerCase();
    if (q) {
      filtered = filtered.filter(t => {
        const haystack = [
          t.id,
          t.title,
          t.description,
          t.type,
        ].map(v => String(v ?? '').toLowerCase()).join(' ');
        return haystack.includes(q);
      });
    }

    return filtered;
  }

  _openAddTaskModal(status = 'pending') {
    this.dispatchEvent(new CustomEvent('add-task', { detail: { status } }));
  }

  _openTaskDetail(task) {
    this._selectedTask = task;
    this.render();
    this.dispatchEvent(new CustomEvent('task-click', { detail: { task } }));
  }

  _closeTaskDetail() {
    this._selectedTask = null;
    this.render();
  }

  _renderMarkdown(md) {
    // Delegates to the shared, XSS-safe renderer so task descriptions render
    // identically to every other markdown surface (Spec, Wiki, escalations) and
    // cannot drift. The output uses the same .md-* classes this component's
    // .md-body styles already target; renderMarkdown escapes its input first.
    return renderMarkdown(md);
  }

  _formatTimestamp(ts) {
    if (!ts) return '';
    try {
      const d = new Date(ts);
      if (isNaN(d.getTime())) return this._escapeHtml(String(ts));
      return d.toLocaleString();
    } catch (e) {
      return this._escapeHtml(String(ts));
    }
  }

  _phaseClass(phase) {
    const p = String(phase || '').toLowerCase();
    if (['reason', 'plan', 'planning'].includes(p)) return 'phase-reason';
    if (['act', 'execute', 'execution', 'implement'].includes(p)) return 'phase-act';
    if (['reflect', 'review'].includes(p)) return 'phase-reflect';
    if (['verify', 'test', 'gate'].includes(p)) return 'phase-verify';
    return 'phase-default';
  }

  _logLevelClass(level) {
    const l = String(level || 'info').toLowerCase();
    if (l === 'error' || l === 'fatal') return 'log-error';
    if (l === 'warn' || l === 'warning') return 'log-warn';
    if (l === 'debug' || l === 'trace') return 'log-debug';
    return 'log-info';
  }

  _renderTaskDetailModal(task) {
    if (!task) return '';

    const priority = (task.priority || 'medium').toLowerCase();
    const priorityLabel = priority.charAt(0).toUpperCase() + priority.slice(1);
    const status = task.status || 'pending';
    const statusLabel = status.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
    const meta = task.metadata || {};
    const criteria = Array.isArray(task.acceptance_criteria) ? task.acceptance_criteria : [];
    const contextFiles = Array.isArray(task.context_files) ? task.context_files : [];
    const spec = task.specification || '';
    const description = task.description || '';
    const notes = Array.isArray(task.notes) ? task.notes : [];
    const logs = Array.isArray(task.logs) ? task.logs : [];
    const fullContent = task.full_content || '';

    return `
      <div class="modal-overlay" id="task-detail-overlay">
        <div class="modal-container">
          <div class="modal-header">
            <div class="modal-header-left">
              <span class="task-id">${task.isLocal ? 'LOCAL' : '#' + this._escapeHtml(String(task.id))}</span>
              <span class="task-priority ${priority}">${priorityLabel}</span>
              <span class="task-status-badge ${status}">${statusLabel}</span>
            </div>
            <button class="modal-close" id="modal-close-btn" aria-label="Close">&times;</button>
          </div>
          <h2 class="modal-title">${this._escapeHtml(task.title || 'Untitled')}</h2>

          ${Object.keys(meta).length > 0 ? `
            <div class="modal-section">
              <h3 class="modal-section-title">Metadata</h3>
              <div class="meta-grid">
                ${Object.entries(meta).map(([k, v]) => `
                  <div class="meta-cell">
                    <span class="meta-label">${this._escapeHtml(k.replace(/_/g, ' '))}</span>
                    <span class="meta-value">${this._escapeHtml(String(v))}</span>
                  </div>
                `).join('')}
              </div>
            </div>
          ` : ''}

          ${description ? `
            <div class="modal-section">
              <h3 class="modal-section-title">Description</h3>
              <div class="modal-prose md-body">${this._renderMarkdown(description)}</div>
            </div>
          ` : ''}

          ${spec ? `
            <div class="modal-section">
              <h3 class="modal-section-title">Specification</h3>
              <div class="modal-prose">${this._escapeHtml(spec)}</div>
            </div>
          ` : ''}

          ${criteria.length > 0 ? `
            <div class="modal-section">
              <h3 class="modal-section-title">Acceptance Criteria</h3>
              <ul class="criteria-checklist" role="list">
                ${criteria.map(c => {
                  const isObj = c && typeof c === 'object';
                  const text = isObj ? (c.text || c.title || '') : c;
                  const done = isObj ? !!c.done : false;
                  return `<li class="criteria-item">
                    <span class="criteria-checkbox ${done ? 'checked' : ''}" aria-hidden="true">${done ? '&#10003;' : ''}</span>
                    <span class="criteria-text ${done ? 'done' : ''}">${this._escapeHtml(String(text))}</span>
                  </li>`;
                }).join('')}
              </ul>
            </div>
          ` : ''}

          ${notes.length > 0 ? `
            <div class="modal-section">
              <h3 class="modal-section-title">Notes</h3>
              <ul class="notes-timeline" role="list">
                ${notes.map(n => {
                  const ts = this._formatTimestamp(n && n.timestamp);
                  const author = n && n.author ? this._escapeHtml(String(n.author)) : 'unknown';
                  const body = n && n.body ? this._escapeHtml(String(n.body)) : '';
                  return `<li class="note-entry">
                    <div class="note-meta">
                      <span class="note-author">${author}</span>
                      ${ts ? `<span class="note-time">${ts}</span>` : ''}
                    </div>
                    <div class="note-body">${body}</div>
                  </li>`;
                }).join('')}
              </ul>
            </div>
          ` : ''}

          ${logs.length > 0 ? `
            <div class="modal-section">
              <h3 class="modal-section-title">Logs</h3>
              <div class="logs-scroll">
                <ul class="logs-timeline" role="list">
                  ${logs.map(l => {
                    const ts = this._formatTimestamp(l && l.timestamp);
                    const iter = l && (l.iteration !== undefined && l.iteration !== null) ? `i${this._escapeHtml(String(l.iteration))}` : '';
                    const phase = l && l.phase ? String(l.phase) : '';
                    const phaseClass = this._phaseClass(phase);
                    const levelClass = this._logLevelClass(l && l.level);
                    const message = l && l.message ? this._escapeHtml(String(l.message)) : '';
                    return `<li class="log-entry ${levelClass}">
                      ${ts ? `<span class="log-time">${ts}</span>` : ''}
                      ${iter ? `<span class="log-iter">${iter}</span>` : ''}
                      ${phase ? `<span class="log-phase ${phaseClass}">${this._escapeHtml(phase)}</span>` : ''}
                      <span class="log-message">${message}</span>
                    </li>`;
                  }).join('')}
                </ul>
              </div>
            </div>
          ` : ''}

          ${contextFiles.length > 0 ? `
            <div class="modal-section">
              <h3 class="modal-section-title">Context Files</h3>
              <ul class="context-files-list">
                ${contextFiles.map(f => `<li class="mono">${this._escapeHtml(f)}</li>`).join('')}
              </ul>
            </div>
          ` : ''}

          ${fullContent && !spec ? `
            <div class="modal-section">
              <h3 class="modal-section-title">Full Content</h3>
              <pre class="modal-pre">${this._escapeHtml(fullContent)}</pre>
            </div>
          ` : ''}

          ${task.user_story ? `
            <div class="modal-section">
              <h3 class="modal-section-title">User Story</h3>
              <div class="modal-prose">${this._escapeHtml(task.user_story)}</div>
            </div>
          ` : ''}

          ${task.source ? `
            <div class="modal-section">
              <h3 class="modal-section-title">Source</h3>
              <div class="modal-prose"><code>${this._escapeHtml(task.source)}</code></div>
            </div>
          ` : ''}

          ${task.type ? `
            <div class="modal-footer">
              <span class="task-type">${this._escapeHtml(task.type)}</span>
              ${task.assigned_agent_id ? `<span class="meta-value">Agent #${task.assigned_agent_id}</span>` : ''}
            </div>
          ` : ''}
        </div>
      </div>
    `;
  }

