/**
 * @fileoverview Multi-Tenant Context Switcher - dropdown component for
 * switching between tenants. Dispatches a 'tenant-changed' custom event
 * when the user selects a different tenant. Includes an "All tenants"
 * option for unfiltered views.
 *
 * @example
 * <loki-tenant-switcher api-url="http://localhost:57374" theme="dark"></loki-tenant-switcher>
 */

import { LokiElement } from '../core/loki-theme.js';
import { getApiClient } from '../core/loki-api-client.js';

/**
 * Format a tenant for display.
 * @param {Object} tenant - Tenant object with name and slug
 * @returns {string} Display string
 */
export function formatTenantLabel(tenant) {
  if (!tenant) return 'Unknown';
  if (tenant.slug && tenant.name) {
    return `${tenant.name} (${tenant.slug})`;
  }
  return tenant.name || tenant.slug || 'Unknown';
}

/**
 * @class LokiTenantSwitcher
 * @extends LokiElement
 * @fires tenant-changed - When the user selects a different tenant
 * @property {string} api-url - API base URL
 * @property {string} theme - 'light' or 'dark'
 */
export class LokiTenantSwitcher extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'theme'];
  }

  constructor() {
    super();
    this._loading = false;
    this._error = null;
    this._api = null;
    this._tenants = [];
    this._selectedTenantId = null;
    this._dropdownOpen = false;
  }

  connectedCallback() {
    super.connectedCallback();
    this._setupApi();
    this._loadData();

    // Close dropdown on outside click
    this._outsideClickHandler = (e) => {
      if (this._dropdownOpen && !this.contains(e.target)) {
        this._dropdownOpen = false;
        this.render();
      }
    };
    document.addEventListener('click', this._outsideClickHandler);
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    if (this._outsideClickHandler) {
      document.removeEventListener('click', this._outsideClickHandler);
      this._outsideClickHandler = null;
    }
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    if (name === 'api-url' && this._api) {
      this._api = getApiClient({ baseUrl: newValue });
      this._loadData();
    }
    if (name === 'theme') {
      this._applyTheme();
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });
  }

  async _loadData() {
    const api = this._api;
    try {
      this._loading = true;
      const data = await api._get('/api/v2/tenants');
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      this._tenants = Array.isArray(data) ? data : (data?.tenants || []);
      this._error = null;
    } catch (err) {
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      this._error = `Failed to load tenants: ${err.message}`;
    } finally {
      this._loading = false;
    }

    this.render();
  }

  _toggleDropdown() {
    this._dropdownOpen = !this._dropdownOpen;
    this.render();
  }

  _selectTenant(tenantId, tenantName) {
    this._selectedTenantId = tenantId;
    this._dropdownOpen = false;
    this.render();

    this.dispatchEvent(new CustomEvent('tenant-changed', {
      detail: { tenantId, tenantName },
      bubbles: true,
      composed: true,
    }));
  }

  _getSelectedTenant() {
    if (this._selectedTenantId == null) return null;
    return this._tenants.find(t => (t.id || t.slug) === this._selectedTenantId) || null;
  }

  _escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  _getStyles() {
    return `
      :host {
        display: inline-block;
        position: relative;
      }

      .tenant-switcher {
        font-family: var(--loki-font-family, 'Inter', -apple-system, sans-serif);
        color: var(--loki-text-primary, #201515);
        position: relative;
      }

      .trigger {
        display: flex;
        align-items: center;
        gap: 8px;
        padding: 6px 12px;
        background: var(--loki-bg-card, #ffffff);
        border: 1px solid var(--loki-border, #ECEAE3);
        border-radius: 4px;
        cursor: pointer;
        font-size: 13px;
        font-weight: 500;
        color: var(--loki-text-primary, #201515);
        transition: all 0.15s ease;
        min-width: 180px;
        justify-content: space-between;
      }

      .trigger:hover {
        border-color: var(--loki-border-light, #C5C0B1);
      }

      .trigger.open {
        border-color: var(--loki-accent, #553DE9);
      }

      .trigger-label {
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
      }

      .trigger-icon {
        flex-shrink: 0;
        font-size: 10px;
        color: var(--loki-text-muted, #939084);
        transition: transform 0.15s ease;
      }

      .trigger-icon.open {
        transform: rotate(180deg);
      }

      .dropdown {
        position: absolute;
        top: calc(100% + 4px);
        left: 0;
        right: 0;
        min-width: 220px;
        background: var(--loki-bg-card, #ffffff);
        border: 1px solid var(--loki-border, #ECEAE3);
        border-radius: 5px;
        box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
        z-index: 100;
        overflow: hidden;
      }

      .dropdown-item {
        display: flex;
        align-items: center;
        gap: 8px;
        padding: 8px 14px;
        font-size: 13px;
        cursor: pointer;
        transition: background 0.1s ease;
        color: var(--loki-text-primary, #201515);
        border: none;
        background: none;
        width: 100%;
        text-align: left;
      }

      .dropdown-item:hover {
        background: var(--loki-bg-hover, #1f1f23);
      }

      .dropdown-item.selected {
        background: var(--loki-accent-muted, rgba(139, 92, 246, 0.15));
        color: var(--loki-accent, #553DE9);
      }

      .dropdown-item.all-tenants {
        border-bottom: 1px solid var(--loki-border, #ECEAE3);
        font-weight: 500;
      }

      .tenant-slug {
        font-size: 11px;
        color: var(--loki-text-muted, #939084);
        font-family: 'JetBrains Mono', monospace;
      }

      .tenant-info {
        display: flex;
        flex-direction: column;
        gap: 1px;
        overflow: hidden;
      }

      .tenant-name {
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
      }

      .check-mark {
        margin-left: auto;
        color: var(--loki-accent, #553DE9);
        font-size: 14px;
        flex-shrink: 0;
      }

      .error-text {
        padding: 8px 14px;
        color: var(--loki-red, #ef4444);
        font-size: 12px;
      }

      .loading-text {
        padding: 8px 14px;
        color: var(--loki-text-muted, #939084);
        font-size: 12px;
      }
    `;
  }

  render() {
    const s = this.shadowRoot;
    if (!s) return;

    const selected = this._getSelectedTenant();
    const triggerText = selected ? formatTenantLabel(selected) : 'All Tenants';
    const isOpen = this._dropdownOpen;

    let dropdownHtml = '';
    if (isOpen) {
      let itemsHtml;
      if (this._loading) {
        itemsHtml = '<div class="loading-text">Loading tenants...</div>';
      } else if (this._error) {
        itemsHtml = `<div class="error-text">${this._escapeHtml(this._error)}</div>`;
      } else {
        const allSelected = this._selectedTenantId == null;
        itemsHtml = `
          <button class="dropdown-item all-tenants ${allSelected ? 'selected' : ''}" data-tenant-id="">
            <span class="tenant-name">All Tenants</span>
            ${allSelected ? '<span class="check-mark">*</span>' : ''}
          </button>
          ${this._tenants.map(t => {
            const id = t.id || t.slug;
            const isSelected = this._selectedTenantId === id;
            return `
              <button class="dropdown-item ${isSelected ? 'selected' : ''}"
                      data-tenant-id="${this._escapeHtml(String(id))}"
                      data-tenant-name="${this._escapeHtml(t.name || '')}">
                <div class="tenant-info">
                  <span class="tenant-name">${this._escapeHtml(t.name || 'Unnamed')}</span>
                  ${t.slug ? `<span class="tenant-slug">${this._escapeHtml(t.slug)}</span>` : ''}
                </div>
                ${isSelected ? '<span class="check-mark">*</span>' : ''}
              </button>
            `;
          }).join('')}
        `;
      }

      dropdownHtml = `<div class="dropdown">${itemsHtml}</div>`;
    }

    s.innerHTML = `
      <style>${this.getBaseStyles()}${this._getStyles()}</style>
      <div class="tenant-switcher">
        <button class="trigger ${isOpen ? 'open' : ''}" id="trigger-btn">
          <span class="trigger-label">${this._escapeHtml(triggerText)}</span>
          <span class="trigger-icon ${isOpen ? 'open' : ''}">&#9660;</span>
        </button>
        ${dropdownHtml}
      </div>
    `;

    this._attachEventListeners();
  }

  _attachEventListeners() {
    const s = this.shadowRoot;
    if (!s) return;

    const triggerBtn = s.getElementById('trigger-btn');
    if (triggerBtn) {
      triggerBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        this._toggleDropdown();
      });
    }

    s.querySelectorAll('.dropdown-item').forEach(item => {
      item.addEventListener('click', (e) => {
        e.stopPropagation();
        const tenantId = item.dataset.tenantId || null;
        const tenantName = item.dataset.tenantName || null;
        this._selectTenant(tenantId || null, tenantName || 'All Tenants');
      });
    });
  }
}

if (!customElements.get('loki-tenant-switcher')) {
  customElements.define('loki-tenant-switcher', LokiTenantSwitcher);
}

export default LokiTenantSwitcher;

/**
 * @fileoverview Loki Tool Insights Component - displays tool token usage
 * per origin (native, MCP, custom). Inspired by Kiro CLI /tools command
 * that shows estimated token counts for each tool and totals per origin.
 *
 * Shows:
 * - Token cost per tool definition (schema size)
 * - Per-origin totals (native tools, MCP servers)
 * - Tool call frequency and success rates
 * - Warnings for tools with large descriptions (>10K chars)
 *
 * @example
 * <loki-tool-insights api-url="http://localhost:57374" theme="dark"></loki-tool-insights>
 */

import { LokiElement } from '../core/loki-theme.js';
import { getApiClient } from '../core/loki-api-client.js';
import { registerPoll } from '../core/loki-poll-registry.js';

export class LokiToolInsights extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'theme'];
  }

  constructor() {
    super();
    this._data = null;
    this._api = null;
    this._pollInterval = null;
    this._activeView = 'overview';
  }

  connectedCallback() {
    super.connectedCallback();
    this._setupApi();
    this._loadData();
    this._startPolling();
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this._stopPolling();
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) return;
    if (name === 'api-url' && this._api) {
      this._api = getApiClient({ baseUrl: newValue });
      this._loadData();
    }
    if (name === 'theme') {
      this._applyTheme();
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });
  }

  _startPolling() {
    // Central registry (core/loki-poll-registry.js) gates this poll to the
    // active + visible section in ONE place, so a hidden tab or background
    // section does not fetch. connectedCallback already did the first load,
    // so immediate is disabled to avoid a duplicate fetch.
    this._poll = registerPoll({
      loadFn: () => this._loadData(),
      intervalMs: 30000,
      element: this,
      immediate: false,
    });
  }

  _stopPolling() {
    if (this._poll) {
      this._poll.stop();
      this._poll = null;
    }
  }

  async _loadData() {
    // Drop a stale response if the api-url switched mid-flight.
    const api = this._api;
    try {
      const [toolsRes, metricsRes] = await Promise.allSettled([
        api.get('/api/tools'),
        api.get('/api/metrics/tools'),
      ]);
      if (api !== this._api) return;

      this._data = {
        tools: toolsRes.status === 'fulfilled' ? toolsRes.value : null,
        metrics: metricsRes.status === 'fulfilled' ? metricsRes.value : null,
      };
      this._render();
    } catch (e) {
      if (api !== this._api) return;
      this._data = null;
      this._render();
    }
  }

  _estimateTokens(tool) {
    // Rough estimate: 1 token per 4 characters of schema/description
    const descLen = (tool.description || '').length;
    const schemaLen = JSON.stringify(tool.input_schema || tool.schema || {}).length;
    return Math.ceil((descLen + schemaLen) / 4);
  }

  // Escape untrusted strings (tool names, origins, descriptions from the API)
  // before interpolating into innerHTML to prevent XSS.
  _escapeHtml(str) {
    if (str == null) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  _render() {
    const data = this._data;
    const v = this._themeVars || {};

    if (!data || !data.tools) {
      this.shadowRoot.innerHTML = `
        <style>
          :host { display: block; font-family: var(--font-mono, monospace); }
          .container { padding: 16px; color: ${v.textColor || '#c9d1d9'}; background: ${v.bgColor || '#0d1117'}; border-radius: 8px; }
          .muted { color: ${v.mutedColor || '#8b949e'}; }
        </style>
        <div class="container">
          <h3>Tool Insights</h3>
          <p class="muted">Loading tool data...</p>
        </div>
      `;
      return;
    }

    const tools = Array.isArray(data.tools) ? data.tools : (data.tools.tools || []);
    const metrics = data.metrics || {};

    // Group by origin
    const grouped = {};
    let totalTokens = 0;
    const warnings = [];

    for (const tool of tools) {
      const origin = tool.origin || tool.source || 'native';
      if (!grouped[origin]) grouped[origin] = { tools: [], tokens: 0 };
      const tokens = this._estimateTokens(tool);
      totalTokens += tokens;
      grouped[origin].tools.push({ ...tool, estimatedTokens: tokens });
      grouped[origin].tokens += tokens;

      // Warn for large descriptions (Kiro pattern: >10K chars)
      const totalLen = (tool.description || '').length + JSON.stringify(tool.input_schema || {}).length;
      if (totalLen > 10000) {
        warnings.push(`${tool.name}: description exceeds 10K chars (${totalLen} chars). May impact performance.`);
      }
    }

    // Build origin rows
    let originRows = '';
    for (const [origin, group] of Object.entries(grouped).sort((a, b) => b[1].tokens - a[1].tokens)) {
      const pct = totalTokens > 0 ? Math.round(group.tokens / totalTokens * 100) : 0;
      const barWidth = Math.max(1, Math.round(pct / 2));
      const bar = '='.repeat(barWidth);

      originRows += `
        <div class="origin-row" data-origin="${this._escapeHtml(origin)}">
          <div class="origin-header" onclick="this.parentElement.classList.toggle('expanded')">
            <span class="origin-name">${this._escapeHtml(origin)}</span>
            <span class="origin-count">${group.tools.length} tools</span>
            <span class="origin-tokens">${(group.tokens ?? 0).toLocaleString()} tokens</span>
            <span class="origin-bar"><span class="bar-fill" style="width:${pct}%"></span></span>
            <span class="origin-pct">${pct}%</span>
          </div>
          <div class="origin-tools">
            ${group.tools.map(t => `
              <div class="tool-row ${t.estimatedTokens > 2500 ? 'tool-large' : ''}">
                <span class="tool-name">${this._escapeHtml(t.name)}</span>
                <span class="tool-tokens">${t.estimatedTokens} tokens</span>
                <span class="tool-desc">${this._escapeHtml((t.description || '').substring(0, 80))}${(t.description || '').length > 80 ? '...' : ''}</span>
              </div>
            `).join('')}
          </div>
        </div>
      `;
    }

    // Warnings section
    let warningHtml = '';
    if (warnings.length > 0) {
      warningHtml = `
        <div class="warnings">
          <h4>Warnings</h4>
          ${warnings.map(w => `<div class="warning-item">${this._escapeHtml(w)}</div>`).join('')}
        </div>
      `;
    }

    // Tool call metrics (if available)
    let metricsHtml = '';
    const toolMetrics = metrics.tool_calls || metrics.calls || {};
    if (Object.keys(toolMetrics).length > 0) {
      const sorted = Object.entries(toolMetrics).sort((a, b) => (b[1].count || b[1]) - (a[1].count || a[1]));
      metricsHtml = `
        <div class="metrics-section">
          <h4>Tool Call Frequency</h4>
          ${sorted.slice(0, 15).map(([name, data]) => {
            const count = typeof data === 'number' ? data : data.count || 0;
            const success = typeof data === 'object' ? (data.success_rate || data.success || 100) : 100;
            return `
              <div class="metric-row">
                <span class="metric-name">${this._escapeHtml(name)}</span>
                <span class="metric-count">${count} calls</span>
                <span class="metric-success" style="color: ${success >= 90 ? '#3fb950' : success >= 70 ? '#d29922' : '#f85149'}">${success}%</span>
              </div>
            `;
          }).join('')}
        </div>
      `;
    }

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; font-family: var(--font-mono, 'SF Mono', monospace); font-size: 13px; }
        .container { padding: 16px; color: ${v.textColor || '#c9d1d9'}; background: ${v.bgColor || '#0d1117'}; border-radius: 8px; border: 1px solid ${v.borderColor || '#30363d'}; }
        h3 { margin: 0 0 12px 0; font-size: 14px; color: ${v.headingColor || '#f0f6fc'}; }
        h4 { margin: 16px 0 8px 0; font-size: 12px; color: ${v.mutedColor || '#8b949e'}; text-transform: uppercase; letter-spacing: 0.5px; }
        .summary { display: flex; gap: 24px; margin-bottom: 16px; padding-bottom: 12px; border-bottom: 1px solid ${v.borderColor || '#30363d'}; }
        .summary-item { display: flex; flex-direction: column; }
        .summary-label { font-size: 11px; color: ${v.mutedColor || '#8b949e'}; }
        .summary-value { font-size: 18px; font-weight: 600; color: ${v.headingColor || '#f0f6fc'}; }
        .origin-row { margin-bottom: 2px; }
        .origin-header { display: grid; grid-template-columns: 120px 80px 100px 1fr 40px; gap: 8px; align-items: center; padding: 6px 8px; cursor: pointer; border-radius: 4px; transition: background 0.15s; }
        .origin-header:hover { background: ${v.hoverBg || '#161b22'}; }
        .origin-name { font-weight: 600; }
        .origin-count { color: ${v.mutedColor || '#8b949e'}; font-size: 12px; }
        .origin-tokens { text-align: right; }
        .origin-bar { height: 6px; background: ${v.barBg || '#21262d'}; border-radius: 3px; overflow: hidden; }
        .bar-fill { display: block; height: 100%; background: ${v.accentColor || '#58a6ff'}; border-radius: 3px; transition: width 0.3s; }
        .origin-pct { text-align: right; color: ${v.mutedColor || '#8b949e'}; font-size: 12px; }
        .origin-tools { display: none; padding-left: 16px; }
        .origin-row.expanded .origin-tools { display: block; }
        .tool-row { display: grid; grid-template-columns: 180px 80px 1fr; gap: 8px; padding: 3px 8px; font-size: 12px; color: ${v.mutedColor || '#8b949e'}; }
        .tool-row.tool-large .tool-name { color: ${v.warningColor || '#d29922'}; }
        .tool-name { color: ${v.textColor || '#c9d1d9'}; }
        .tool-tokens { text-align: right; }
        .tool-desc { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
        .warnings { margin-top: 12px; padding: 8px 12px; background: ${v.warningBg || '#2d1b00'}; border: 1px solid ${v.warningBorder || '#bb8009'}; border-radius: 6px; }
        .warning-item { font-size: 12px; color: ${v.warningColor || '#d29922'}; padding: 2px 0; }
        .metrics-section { margin-top: 12px; }
        .metric-row { display: grid; grid-template-columns: 180px 80px 50px; gap: 8px; padding: 3px 8px; font-size: 12px; }
        .metric-name { color: ${v.textColor || '#c9d1d9'}; }
        .metric-count { text-align: right; color: ${v.mutedColor || '#8b949e'}; }
        .metric-success { text-align: right; }
        .muted { color: ${v.mutedColor || '#8b949e'}; font-size: 12px; }
      </style>
      <div class="container">
        <h3>Tool Insights</h3>
        <div class="summary">
          <div class="summary-item">
            <span class="summary-label">Total Tools</span>
            <span class="summary-value">${tools.length}</span>
          </div>
          <div class="summary-item">
            <span class="summary-label">Token Overhead</span>
            <span class="summary-value">${totalTokens.toLocaleString()}</span>
          </div>
          <div class="summary-item">
            <span class="summary-label">Origins</span>
            <span class="summary-value">${Object.keys(grouped).length}</span>
          </div>
        </div>
        ${originRows}
        ${warningHtml}
        ${metricsHtml}
        <p class="muted">Token counts are estimates based on schema size. Actual usage varies.</p>
      </div>
    `;
  }
}

customElements.define('loki-tool-insights', LokiToolInsights);

/**
 * @fileoverview Loki Wiki Browser - R5 auto-wiki + cited codebase Q&A panel
 * (Loki's answer to Devin DeepWiki). Browses the per-project wiki generated by
 * `loki wiki generate` (GET /api/wiki, /api/wiki/{section}) and runs the
 * grounded Q&A flow (POST /api/wiki/ask). Every answer and section shows
 * file:line citations that point at real source code.
 *
 * @example
 * <loki-wiki-browser api-url="http://localhost:57374" theme="dark"></loki-wiki-browser>
 */

import { LokiElement } from '../core/loki-theme.js';
import { getApiClient } from '../core/loki-api-client.js';
import { renderMarkdown, MARKDOWN_STYLES } from '../core/loki-markdown.js';

/** @type {Array<{id: string, label: string}>} Wiki section tabs plus the Ask tab. */
const TABS = [
  { id: 'overview', label: 'Overview' },
  { id: 'architecture', label: 'Architecture' },
  { id: 'modules', label: 'Key Modules' },
  { id: 'data-flow', label: 'Data Flow' },
  { id: 'ask', label: 'Ask' },
];

/**
 * @class LokiWikiBrowser
 * @extends LokiElement
 * @property {string} api-url - API base URL (default: window.location.origin)
 * @property {string} theme - 'light' or 'dark'
 */
export class LokiWikiBrowser extends LokiElement {
  static get observedAttributes() {
    return ['api-url', 'theme'];
  }

  constructor() {
    super();
    this._activeTab = 'overview';
    this._loading = false;
    this._error = null;
    this._api = null;
    this._meta = null; // GET /api/wiki
    this._metaPromise = null; // in-flight GET /api/wiki, awaited by _selectTab
    this._sectionCache = {}; // id -> {title, body, citations} (loaded sections)
    // Per-section state machine: id -> 'loading' | 'loaded' | 'error' | 'empty'.
    // Drives _renderSection so a tab can never get stuck on a spinner: every
    // _loadSection transitions the section out of 'loading' in a finally block.
    this._sectionState = {};
    // Ask state
    this._question = '';
    this._answer = null;
    this._asking = false;
    this._askError = null;
    // Mermaid (lazy-loaded, see _ensureMermaid). null = untried.
    this._mermaid = null;
    this._mermaidPromise = null;
  }

  connectedCallback() {
    super.connectedCallback();
    this._setupApi();
    this._loadMeta();
  }

  disconnectedCallback() {
    if (super.disconnectedCallback) super.disconnectedCallback();
    this._disconnected = true;
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (name === 'api-url' && this._api) {
      this._api = getApiClient({ baseUrl: newValue });
    }
  }

  _setupApi() {
    const apiUrl = this.getAttribute('api-url') || window.location.origin;
    this._api = getApiClient({ baseUrl: apiUrl });
  }

  /**
   * Load the wiki manifest (GET /api/wiki). The in-flight promise is stored on
   * this._metaPromise so _selectTab can await it -- this is the fix for the
   * first-click race where a section fetch was skipped because _meta was not
   * yet resolved, leaving the tab stuck on "Loading section..." forever.
   * @returns {Promise<void>} resolves once _meta is set (or _error on failure).
   */
  _loadMeta() {
    this._loading = true;
    this._error = null;
    this.render();
    const api = this._api;
    this._metaPromise = (async () => {
      try {
        const meta = await api._get('/api/wiki');
        // Drop a stale response if the api-url switched mid-flight.
        if (api !== this._api) return;
        this._meta = meta;
      } catch (e) {
        // Drop a stale response if the api-url switched mid-flight.
        if (api !== this._api) return;
        this._error = (e && e.message) ? e.message : 'Failed to load wiki';
      } finally {
        this._loading = false;
        this.render();
      }
    })();
    return this._metaPromise;
  }

  /**
   * Fetch a wiki section, driving its state machine entry. Always leaves the
   * section in a terminal state ('loaded' or 'error') -- never 'loading' -- so
   * the spinner can never stick. Cached sections short-circuit and stay instant.
   * @param {string} id - section id (architecture | modules | data-flow)
   * @returns {Promise<object>} the section data (or an {error} record).
   */
  async _loadSection(id) {
    if (this._sectionCache[id]) {
      this._sectionState[id] = this._sectionCache[id].error ? 'error' : 'loaded';
      return this._sectionCache[id];
    }
    this._sectionState[id] = 'loading';
    const api = this._api;
    try {
      const data = await api._get(`/api/wiki/${encodeURIComponent(id)}`);
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return this._sectionCache[id] || { error: 'stale' };
      this._sectionCache[id] = data;
      this._sectionState[id] = (data && data.error) ? 'error' : 'loaded';
      return data;
    } catch (e) {
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return this._sectionCache[id] || { error: 'stale' };
      const rec = { error: (e && e.message) || 'load failed' };
      this._sectionCache[id] = rec;
      this._sectionState[id] = 'error';
      return rec;
    }
  }

  /**
   * Switch tabs. For a section tab, this ENSURES the manifest is resolved
   * (awaiting the in-flight _loadMeta promise) before deciding whether to fetch
   * the section, then fetches it if a wiki exists. The fetch + diagram render
   * always end in a terminal state, so the tab can never hang.
   * @param {string} id - tab id
   */
  async _selectTab(id) {
    this._activeTab = id;
    if (id !== 'architecture' && id !== 'modules' && id !== 'data-flow') {
      this.render();
      return;
    }
    // Already loaded -> instant (cache preserved, no refetch, no flicker).
    if (this._sectionCache[id]) {
      this.render();
      return;
    }
    // Show the spinner while we resolve the manifest + fetch the section.
    this._sectionState[id] = 'loading';
    this.render();
    // Wait for the manifest so the generated:false / generated:true decision is
    // real and not a race. If the manifest is still loading on first click, this
    // is exactly the bug we fix: we await it instead of skipping the fetch.
    if (this._metaPromise) {
      try { await this._metaPromise; } catch (_e) { /* handled via _error */ }
    }
    if (this._disconnected || this._activeTab !== id) return;
    // No wiki yet (fresh repo): show the honest not-generated empty state.
    // Do NOT cache it -- _renderSection reads _meta.generated live so the tab
    // self-corrects once a wiki exists. Clear the transient 'loading' state.
    if (!this._meta || !this._meta.generated) {
      delete this._sectionState[id];
      this.render();
      return;
    }
    await this._loadSection(id);
    if (this._disconnected || this._activeTab !== id) return;
    // render() rewrites the panel and then (re-)renders any mermaid diagram for
    // the active section into #wiki-diagram. Failure there degrades to the
    // source + prose, never throws -- so this single render fully settles the tab.
    this.render();
  }

  /**
   * Lazily load mermaid from a SAME-ORIGIN vendored asset (no external CDN, so
   * the dashboard stays offline / air-gapped safe). Resolves to the mermaid API
   * object, or null if it cannot be loaded (caller then degrades to the source).
   * The script is loaded once and cached; concurrent callers share one promise.
   * @returns {Promise<object|null>}
   */
  _ensureMermaid() {
    if (this._mermaid) return Promise.resolve(this._mermaid);
    if (this._mermaidPromise) return this._mermaidPromise;
    this._mermaidPromise = (async () => {
      try {
        // Already present on the page (standalone build may inline it, or a
        // prior load on another component instance).
        if (typeof window !== 'undefined' && window.mermaid) {
          this._mermaid = window.mermaid;
          return this._mermaid;
        }
        if (typeof window === 'undefined' || typeof document === 'undefined') {
          return null;
        }
        const base = (this._api && this._api.baseUrl) || window.location.origin;
        const url = `${base}/assets/mermaid.min.js`;
        await new Promise((resolve, reject) => {
          const existing = document.querySelector('script[data-loki-mermaid]');
          if (existing) {
            existing.addEventListener('load', resolve, { once: true });
            existing.addEventListener('error', reject, { once: true });
            if (window.mermaid) resolve();
            return;
          }
          const s = document.createElement('script');
          s.src = url;
          s.async = true;
          s.setAttribute('data-loki-mermaid', '1');
          s.addEventListener('load', resolve, { once: true });
          s.addEventListener('error', () => reject(new Error('mermaid load failed')), { once: true });
          document.head.appendChild(s);
        });
        this._mermaid = (typeof window !== 'undefined' && window.mermaid) || null;
        return this._mermaid;
      } catch (_e) {
        // Offline / asset missing / load error: degrade gracefully.
        return null;
      }
    })();
    return this._mermaidPromise;
  }

  /**
   * Render the mermaid diagram for a section into #wiki-diagram as an SVG, if a
   * diagram exists and mermaid is available. Any failure (no mermaid, invalid
   * source, parse error) is swallowed -- the fallback code block + prose stay
   * visible. Never throws, never blanks the panel.
   * @param {string} id - section id
   */
  async _maybeRenderDiagram(id) {
    const data = this._sectionCache[id];
    const src = this._diagramSource(data);
    if (!src) return;
    let mermaid;
    try {
      mermaid = await this._ensureMermaid();
    } catch (_e) {
      mermaid = null;
    }
    if (!mermaid || this._disconnected || this._activeTab !== id) return;
    try {
      mermaid.initialize({
        startOnLoad: false,
        // 'strict' strips/escapes HTML in labels, blocking script injection from
        // generated (and therefore untrusted) diagram text.
        securityLevel: 'strict',
        theme: this._mermaidTheme(),
        flowchart: { htmlLabels: false, useMaxWidth: true },
        deterministicIds: true,
      });
      // Validate first so invalid source falls back instead of throwing into the
      // panel. mermaid.parse throws on invalid syntax.
      if (typeof mermaid.parse === 'function') {
        await mermaid.parse(src);
      }
      const renderId = `wiki-mmd-${id}-${Date.now()}`;
      const out = await mermaid.render(renderId, src);
      const svg = out && (out.svg || out); // v10 returns {svg}, older returns string
      if (typeof svg !== 'string' || svg.indexOf('<svg') === -1) return;
      if (this._disconnected || this._activeTab !== id || !this.shadowRoot) return;
      const host = this.shadowRoot.getElementById('wiki-diagram');
      if (host) host.innerHTML = svg;
    } catch (_e) {
      // Invalid mermaid or render error: keep the source fallback already shown.
    }
  }

  /** Map the dashboard theme to a mermaid built-in theme. */
  _mermaidTheme() {
    const t = (this.getAttribute('theme') ||
      (typeof document !== 'undefined' &&
        document.documentElement.getAttribute('data-loki-theme')) || '').toLowerCase();
    return t.includes('dark') ? 'dark' : 'neutral';
  }

  async _ask() {
    const q = (this._question || '').trim();
    if (!q) return;
    this._asking = true;
    this._askError = null;
    this._answer = null;
    this.render();
    const api = this._api;
    try {
      // The ask endpoint shells out to claude (and may rebuild the index on a
      // cold repo), so it can take minutes. Use a 200s client timeout, longer
      // than the server's 180s cap, so the server -- not the client -- decides
      // when to give up. The default 10s would abort with "Request timeout".
      const answer = await api._post('/api/wiki/ask', { question: q },
        { timeout: 200000 });
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      this._answer = answer;
    } catch (e) {
      // Drop a stale response if the api-url switched mid-flight.
      if (api !== this._api) return;
      this._askError = (e && e.message) ? e.message : 'Ask failed';
    } finally {
      this._asking = false;
      this.render();
    }
  }

  /** Escape untrusted text for safe insertion into HTML. */
  _esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  _renderCitations(citations) {
    if (!citations || !citations.length) return '';
    const items = citations.map((c) =>
      `<li><code>${this._esc(c.file)}:${this._esc(c.line)}</code></li>`
    ).join('');
    return `<div class="cites"><strong>Sources:</strong><ul>${items}</ul></div>`;
  }

  /** Branded "no wiki yet" empty state with a copyable generate command. */
  _renderNotGenerated() {
    const bookIcon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg>';
    return `<div class="es">
      <div class="es-icon">${bookIcon}</div>
      <div class="es-title">No wiki generated yet</div>
      <div class="es-desc">Generate a cited codebase wiki to browse architecture, modules, and data flow. Every section links to real file:line locations.</div>
      <div class="es-cmd-row">
        <code class="es-cmd" id="wiki-gen-cmd">loki wiki generate</code>
        <button class="es-copy" id="wiki-gen-copy" title="Copy command" aria-label="Copy command">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>
        </button>
      </div>
    </div>`;
  }

  _renderOverview() {
    const m = this._meta;
    if (!m || !m.generated) {
      return this._renderNotGenerated();
    }
    const secs = (m.sections || []).map((s) =>
      `<li>${this._esc(s.title)} <span class="dim">(${this._esc(s.citation_count)} citations)</span></li>`
    ).join('');
    return `<div class="overview">
      <p><strong>${this._esc(m.project || 'Project')}</strong> wiki -
        ${this._esc(m.file_count || 0)} source files indexed.</p>
      <p class="dim">Generated: ${this._esc(m.generated_at || 'unknown')}</p>
      <ul>${secs}</ul>
    </div>`;
  }

  _renderSection(id) {
    // State machine: loading -> (loaded | error | empty). The not-generated
    // empty state is checked live (never cached) so the tab self-corrects once a
    // wiki exists / _meta resolves. While the manifest is still resolving on a
    // first click we keep showing the spinner (terminal states clear it).
    const state = this._sectionState[id];
    if (state === 'loading') {
      return `<div class="es-loading"><span class="es-spinner"></span> Loading section...</div>`;
    }
    if (!this._meta || !this._meta.generated) {
      return this._renderNotGenerated();
    }
    const data = this._sectionCache[id];
    if (!data) return `<div class="es-loading"><span class="es-spinner"></span> Loading section...</div>`;
    if (data.error) return this._renderError(data.error);
    return `<div class="section">
      <h3>${this._esc(data.title)}</h3>
      ${this._renderDiagram(id, data)}
      <div class="body md-body">${renderMarkdown(data.body)}</div>
      ${this._renderCitations(data.citations)}
    </div>`;
  }

  /**
   * Render the diagram region for a section. The container is filled with an SVG
   * by _maybeRenderDiagram once mermaid resolves; until then (or if there is no
   * diagram / mermaid is unavailable / the source is invalid) it falls back to
   * the mermaid source in a code block so the user always sees the structure.
   * @param {string} id - section id
   * @param {object} data - section payload (may carry a `diagram` field)
   * @returns {string} HTML for the diagram region (empty string if no diagram)
   */
  /**
   * Extract the mermaid source from a section payload. Accepts either a raw
   * mermaid string or a fenced ```mermaid ... ``` block (the generator may emit
   * either), returning the inner mermaid source with the fence stripped.
   * @param {object} data - section payload
   * @returns {string} mermaid source ('' if none)
   */
  _diagramSource(data) {
    let src = data && typeof data.diagram === 'string' ? data.diagram.trim() : '';
    if (!src) return '';
    const fenced = src.match(/^```(?:mermaid)?\s*\n([\s\S]*?)\n```$/);
    if (fenced) src = fenced[1].trim();
    return src;
  }

  _renderDiagram(id, data) {
    const src = this._diagramSource(data);
    if (!src) return '';
    // The rendered SVG (set imperatively after render) lives in #wiki-diagram.
    // The <noscript>-style fallback below is shown until/unless an SVG replaces
    // it, and remains if mermaid is unavailable or the source fails to parse.
    return `<div class="diagram" id="wiki-diagram" data-section="${this._esc(id)}">
      <pre class="diagram-fallback"><code>${this._esc(src)}</code></pre>
    </div>`;
  }

  _renderAsk() {
    let result = '';
    if (this._asking) {
      result = `<div class="es-loading"><span class="es-spinner"></span> Searching the codebase...</div>`;
    } else if (this._askError) {
      result = `<div class="es-inline-error">${this._esc(this._askError)}</div>`;
    } else if (this._answer) {
      const note = this._answer.note
        ? `<p class="dim">${this._esc(this._answer.note)}</p>` : '';
      result = `<div class="answer">
        <div class="body md-body">${renderMarkdown(this._answer.answer || '')}</div>
        ${note}
        ${this._renderCitations(this._answer.citations)}
      </div>`;
    }
    return `<div class="ask">
      <div class="ask-row">
        <input id="wiki-q" type="text" placeholder="Ask about this codebase..."
          value="${this._esc(this._question)}" />
        <button id="wiki-ask-btn">Ask</button>
      </div>
      <p class="dim">Answers are grounded in the indexed codebase and cite real file:line locations.</p>
      ${result}
    </div>`;
  }

  /** Branded error state with a retry button. */
  _renderError(message) {
    const alertIcon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>';
    return `<div class="es">
      <div class="es-icon es-icon-error">${alertIcon}</div>
      <div class="es-title">Couldn't load wiki</div>
      <div class="es-desc">${this._esc(message)}</div>
      <button class="es-cta" id="wiki-retry-btn">Retry</button>
    </div>`;
  }

  _renderBody() {
    if (this._loading) return `<div class="es-loading"><span class="es-spinner"></span> Loading wiki...</div>`;
    if (this._error) return this._renderError(this._error);
    switch (this._activeTab) {
      case 'overview': return this._renderOverview();
      case 'architecture': return this._renderSection('architecture');
      case 'modules': return this._renderSection('modules');
      case 'data-flow': return this._renderSection('data-flow');
      case 'ask': return this._renderAsk();
      default: return this._renderOverview();
    }
  }

  render() {
    if (!this.shadowRoot) return;
    const tabs = TABS.map((t) =>
      `<button class="tab ${t.id === this._activeTab ? 'active' : ''}"
        data-tab="${t.id}">${this._esc(t.label)}</button>`
    ).join('');

    this.shadowRoot.innerHTML = `
      <style>
        ${this.getBaseStyles()}
        ${MARKDOWN_STYLES}
        :host { display: block; }
        .tabs { display: flex; gap: 4px; border-bottom: 1px solid var(--loki-border);
          margin-bottom: 12px; flex-wrap: wrap; }
        .tab { background: none; border: none; padding: 8px 14px; cursor: pointer;
          font-size: 13px; font-family: inherit; color: var(--loki-text-muted);
          border-bottom: 2px solid transparent; transition: color 0.15s ease; }
        .tab:hover { color: var(--loki-text-primary); }
        .tab.active { color: var(--loki-accent); border-bottom-color: var(--loki-accent); }
        /* Chrome for the rendered section / answer document. The markdown itself
           is styled by MARKDOWN_STYLES (.md-body), injected into this root. */
        .body { word-break: break-word;
          background: var(--loki-bg-secondary);
          padding: 14px; border-radius: var(--loki-radius-lg, 5px);
          border: 1px solid var(--loki-border); }
        .cites { margin-top: 10px; font-size: 12px; color: var(--loki-text-secondary); }
        .cites ul { margin: 4px 0 0; padding-left: 18px; }
        code { font-family: var(--loki-font-mono, monospace); font-size: 0.85em;
          background: var(--loki-bg-tertiary); color: var(--loki-text-secondary);
          padding: 1px 5px; border-radius: 3px; }
        .dim { color: var(--loki-text-muted); }
        .overview p, .section p { color: var(--loki-text-secondary); font-size: 13px; }
        h3 { margin-top: 0; color: var(--loki-text-primary); font-size: 15px; }

        /* Mermaid diagram region (theme-aware container; the SVG inherits the
           mermaid theme chosen in _mermaidTheme). Falls back to the source code
           block below if mermaid is unavailable or the source is invalid. */
        .diagram {
          margin: 0 0 12px; padding: 14px; overflow-x: auto;
          background: var(--loki-bg-secondary);
          border: 1px solid var(--loki-border);
          border-radius: var(--loki-radius-lg, 5px);
        }
        .diagram svg { max-width: 100%; height: auto; display: block; margin: 0 auto; }
        .diagram-fallback {
          margin: 0; white-space: pre-wrap; word-break: break-word;
          font-family: var(--loki-font-mono, monospace); font-size: 12px;
          line-height: 1.5; color: var(--loki-text-secondary);
        }
        .diagram-fallback code { background: transparent; padding: 0; color: inherit; }

        /* Branded empty / loading / error states */
        .es {
          display: flex; flex-direction: column; align-items: center;
          text-align: center; padding: 48px 24px; gap: 4px;
        }
        .es-icon {
          width: 44px; height: 44px; display: flex; align-items: center;
          justify-content: center; border-radius: var(--loki-radius-full, 9999px);
          background: var(--loki-accent-muted); color: var(--loki-accent);
          margin-bottom: 14px;
        }
        .es-icon-error { background: var(--loki-error-muted); color: var(--loki-error); }
        .es-icon svg { width: 22px; height: 22px; stroke: currentColor; stroke-width: 2;
          fill: none; stroke-linecap: round; stroke-linejoin: round; }
        .es-title { font-size: 15px; font-weight: 600; color: var(--loki-text-primary); }
        .es-desc { font-size: 13px; color: var(--loki-text-muted); line-height: 1.55;
          max-width: 380px; }
        .es-cmd-row {
          margin-top: 16px; display: inline-flex; align-items: stretch;
          border: 1px solid var(--loki-border); border-radius: var(--loki-radius-md, 4px);
          overflow: hidden; background: var(--loki-bg-secondary);
        }
        .es-cmd {
          font-family: var(--loki-font-mono, monospace); font-size: 13px;
          color: var(--loki-text-primary); background: transparent;
          padding: 9px 14px; border-radius: 0;
        }
        .es-copy {
          display: inline-flex; align-items: center; justify-content: center;
          width: 38px; border: none; border-left: 1px solid var(--loki-border);
          background: var(--loki-bg-tertiary); color: var(--loki-text-secondary);
          cursor: pointer; transition: all 0.15s ease;
        }
        .es-copy:hover { background: var(--loki-bg-hover); color: var(--loki-accent); }
        .es-copy svg { width: 15px; height: 15px; stroke: currentColor; stroke-width: 2;
          fill: none; stroke-linecap: round; stroke-linejoin: round; }
        .es-cta {
          margin-top: 16px; padding: 9px 18px; background: var(--loki-accent);
          color: var(--loki-text-inverse); border: none;
          border-radius: var(--loki-radius-md, 4px); font-size: 13px; font-weight: 500;
          font-family: inherit; cursor: pointer; transition: background 0.15s ease;
        }
        .es-cta:hover { background: var(--loki-accent-hover); }
        .es-loading {
          display: flex; align-items: center; justify-content: center; gap: 8px;
          padding: 40px 16px; color: var(--loki-text-muted); font-size: 13px;
        }
        .es-spinner {
          width: 14px; height: 14px; border: 2px solid var(--loki-border);
          border-top-color: var(--loki-accent); border-radius: 50%;
          animation: es-spin 0.8s linear infinite;
        }
        .es-inline-error {
          margin-top: 10px; padding: 10px 12px; font-size: 12px;
          color: var(--loki-error); background: var(--loki-error-muted);
          border-radius: var(--loki-radius-md, 4px);
        }
        @keyframes es-spin { to { transform: rotate(360deg); } }

        .ask-row { display: flex; gap: 8px; margin-bottom: 8px; }
        #wiki-q { flex: 1; padding: 9px 12px; border: 1px solid var(--loki-border);
          border-radius: var(--loki-radius-md, 4px); font-size: 13px; font-family: inherit;
          background: var(--loki-bg-tertiary); color: var(--loki-text-primary); }
        #wiki-q:focus { outline: none; border-color: var(--loki-border-focus);
          box-shadow: var(--loki-shadow-focus); }
        #wiki-q::placeholder { color: var(--loki-text-muted); }
        #wiki-ask-btn { padding: 9px 18px; border: none; border-radius: var(--loki-radius-md, 4px);
          background: var(--loki-accent); color: var(--loki-text-inverse); cursor: pointer;
          font-size: 13px; font-weight: 500; font-family: inherit; transition: background 0.15s ease; }
        #wiki-ask-btn:hover { background: var(--loki-accent-hover); }
      </style>
      <div class="tabs">${tabs}</div>
      <div class="content">${this._renderBody()}</div>
    `;

    this.shadowRoot.querySelectorAll('.tab').forEach((btn) => {
      btn.addEventListener('click', () => this._selectTab(btn.dataset.tab));
    });
    const input = this.shadowRoot.getElementById('wiki-q');
    if (input) {
      input.addEventListener('input', (e) => { this._question = e.target.value; });
      input.addEventListener('keydown', (e) => { if (e.key === 'Enter') this._ask(); });
    }
    const askBtn = this.shadowRoot.getElementById('wiki-ask-btn');
    if (askBtn) {
      askBtn.addEventListener('click', () => this._ask());
    }
    const copyBtn = this.shadowRoot.getElementById('wiki-gen-copy');
    if (copyBtn) {
      copyBtn.addEventListener('click', () => this._copyGenerateCmd(copyBtn));
    }
    const retryBtn = this.shadowRoot.getElementById('wiki-retry-btn');
    if (retryBtn) {
      retryBtn.addEventListener('click', () => {
        this._sectionCache = {};
        this._sectionState = {};
        this._loadMeta();
      });
    }
    // If the active section is a loaded diagram-bearing section, (re-)render the
    // SVG -- render() rewrites innerHTML back to the source fallback each time,
    // so we re-hydrate the visual on every render of a cached section. Guarded
    // so it is a no-op when there is no diagram or mermaid is unavailable.
    const t = this._activeTab;
    if ((t === 'architecture' || t === 'data-flow') &&
        this._sectionCache[t] && !this._sectionCache[t].error &&
        this.shadowRoot.getElementById('wiki-diagram')) {
      this._maybeRenderDiagram(t);
    }
  }

  /** Copy the generate command to the clipboard with a brief confirmation. */
  _copyGenerateCmd(btn) {
    const cmd = 'loki wiki generate';
    const done = () => {
      const original = btn.innerHTML;
      btn.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>';
      setTimeout(() => { btn.innerHTML = original; }, 1500);
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(cmd).then(done).catch(() => {});
    }
  }
}

if (!customElements.get('loki-wiki-browser')) {
  customElements.define('loki-wiki-browser', LokiWikiBrowser);
}

