// loki-markdown.js -- shared, XSS-safe markdown -> HTML renderer for the dashboard.
//
// Every dashboard surface that shows markdown (the Spec panel / generated-prd,
// the How-to-Run USAGE.md panel, the Wiki sections, task descriptions, handoff/
// escalation docs) must render a formatted PREVIEW, not raw markdown with literal
// ``` fences, ** bold markers, and - bullets. This is the single renderer they all
// import so the output is consistent and cannot drift.
//
// SAFETY: the input is escaped FIRST (escapeHtml), then a small set of block +
// inline patterns are applied to the escaped text. No raw HTML from the source can
// reach the DOM, so a malicious spec/wiki/diff string cannot inject script. The
// caller assigns the result via innerHTML into a .md-body container.
//
// SCOPE: intentionally a compact subset (headings, bold/italic, inline code,
// fenced + indented code, ordered + unordered lists incl one level of nesting,
// blockquotes, hr, links, paragraphs). Not a full CommonMark engine -- it covers
// what Loki-generated docs actually contain, with zero external dependency so the
// dashboard stays a self-contained, offline/air-gapped single file.

export function escapeHtml(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// renderMarkdown(md) -> HTML string (safe to assign to innerHTML of a .md-body).
export function renderMarkdown(md) {
  if (md == null || md === '') return '';
  let src = String(md).replace(/\r\n/g, '\n');

  // 1. Pull fenced code blocks out FIRST (before escaping the rest), replacing
  //    them with placeholders, so their contents are not treated as markdown and
  //    are escaped verbatim. Handles ```lang\n...\n``` and bare ```.
  const codeBlocks = [];
  src = src.replace(/```[^\n]*\n([\s\S]*?)```/g, (_, code) => {
    const i = codeBlocks.length;
    codeBlocks.push(`<pre class="md-code"><code>${escapeHtml(code.replace(/\n$/, ''))}</code></pre>`);
    return `�CODEBLOCK${i}�`;
  });

  // 2. Escape everything else.
  let html = escapeHtml(src);

  // 3. Inline code `...` (after escaping; backticks survive escaping).
  html = html.replace(/`([^`\n]+)`/g, (_, c) => `<code class="md-inline-code">${c}</code>`);

  // 4. Links [text](url) -- url is already escaped; only allow http(s)/mailto/relative.
  html = html.replace(/\[([^\]\n]+)\]\(([^)\s]+)\)/g, (m, text, url) => {
    if (/^(https?:|mailto:|\/|#|\.)/.test(url)) {
      return `<a class="md-link" href="${url}" target="_blank" rel="noopener noreferrer">${text}</a>`;
    }
    return m;
  });

  // 5. Block-level pass, line by line, grouping lists + blockquotes + paragraphs.
  const lines = html.split('\n');
  const out = [];
  let para = [];
  let listStack = []; // { tag, indent }
  const flushPara = () => {
    if (para.length) {
      out.push(`<p class="md-p">${para.join('<br>')}</p>`);
      para = [];
    }
  };
  const closeListsTo = (indent) => {
    while (listStack.length && listStack[listStack.length - 1].indent >= indent) {
      out.push(`</${listStack.pop().tag}>`);
    }
  };
  const closeAllLists = () => { while (listStack.length) out.push(`</${listStack.pop().tag}>`); };

  for (let raw of lines) {
    const line = raw;
    const trimmed = line.trim();

    // Code-block placeholder: emit verbatim.
    const cbMatch = trimmed.match(/^�CODEBLOCK(\d+)�$/);
    if (cbMatch) { flushPara(); closeAllLists(); out.push(codeBlocks[Number(cbMatch[1])]); continue; }

    if (trimmed === '') { flushPara(); closeAllLists(); continue; }

    // Headings.
    let h = trimmed.match(/^(#{1,6})\s+(.+)$/);
    if (h) {
      flushPara(); closeAllLists();
      const level = Math.min(h[1].length + 1, 6); // # -> h2 (panels own the h1)
      out.push(`<h${level} class="md-h${level}">${h[2]}</h${level}>`);
      continue;
    }

    // Horizontal rule.
    if (/^(-{3,}|\*{3,}|_{3,})$/.test(trimmed)) { flushPara(); closeAllLists(); out.push('<hr class="md-hr">'); continue; }

    // Blockquote.
    let bq = trimmed.match(/^&gt;\s?(.*)$/);
    if (bq) { flushPara(); closeAllLists(); out.push(`<blockquote class="md-quote">${bq[1]}</blockquote>`); continue; }

    // List items (unordered - * +  / ordered 1. ), with indent for one nest level.
    const indent = line.match(/^(\s*)/)[1].replace(/\t/g, '  ').length;
    let li = trimmed.match(/^([-*+])\s+(.+)$/);
    let oli = trimmed.match(/^(\d+)[.)]\s+(.+)$/);
    if (li || oli) {
      flushPara();
      const tag = oli ? 'ol' : 'ul';
      const text = (li ? li[2] : oli[2]);
      // open/adjust list nesting by indent
      if (!listStack.length || indent > listStack[listStack.length - 1].indent) {
        out.push(`<${tag} class="md-list">`); listStack.push({ tag, indent });
      } else {
        closeListsTo(indent + 1);
        if (!listStack.length) { out.push(`<${tag} class="md-list">`); listStack.push({ tag, indent }); }
      }
      out.push(`<li>${text}</li>`);
      continue;
    }

    // Plain text -> accumulate into a paragraph (close any open list first).
    closeAllLists();
    para.push(line.trim());
  }
  flushPara(); closeAllLists();

  // 6. Inline bold / italic on the assembled HTML (safe: operates on escaped text).
  let result = out.join('\n');
  result = result.replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>');
  result = result.replace(/__([^_\n]+)__/g, '<strong>$1</strong>');
  result = result.replace(/(^|[^*])\*([^*\n]+)\*/g, '$1<em>$2</em>');
  return result;
}

